_pricing_cache = {'data': None, 'loaded_at': 0}
PRICING_CACHE_TTL = 300  # 5 minutes


def load_pricing_settings():
    """Load pricing settings from S3, with caching."""
    import time
    now = time.time()
    if _pricing_cache['data'] and (now - _pricing_cache['loaded_at']) < PRICING_CACHE_TTL:
        return _pricing_cache['data']
    
    try:
        response = s3_client.get_object(Bucket=S3_BUCKET, Key=PRICING_SETTINGS_KEY)
        data = json.loads(response['Body'].read().decode('utf-8'))
        merged = {**DEFAULT_PRICING, **data}
        _pricing_cache['data'] = merged
        _pricing_cache['loaded_at'] = now
        return merged
    except Exception as e:
        print(f"⚠️ Could not load pricing settings: {e}, using defaults")
        _pricing_cache['data'] = DEFAULT_PRICING.copy()
        _pricing_cache['loaded_at'] = now
        return DEFAULT_PRICING.copy()


def save_pricing_settings(settings):
    """Save pricing settings to S3."""
    try:
        s3_client.put_object(
            Bucket=S3_BUCKET,
            Key=PRICING_SETTINGS_KEY,
            Body=json.dumps(settings, indent=2).encode('utf-8'),
            ContentType='application/json'
        )
        _pricing_cache['data'] = settings
        _pricing_cache['loaded_at'] = 0  # Force refresh on next load
        return True
    except Exception as e:
        print(f"❌ Failed to save pricing settings: {e}")
        return False


def get_credit_cost(analysis_type):
    """Get the credit cost for an analysis type from pricing settings."""
    pricing = load_pricing_settings()
    return pricing.get(analysis_type, DEFAULT_PRICING.get(analysis_type, 1))


ROAS_BOOST_FACTOR = 15
ROAS_SAMPLE_SIZE = 10_000_000
US_POPULATION = 329_900_000

def _project_to_us_pop(raw_count):
    """Project a sample UID count to US gen pop estimate."""
    return round(raw_count * ROAS_BOOST_FACTOR / ROAS_SAMPLE_SIZE * US_POPULATION)

def _get_company_pool(data, company_name):
    """Return the company pool dict if the company has one, else None."""
    if not company_name:
        return None
    return data.get('companies', {}).get(company_name)


def _numeric_credits_balance(user):
    """Personal `credits` field on user dict: None/missing → 0; -1 means unlimited."""
    if not user:
        return 0
    c = user.get('credits')
    return 0 if c is None else c


def check_user_credits(username):
    """Check if user has credits remaining.  Returns (has_credits, credits_left).

    Credit model (company users):
      * The company credit pool is the primary source of credits.
      * A per-user ``credit_ceiling`` (-1 = no limit) caps how many credits
        the individual may ever consume from the pool.
      * If a user has a personal ``credits`` override (> 0 or -1), that
        balance is used *instead* of the pool.

    Solo users (no company pool) just use their personal ``credits``.
    """
    data = load_users()
    user = data['users'].get(username)
    if not user:
        return False, 0

    user_credits = _numeric_credits_balance(user)
    user_unlimited = user_credits == -1

    company = (user.get('company') or '').strip()
    pool = _get_company_pool(data, company)

    if pool is not None:
        pool_total = pool.get('credit_pool', 0)
        pool_used  = pool.get('credit_pool_used', 0)
        pool_unlimited  = pool_total == -1
        pool_remaining  = -1 if pool_unlimited else max(pool_total - pool_used, 0)

        has_personal_override = user.get('credit_source') == 'personal'
        if has_personal_override:
            if user_unlimited:
                return True, -1
            return user_credits > 0, user_credits

        ceiling = user.get('credit_ceiling', -1)
        user_used = user.get('credits_used', 0)
        ceiling_remaining = -1 if ceiling == -1 else max(ceiling - user_used, 0)

        if pool_unlimited and ceiling == -1:
            return True, -1
        if pool_unlimited:
            return ceiling_remaining > 0, ceiling_remaining
        if ceiling == -1:
            return pool_remaining > 0, pool_remaining
        effective = min(pool_remaining, ceiling_remaining)
        return effective > 0, effective

    if user_unlimited:
        return True, -1
    return user_credits > 0, user_credits


def has_credits_for(username, amount):
    """Return True if user has at least `amount` credits (or unlimited)."""
    has_credits, credits_left = check_user_credits(username)
    if not has_credits:
        return False
    if credits_left == -1:
        return True
    return credits_left >= amount


def consume_credit(username, description=None, job_id=None, pull_type=None, credits_used=1):
    """Consume credits from user and/or company pool.
    Returns True if successful."""
    data = load_users()
    user = data['users'].get(username)
    if not user:
        return False

    used_at = datetime.now().isoformat()
    entry = {
        'used_at': used_at,
        'description': description or 'Analysis run',
        'job_id': job_id or '',
        'pull_type': pull_type or 'Profile Analysis',
        'credits_used': credits_used
    }

    user_unlimited = _numeric_credits_balance(user) == -1

    company = (user.get('company') or '').strip()
    pool = _get_company_pool(data, company)
    has_personal_override = user.get('credit_source') == 'personal'

    if pool is not None and not has_personal_override:
        pool_total = pool.get('credit_pool', 0)
        pool_used  = pool.get('credit_pool_used', 0)
        pool_unlimited = pool_total == -1
        pool_remaining = -1 if pool_unlimited else (pool_total - pool_used)

        ceiling = user.get('credit_ceiling', -1)
        user_used = user.get('credits_used', 0)
        ceiling_remaining = -1 if ceiling == -1 else (ceiling - user_used)

        if not pool_unlimited and pool_remaining < credits_used:
            return False
        if ceiling != -1 and ceiling_remaining < credits_used:
            return False

        user['credits_used'] = user.get('credits_used', 0) + credits_used
        history = user.setdefault('credit_usage_history', [])
        history.insert(0, entry)
        user['credit_usage_history'] = history[:500]

        if not pool_unlimited:
            pool['credit_pool_used'] = pool.get('credit_pool_used', 0) + credits_used

        save_users(data)
        return True

    if not user_unlimited and _numeric_credits_balance(user) < credits_used:
        return False

    if not user_unlimited:
        user['credits'] = _numeric_credits_balance(user) - credits_used
    user['credits_used'] = user.get('credits_used', 0) + credits_used
    history = user.setdefault('credit_usage_history', [])
    history.insert(0, entry)
    user['credit_usage_history'] = history[:500]

    save_users(data)
    return True

def _normalize_role(role):
    """Treat legacy 'enterprise' as 'user'; only user, admin, super_admin are valid."""
    if role == 'enterprise':
        return 'user'
    return role if role in ('user', 'admin', 'super_admin') else (role or 'user')

# ============================================================================
# AUTHENTICATION DECORATORS
# ============================================================================

# DEV ENVIRONMENT ACCESS CONTROL
# In development mode, only admin and super_admin users can access the site
# This allows testing changes without affecting regular users
ALLOWED_DEV_PATHS = ['/login', '/logout', '/health', '/healthz', '/ready', '/static', '/api/login']

@app.before_request
def check_dev_environment_access():
    """In dev environment, restrict access to admin/super_admin users only."""
    if not IS_DEV_ENV:
        return None  # Production - no restrictions
    
    # Allow health checks and static files without auth
    path = request.path
    if any(path.startswith(allowed) for allowed in ALLOWED_DEV_PATHS):
        return None
    
    # If not logged in, allow through to login page
    if 'username' not in session:
        if path == '/' or path.startswith('/api/'):
            return None  # Let the normal auth flow handle it
        return None
    
    # Check if user is admin or super_admin
    user = get_current_user()
    if user:
        role = _normalize_role(user.get('role', 'user'))
        if role in ('admin', 'super_admin'):
            return None  # Allow access
    
    # Non-admin user trying to access dev site
    return render_template('dev_access_denied.html'), 403

def requires_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'username' not in session:
            # For API endpoints, return JSON error instead of redirect
            if request.path.startswith('/api/'):
                return jsonify({'error': 'Authentication required', 'redirect': '/login'}), 401
            return redirect(url_for('login_page'))
        return f(*args, **kwargs)
    return decorated

def requires_admin(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'username' not in session:
            # For API requests, return JSON error instead of redirect
            if request.path.startswith('/api/'):
                return jsonify({'success': False, 'error': 'Session expired. Please log in again.'}), 401
            return redirect(url_for('login_page'))
        user = get_current_user()
        role = user.get('role', '') if user else ''
        if not user or (role != 'admin' and role != 'super_admin'):
            return jsonify({'success': False, 'error': 'Admin access required'}), 403
        return f(*args, **kwargs)
    return decorated


def requires_super_admin(f):
    """Only super_admin can call this endpoint."""
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'username' not in session:
            if request.path.startswith('/api/'):
                return jsonify({'success': False, 'error': 'Session expired. Please log in again.'}), 401
            return redirect(url_for('login_page'))
        user = get_current_user()
        role = _normalize_role(user.get('role', 'user') if user else '')
        if not user or role != 'super_admin':
            return jsonify({'success': False, 'error': 'Super admin access required'}), 403
        return f(*args, **kwargs)
    return decorated

def requires_purgatory_access(f):
    """Decorator that allows admins, super_admins, and users with purgatory approval access."""
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'username' not in session:
            if request.path.startswith('/api/'):
                return jsonify({'success': False, 'error': 'Session expired. Please log in again.'}), 401
            return redirect(url_for('login_page'))
        user = get_current_user()
        if not user:
            return jsonify({'success': False, 'error': 'User not found'}), 403
        
        role = user.get('role', '')
        has_purgatory_approval = user.get('has_purgatory_approval', False)
        
        # Allow admins, super_admins, or users with purgatory approval
        if role in ['admin', 'super_admin'] or has_purgatory_approval:
            return f(*args, **kwargs)
        
        return jsonify({'success': False, 'error': 'Purgatory access required'}), 403
    return decorated


# Store for job status and results
jobs = {}
OUTPUT_DIR = os.path.join(os.path.dirname(__file__), 'outputs')
os.makedirs(OUTPUT_DIR, exist_ok=True)

# ── Serialize Profile Analysis (run_analysis) ─────────────────────────────────
# One run at a time per Python process / Render replica in FIFO submission order,
# so overlapping universe scans do not saturate ClickHouse. Queued UI message is updated
# when more than zero jobs wait in this process; with multiple replicas, load may still
# fan out unless requests hit one instance — run Render with a single replica for strict global FIFO.
# ============================================================================
# GLOBAL HEAVY-ANALYSIS THROTTLE
# ============================================================================
# All analysis tools that hit ClickHouse hard or run long LLM agent chains
# share a single counting semaphore. Profile Analysis, Subscriber IQ, ROAS IQ,
# Talent Theater, Watch Time, Cross Show, Campaign ROI, Ticket Sales Tracker,
# SF/LF Conversion, Flywheel Conversion, Ecommerce IQ, Talent Search — all of
# them go through `spawn_heavy_analysis()` which acquires one slot before
# running. This prevents the dashboard from thrashing ClickHouse when several
# users / pulls fire at once. Tunable via BG_HEAVY_ANALYSIS_CONCURRENCY.
# ============================================================================
try:
    BG_HEAVY_ANALYSIS_CONCURRENCY = max(1, int(os.environ.get('BG_HEAVY_ANALYSIS_CONCURRENCY', '2')))
except Exception:
    BG_HEAVY_ANALYSIS_CONCURRENCY = 2

_heavy_analysis_semaphore = threading.BoundedSemaphore(BG_HEAVY_ANALYSIS_CONCURRENCY)
_heavy_state_lock = threading.Lock()
_heavy_inflight = {}    # job_id -> {tool, queued_at, started_at, username}
_heavy_waiting = {}     # job_id -> {tool, queued_at, username}


def _heavy_status_snapshot():
    """Best-effort dict of currently-running and currently-waiting heavy jobs."""
    with _heavy_state_lock:
        return {
            'inflight': dict(_heavy_inflight),
            'waiting': dict(_heavy_waiting),
        }


def _safe_ch_throttle_stats():
    """Best-effort snapshot of the cross-tool ClickHouse query semaphore.
    Defined in `migration/clickhouse_connector.py`; the import is wrapped
    so the queue-status endpoint never crashes if the connector module
    isn't importable in some constrained environment (tests, etc.)."""
    try:
        from clickhouse_connector import get_clickhouse_throttle_stats
        return get_clickhouse_throttle_stats()
    except Exception:
        try:
            from migration.clickhouse_connector import get_clickhouse_throttle_stats
            return get_clickhouse_throttle_stats()
        except Exception as e:
            return {'error': f'unavailable: {e}'}


def _heavy_ahead_count(self_job_id=None):
    """How many heavy slots are spoken for ahead of `self_job_id`."""
    with _heavy_state_lock:
        ahead = len(_heavy_inflight) + len(_heavy_waiting)
    if self_job_id and self_job_id in _heavy_waiting:
        ahead = max(0, ahead - 1)
    return ahead


def heavy_analysis_acquire(job_id, tool, username=None):
    """Block until a global heavy-analysis slot is free. Updates job status to
    'queued' with a useful message while waiting. Returns True on success."""
    info = {'tool': tool, 'queued_at': time.time(), 'username': username}
    with _heavy_state_lock:
        _heavy_waiting[job_id] = info

    # Try non-blocking first so the common case (slots free) doesn't show a
    # spurious "Waiting for compute slot" message.
    if _heavy_analysis_semaphore.acquire(blocking=False):
        with _heavy_state_lock:
            _heavy_waiting.pop(job_id, None)
            _heavy_inflight[job_id] = {**info, 'started_at': time.time()}
        return True

    # Slots are full — surface this in the UI before blocking.
    try:
        if job_id and job_id in jobs:
            ahead = _heavy_ahead_count(self_job_id=job_id)
            update_job_status(
                job_id,
                status='queued',
                message=f'Waiting for compute slot ({ahead} heavy run(s) ahead)',
            )
    except Exception:
        pass

    _heavy_analysis_semaphore.acquire()
    with _heavy_state_lock:
        _heavy_waiting.pop(job_id, None)
        _heavy_inflight[job_id] = {**info, 'started_at': time.time()}

    # Flip status back to running once we have a slot, but only if the run
    # function won't immediately do the same. We pass through to the run fn
    # which will set its own status anyway; no-op here is fine.
    return True


def heavy_analysis_release(job_id):
    """Release the global heavy-analysis slot held by `job_id` (idempotent)."""
    with _heavy_state_lock:
        was_inflight = _heavy_inflight.pop(job_id, None) is not None
        _heavy_waiting.pop(job_id, None)
    if was_inflight:
        try:
            _heavy_analysis_semaphore.release()
        except ValueError:
            # Bounded semaphore overshoot — somebody else released first.
            pass


def spawn_heavy_analysis(target, args=(), kwargs=None, *, tool, job_id=None, username=None, daemon=True):
    """Spawn a background thread that runs `target(*args, **kwargs)` only after
    acquiring one slot of the shared heavy-analysis semaphore. Use this in
    place of `threading.Thread(target=run_X, ...)` for any IQ tool that does
    serious ClickHouse or LLM work.

    Returns the started Thread."""
    kwargs = kwargs or {}

    def _runner():
        try:
            heavy_analysis_acquire(job_id, tool, username=username)
        except Exception as e:
            # Failsafe: don't deadlock the UI if acquisition itself blew up.
            print(f"[Heavy Throttle] acquire failed for {tool}/{job_id}: {e}")
        try:
            target(*args, **kwargs)
        finally:
            heavy_analysis_release(job_id)

    t = threading.Thread(target=_runner, daemon=daemon, name=f'heavy-{tool}-{job_id or "x"}')
    t.start()
    return t


_profile_analysis_job_queue = _stdlib_queue.Queue()
_profile_analysis_queue_worker_lock = threading.Lock()
_profile_analysis_queue_workers = []          # list of started worker Threads
_profile_analysis_queue_inflight = set()      # set of job_ids currently executing
_profile_analysis_queue_inflight_lock = threading.Lock()

# Configurable concurrency. The default depends on whether the dispatcher
# is configured:
#   - dispatcher OFF (legacy inline path): default 2 — ClickHouse can
#     handle two concurrent universe scans without thrashing, and any
#     more risks OOM-killing a Render gunicorn worker (BG.py needs
#     50-100 GiB peak per profile).
#   - dispatcher ON: default 15 — workers are essentially idle pollers
#     (they POST a job, sleep 30s, GET status, repeat). The actual
#     concurrency cap is enforced server-side by the dispatcher
#     (MAX_CONCURRENT=15 today, matches the API key pool size).
# Tune via env var BG_PROFILE_QUEUE_WORKERS.
_dispatcher_active = bool((os.environ.get('BG_DISPATCH_URL') or '').strip())
try:
    _default_workers = '15' if _dispatcher_active else '2'
    _PROFILE_QUEUE_WORKERS = max(1, int(os.environ.get('BG_PROFILE_QUEUE_WORKERS', _default_workers)))
except Exception:
    _PROFILE_QUEUE_WORKERS = 15 if _dispatcher_active else 2


def _profile_analysis_queue_worker(worker_id: int):
    """Background consumer: pulls jobs FIFO and runs them. Multiple workers run
    concurrently, but each acquires a shared heavy-analysis slot before
    actually running so Profile Analysis competes fairly with Subscriber IQ /
    ROAS IQ / Talent Theater / etc. for ClickHouse capacity."""
    while True:
        run_fn, run_args, run_kwargs, queued_job_id = _profile_analysis_job_queue.get()
        # Best-effort: who submitted this run? Used for throttle telemetry.
        try:
            username = jobs.get(queued_job_id, {}).get('created_by') if queued_job_id else None
        except Exception:
            username = None
        try:
            # Track in-flight set so /api/queue/status can report queue-level
            # concurrency truthfully. The heavy-throttle in-flight set is
            # tracked separately in _heavy_inflight.
            if queued_job_id:
                with _profile_analysis_queue_inflight_lock:
                    _profile_analysis_queue_inflight.add(queued_job_id)
            # Explicit handoff from queue -> execution so jobs don't appear
            # indefinitely queued if startup work takes time.
            if queued_job_id and queued_job_id in jobs:
                try:
                    if jobs[queued_job_id].get('status') == 'queued':
                        update_job_status(queued_job_id, message='Dequeued — starting run...')
                except Exception:
                    pass
            # Acquire the global heavy-analysis slot. May block if the
            # dashboard is busy with other tools.
            try:
                heavy_analysis_acquire(queued_job_id, 'profile_analysis', username=username)
            except Exception as e:
                print(f"[Queue Worker {worker_id}] heavy slot acquire failed: {e}")
            try:
                run_fn(*run_args, **run_kwargs)
            finally:
                heavy_analysis_release(queued_job_id)
        except Exception as e:
            traceback.print_exc()
            # If the callable fails before it can set its own status (e.g. arg
            # mismatch before entering run_analysis), don't leave the job stuck
            # in queued forever.
            if queued_job_id and queued_job_id in jobs:
                try:
                    update_job_status(
                        queued_job_id,
                        status='failed',
                        progress=100,
                        message='Queue worker failed before analysis start',
                        error=f'Queue worker exception: {e}',
                    )
                except Exception:
                    pass
            # Belt-and-braces: ensure the heavy slot is released even if the
            # run path threw before our finally above fired.
            heavy_analysis_release(queued_job_id)
        finally:
            if queued_job_id:
                with _profile_analysis_queue_inflight_lock:
                    _profile_analysis_queue_inflight.discard(queued_job_id)
            _profile_analysis_job_queue.task_done()


def _ensure_queue_workers_started():
    """Lazily spin up N worker threads on first enqueue."""
    with _profile_analysis_queue_worker_lock:
        # Reap any threads that died (defensive; daemon threads on crash).
        alive = [t for t in _profile_analysis_queue_workers if t.is_alive()]
        _profile_analysis_queue_workers[:] = alive
        while len(_profile_analysis_queue_workers) < _PROFILE_QUEUE_WORKERS:
            wid = len(_profile_analysis_queue_workers) + 1
            wt = threading.Thread(
                target=_profile_analysis_queue_worker,
                args=(wid,),
                daemon=True,
                name=f'profile-analysis-queue-{wid}',
            )
            wt.start()
            _profile_analysis_queue_workers.append(wt)


def enqueue_profile_analysis_run(run_fn, run_args, run_kwargs=None, queued_job_id=None):
    """Queue a profile pipeline. Multiple workers process FIFO concurrently
    (capped by BG_PROFILE_QUEUE_WORKERS). Submissions never block — each call
    returns immediately after putting the job on the queue."""
    run_kwargs = run_kwargs or {}
    _ensure_queue_workers_started()

    _profile_analysis_job_queue.put((run_fn, run_args, run_kwargs, queued_job_id))

    if queued_job_id and queued_job_id in jobs:
        try:
            # Show the user a useful queue-position message. With N workers, the
            # first N submissions start immediately; only the (N+1)th and later
            # see "X ahead" in their status line.
            with _profile_analysis_queue_inflight_lock:
                inflight = len(_profile_analysis_queue_inflight)
            qsz = _profile_analysis_job_queue.qsize()
            ahead = max(0, qsz - 1)
            slots = max(0, _PROFILE_QUEUE_WORKERS - inflight)
            if ahead == 0 and slots > 0:
                # Will be picked up by an idle worker almost immediately.
                pass
            elif ahead > 0:
                update_job_status(queued_job_id, message=f'Queued ({ahead} profile run(s) ahead)')
        except Exception:
            pass


def profile_analysis_run_queue_depth():
    """Rough number of queued (not necessarily running) profile jobs in this process."""
    try:
        return _profile_analysis_job_queue.qsize()
    except Exception:
        return -1


def profile_analysis_inflight_count():
    """Number of profile runs currently executing across the worker pool."""
    with _profile_analysis_queue_inflight_lock:
        return len(_profile_analysis_queue_inflight)


def profile_analysis_inflight_ids():
    with _profile_analysis_queue_inflight_lock:
        return list(_profile_analysis_queue_inflight)


