@app.route('/api/admin/ai-cache/status')
@requires_admin
def ai_cache_status():
    """Get AI cache statistics."""
    ensure_cache_dir()
    cache_files = [f for f in os.listdir(AI_CACHE_DIR) if f.endswith('.json')]
    
    total_size = 0
    cache_entries = []
    
    for f in cache_files:
        filepath = os.path.join(AI_CACHE_DIR, f)
        try:
            stat = os.stat(filepath)
            total_size += stat.st_size
            with open(filepath, 'r') as file:
                data = json.load(file)
                cache_entries.append({
                    'key': f.replace('.json', ''),
                    'cached_at': data.get('cached_at', 'Unknown'),
                    'size': stat.st_size
                })
        except:
            pass
    
    return jsonify({
        'success': True,
        'total_entries': len(cache_files),
        'total_size_kb': round(total_size / 1024, 2),
        'entries': sorted(cache_entries, key=lambda x: x.get('cached_at', ''), reverse=True)[:50]
    })

@app.route('/api/admin/ai-cache/clear', methods=['POST'])
@requires_admin
def ai_cache_clear():
    """Clear all AI cache entries."""
    ensure_cache_dir()
    cache_files = [f for f in os.listdir(AI_CACHE_DIR) if f.endswith('.json')]
    
    cleared = 0
    for f in cache_files:
        try:
            os.remove(os.path.join(AI_CACHE_DIR, f))
            cleared += 1
        except:
            pass
    
    return jsonify({
        'success': True,
        'cleared': cleared
    })


@app.route('/api/admin/genpop-cache/refresh', methods=['POST'])
@requires_admin
def refresh_genpop_cache():
    """Force-refresh in-memory Gen Pop baseline cache from canonical S3 file."""
    try:
        import bg as _bg

        had_cache = getattr(_bg, '_genpop_df_cache', None) is not None
        old_rows = len(_bg._genpop_df_cache) if had_cache and hasattr(_bg._genpop_df_cache, '__len__') else 0

        # Clear in-memory cache and reload from S3 immediately.
        _bg._genpop_df_cache = None
        fresh = _bg._load_genpop_csv()
        if fresh is None:
            return jsonify({
                'success': False,
                'error': 'Could not reload Gen Pop from S3'
            }), 500

        return jsonify({
            'success': True,
            'message': 'Gen Pop cache refreshed',
            'had_cache': bool(had_cache),
            'old_rows': int(old_rows),
            'new_rows': int(len(fresh))
        })
    except Exception as e:
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

