def _llmo_get_genpop_flow_destination_token_sets():
    """Lowercase tokens from Gen Pop for MOST PURCHASED BRANDS vs WHERE THEY SHOP (destination typing)."""
    global _llmo_flow_dest_token_sets_cache
    if _llmo_flow_dest_token_sets_cache is not None:
        return _llmo_flow_dest_token_sets_cache
    import bg
    gp = bg._load_genpop_csv()
    if gp is None:
        _llmo_flow_dest_token_sets_cache = (set(), set())
        return _llmo_flow_dest_token_sets_cache
    g = gp.copy()
    col_cat = g.columns[0]
    col_val = g.columns[1]
    g['_col'] = g[col_cat].astype(str).str.strip().str.upper()
    g['_val'] = g[col_val].astype(str).str.strip().str.lower()
    mpb = set(g.loc[g['_col'] == 'MOST PURCHASED BRANDS', '_val'].dropna().astype(str).str.strip().str.lower())
    wts = set(g.loc[g['_col'] == 'WHERE THEY SHOP', '_val'].dropna().astype(str).str.strip().str.lower())
    mpb = {x for x in mpb if x and x not in ('nan', 'none', '')}
    wts = {x for x in wts if x and x not in ('nan', 'none', '')}
    _llmo_flow_dest_token_sets_cache = (mpb, wts)
    return _llmo_flow_dest_token_sets_cache


def _llmo_flow_destination_brand_retailer_flags(destination):
    """True if any pipe-split destination token appears in Gen Pop MPB and/or WTS lists."""
    mpb, wts = _llmo_get_genpop_flow_destination_token_sets()
    is_brand = False
    is_retailer = False
    for part in _llmo_split_multi_names(destination):
        t = part.strip().lower()
        if not t:
            continue
        if t in mpb:
            is_brand = True
        if t in wts:
            is_retailer = True
    return is_brand, is_retailer


# LLMO: do not surface these COMMON_NAME values (noise / mislabels) in dashboards or aggregates.
_LLMO_TRACKING_NAME_DENYLIST = frozenset({'afc bournemouth', 'chelmico', 'unknown'})


def _llmo_name_excluded_from_tracking(name):
    """True if this entity should be omitted from LLMO rollups (case-insensitive)."""
    if name is None:
        return True
    s = str(name).strip().lower()
    return (not s) or (s in _LLMO_TRACKING_NAME_DENYLIST)


def _llmo_split_multi_names(name):
    """Split COMMON_NAME-style values on '|' into separate entities; empty -> ['Unknown']."""
    if name is None:
        return ['Unknown']
    s = str(name).strip()
    if not s:
        return ['Unknown']
    parts = [p.strip() for p in s.split('|') if p.strip()]
    return parts if parts else ['Unknown']


def _llmo_genpop_lookup_bp_cs(name):
    """Return (penetration_pct, category_share, gp_cat) from Gen Pop for LLM / platform names."""
    import bg as _bg
    gp = _bg._load_genpop_csv()
    if gp is None or not name:
        return None, None, None
    col_name, val_name, bp_name = gp.columns[0], gp.columns[1], gp.columns[2]
    cs_name = gp.columns[3] if len(gp.columns) > 3 else None
    bp = None
    gp_cat = None
    for bc in ('SEARCH ENGINE/AI', 'STREAMING/PLATFORM', None):
        pct, c = _bg.get_genpop_penetration_for_brand(name, brand_category=bc)
        if pct is not None:
            bp, gp_cat = float(pct), c
            break
    if bp is None or gp_cat is None:
        return None, None, None
    cs = None
    if cs_name:
        gp_u = gp.copy()
        gp_u['_col'] = gp_u[col_name].astype(str).str.strip().str.upper()
        gp_u['_val'] = gp_u[val_name].astype(str).str.strip().str.upper()
        cat_u = str(gp_cat).strip().upper()
        for cand in (_bg._extract_core_brand(name, None) or []):
            c = str(cand).strip().upper()
            if not c:
                continue
            mask = (gp_u['_col'] == cat_u) & (gp_u['_val'] == c)
            if mask.any():
                try:
                    raw = gp_u.loc[mask].iloc[0][cs_name]
                    cs = float(pd.to_numeric(raw, errors='coerce'))
                except (TypeError, ValueError, IndexError):
                    cs = None
                if cs is not None and cs == cs:
                    break
        if cs is None:
            bpn = pd.to_numeric(gp_u[bp_name], errors='coerce')
            mask_bp = (gp_u['_col'] == cat_u) & ((bpn - float(bp)).abs() < 1e-4)
            if mask_bp.any():
                try:
                    raw = gp_u.loc[mask_bp].iloc[0][cs_name]
                    cs = float(pd.to_numeric(raw, errors='coerce'))
                except (TypeError, ValueError, IndexError):
                    cs = None
    return bp, cs, gp_cat


def _llmo_enrich_llm_genpop(llm_data):
    """Attach Gen Pop penetration, category share (for doughnut), and index vs GP for each LLM row."""
    if not llm_data:
        return llm_data
    rows = []
    for row in llm_data:
        r = dict(row)
        bp, cs, gp_cat = _llmo_genpop_lookup_bp_cs(r.get('name'))
        r['genpop_penetration'] = round(bp, 4) if bp is not None else None
        r['genpop_category'] = gp_cat
        r['genpop_category_share'] = round(cs, 4) if cs is not None and cs == cs else None
        try:
            pt_f = float(r.get('pct_of_total'))
        except (TypeError, ValueError):
            pt_f = 0.0
        if bp and bp > 0:
            r['index_vs_genpop'] = round((pt_f / float(bp)) * 100, 2)
        else:
            r['index_vs_genpop'] = None
        rows.append(r)
    cs_vals = []
    for r in rows:
        v = r.get('genpop_category_share')
        if v is not None and v == v and v > 0:
            cs_vals.append(float(v))
    tot_cs = sum(cs_vals)
    for r in rows:
        if tot_cs > 0 and r.get('genpop_category_share') is not None:
            try:
                gpcs = float(r['genpop_category_share'])
                r['category_share_genpop_normalized'] = round(gpcs / tot_cs * 100, 2)
            except (TypeError, ValueError):
                r['category_share_genpop_normalized'] = None
        else:
            r['category_share_genpop_normalized'] = None
    return rows


def _llmo_llm_totals_uu_for_dates(summary_data, dates_list):
    """Aggregate unique-user counts per split LLM name across a list of calendar dates."""
    from collections import defaultdict
    agg = defaultdict(int)
    by_date = summary_data.get('by_date', {})
    for d in dates_list:
        day = by_date.get(d) or {}
        for llm in day.get('llms', []):
            uu = llm.get('unique_users', 0)
            for nm in _llmo_split_multi_names(llm.get('name')):
                if _llmo_name_excluded_from_tracking(nm):
                    continue
                agg[nm] += uu
    return dict(agg)


def _llmo_merge_llmo_insights(by_date, matching_dates):
    """Merge per-day llmo_insights (from S3) across a date range."""
    merged = {
        'hourly': [0] * 24,
        'dow': [0] * 7,
        'session_depth_by_llm': {},
        'cross_llm_pairs': [],
        'funnel': {'post1_users': 0, 'post2_users': 0, 'post3_users': 0},
    }
    pair_map = {}
    has_insights = 0
    for d in matching_dates:
        ins = (by_date.get(d) or {}).get('llmo_insights')
        if not isinstance(ins, dict):
            continue
        has_insights += 1
        h = ins.get('hourly') or []
        for i in range(min(24, len(h))):
            merged['hourly'][i] += int(h[i] or 0)
        dow = ins.get('dow') or []
        for i in range(min(7, len(dow))):
            merged['dow'][i] += int(dow[i] or 0)
        sd = ins.get('session_depth') or {}
        for llm, buckets in sd.items():
            if _llmo_name_excluded_from_tracking(llm):
                continue
            if not isinstance(buckets, dict):
                continue
            merged['session_depth_by_llm'].setdefault(llm, {})
            for bk, nv in buckets.items():
                merged['session_depth_by_llm'][llm][bk] = (
                    merged['session_depth_by_llm'][llm].get(bk, 0) + int(nv or 0)
                )
        for p in ins.get('cross_llm_pairs') or []:
            if not isinstance(p, dict):
                continue
            if _llmo_name_excluded_from_tracking(p.get('a')) or _llmo_name_excluded_from_tracking(p.get('b')):
                continue
            key = (p.get('a'), p.get('b'))
            pair_map[key] = pair_map.get(key, 0) + int(p.get('n') or 0)
        fu = ins.get('funnel') or {}
        merged['funnel']['post1_users'] += int(fu.get('post1_users') or 0)
        merged['funnel']['post2_users'] += int(fu.get('post2_users') or 0)
        merged['funnel']['post3_users'] += int(fu.get('post3_users') or 0)
    merged['cross_llm_pairs'] = sorted(
        [{'a': a, 'b': b, 'n': n} for (a, b), n in pair_map.items()],
        key=lambda x: -x['n'],
    )[:25]
    if len(matching_dates) > 1:
        merged['multi_day_note'] = (
            'Hourly/dow are summed session counts. Session depth, funnel, and cross-LLM pair counts sum daily '
            'figures (same user across days may be counted more than once).'
        )
    if has_insights == 0 and len(matching_dates) > 0:
        print(f"[LLMO insights] WARNING: 0/{len(matching_dates)} dates had llmo_insights in S3 summary. "
              "Redeploy SP_LLMO_DAILY and run CALL SP_LLMO_DAILY() to populate.")
    elif has_insights < len(matching_dates):
        print(f"[LLMO insights] {has_insights}/{len(matching_dates)} dates had llmo_insights data.")
    return merged


def _llmo_flow_destination_entropy_and_lift(flow_agg, M):
    """Brand/retailer destination mix and Shannon entropy of destinations per source LLM."""
    import math
    from collections import defaultdict
    src_brand = defaultdict(float)
    src_retail = defaultdict(float)
    src_total = defaultdict(float)
    src_dest = defaultdict(lambda: defaultdict(float))
    for (src, dst), v in flow_agg.items():
        uu = v['uu']
        db, dr = _llmo_flow_destination_brand_retailer_flags(dst)
        src_total[src] += uu
        if db:
            src_brand[src] += uu
        if dr:
            src_retail[src] += uu
        src_dest[src][dst] += uu
    lift = []
    entropy_list = []
    for src in sorted(src_total.keys(), key=lambda s: src_total[s], reverse=True)[:35]:
        t = src_total[src] or 1e-9
        lift.append({
            'source': src,
            'pct_brand_dest': round(src_brand[src] / t * 100, 2),
            'pct_retailer_dest': round(src_retail[src] / t * 100, 2),
            'flow_weighted_users': round(t * M),
        })
        dist = src_dest[src]
        ssum = sum(dist.values())
        h = 0.0
        if ssum > 0:
            for vv in dist.values():
                p = float(vv) / ssum
                if p > 0:
                    h -= p * math.log(p + 1e-15)
        mx = max(dist.values()) if dist else 0
        entropy_list.append({
            'source': src,
            'destination_entropy': round(h, 3),
            'top_dest_share_pct': round(mx / ssum * 100, 2) if ssum else 0,
        })
    entropy_list.sort(key=lambda x: -x.get('destination_entropy', 0))
    return lift, entropy_list[:25]


def _llmo_search_term_insights(search_agg):
    """Diversity of search terms in the selected range (from aggregated term counts)."""
    if not search_agg:
        return {'unique_terms': 0, 'total_term_occurrences': 0, 'avg_occurrences_per_term': 0}
    total = sum(search_agg.values())
    uniq = len(search_agg)
    return {
        'unique_terms': uniq,
        'total_term_occurrences': int(total),
        'avg_occurrences_per_term': round(total / uniq, 2) if uniq else 0,
    }


def _llmo_coverage_metrics(llm_data):
    matched = sum(1 for r in llm_data if r.get('genpop_penetration') is not None)
    n = len(llm_data)
    return {
        'llms_with_genpop_match': matched,
        'llms_total': n,
        'match_pct': round(matched / n * 100, 1) if n else 0,
    }


def _llmo_wow_and_rising(summary_data, matching_dates, llm_totals_cur):
    """Prior-period comparison (same span) and LLM with largest % gain in raw user counts."""
    all_dates = sorted(summary_data.get('dates', []))
    if len(matching_dates) < 1 or len(all_dates) < 2:
        return None, None
    span = len(matching_dates)
    lo = min(matching_dates)
    try:
        i0 = all_dates.index(lo)
    except ValueError:
        return None, None
    if i0 < span:
        return None, None
    prev_dates = all_dates[i0 - span:i0]
    by_date = summary_data.get('by_date', {})
    cur_ai = sum((by_date.get(d) or {}).get('total_ai_users', 0) for d in matching_dates)
    prev_ai = sum((by_date.get(d) or {}).get('total_ai_users', 0) for d in prev_dates)
    prev_llm = _llmo_llm_totals_uu_for_dates(summary_data, prev_dates)
    wow = {
        'prior_period_start': prev_dates[0],
        'prior_period_end': prev_dates[-1],
        'pct_change_ai_users': round((cur_ai - prev_ai) / prev_ai * 100, 2) if prev_ai else None,
        'current_ai_users': cur_ai,
        'previous_ai_users': prev_ai,
    }
    best_name = None
    best_pct = None
    for name, cur_u in (llm_totals_cur or {}).items():
        pv = prev_llm.get(name, 0)
        if pv > 0:
            pct = round((cur_u - pv) / pv * 100, 2)
        else:
            pct = 100.0 if cur_u > 0 else 0.0
        if best_pct is None or pct > best_pct:
            best_pct = pct
            best_name = name
    rising = {'name': best_name, 'pct_change_vs_prior': best_pct} if best_name is not None else None
    return wow, rising


def _llmo_build_extended_insights_payload(
    summary_data, matching_dates, date_str, date_end, flow_agg, search_agg, llm_data, llm_totals_uu,
):
    by_date = summary_data.get('by_date', {})
    M = LLMO_PROJECTION_MULT
    merged = _llmo_merge_llmo_insights(by_date, matching_dates)
    lift, entropy = _llmo_flow_destination_entropy_and_lift(flow_agg, M)
    search_ins = _llmo_search_term_insights(search_agg)
    cov = _llmo_coverage_metrics(llm_data)
    wow, rising = _llmo_wow_and_rising(summary_data, matching_dates, llm_totals_uu)
    return {
        'merged_from_summary': merged,
        'dow_labels': ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
        'llm_brand_retailer_lift': lift,
        'destination_entropy': entropy,
        'search_terms': search_ins,
        'coverage': cov,
        'wow': wow,
        'rising_llm': rising,
        'notes': {
            'demo_by_llm': 'Use the AI agent filter on AI User Demographics to isolate one LLM.',
            'theme_by_llm': 'Search themes aggregate all LLMs; per-LLM theme splits need query→agent linkage in the pipeline.',
            'new_vs_returning': 'First-seen cohort not in summary yet.',
        },
    }


def _llmo_combine_date_range(summary_data, date_str, date_end):
    """Combine pre-computed per-date stats for a date range. Returns API response dict."""
    from collections import defaultdict
    M = LLMO_PROJECTION_MULT
    by_date = summary_data.get('by_date', {})

    matching_dates = sorted(d for d in by_date if d >= date_str and d <= date_end)
    if not matching_dates:
        return {'success': True, 'loading': False, 'date': date_str, 'date_end': date_end,
                'total_unique_users': 0, 'total_unique_users_projected': 0,
                'total_clicks': 0, 'total_clicks_projected': 0,
                'llm_count': 0, 'llms': [], 'attribution': [], 'attribution_second': [],
                'attribution_third': [], 'brand_conversion': [], 'retailer_conversion': [], 'flows': [],
                'searches': [], 'trend_dates': [], 'trend_by_llm': {},
                'browsers': [], 'platforms': [],
                'llmo_extended_insights': {}}

    llm_agg = defaultdict(lambda: {'uu': 0, 'cl': 0})
    att_agg = defaultdict(lambda: {'uu': 0, 'cl': 0})
    att2_agg = defaultdict(lambda: {'uu': 0, 'cl': 0})
    att3_agg = defaultdict(lambda: {'uu': 0, 'cl': 0})
    # Lowercase key -> counts + display label (HOST_MAPPING / MPB case-insensitive)
    brand_conv_agg = {}
    retailer_conv_agg = {}
    flow_agg = defaultdict(lambda: {'uu': 0, 'cl': 0})
    search_agg = defaultdict(int)
    browser_agg = defaultdict(int)
    platform_agg = defaultdict(int)
    total_users = 0
    total_clicks = 0
    trend_by_llm = {}

    for d in matching_dates:
        day = by_date[d]
        total_users += day.get('total_ai_users', 0)
        total_clicks += day.get('total_ai_clicks', 0)

        for llm in day.get('llms', []):
            uu, cl = llm['unique_users'], llm['total_clicks']
            for nm in _llmo_split_multi_names(llm.get('name')):
                if _llmo_name_excluded_from_tracking(nm):
                    continue
                llm_agg[nm]['uu'] += uu
                llm_agg[nm]['cl'] += cl
                if nm not in trend_by_llm:
                    trend_by_llm[nm] = {}
                td = trend_by_llm[nm].setdefault(d, {'unique_users': 0, 'total_clicks': 0})
                td['unique_users'] += round(uu * M)
                td['total_clicks'] += round(cl * M)

        for att in day.get('attribution', []):
            uu, cl = att['unique_users'], att['total_clicks']
            for nm in _llmo_split_multi_names(att.get('name')):
                if _llmo_name_excluded_from_tracking(nm):
                    continue
                att_agg[nm]['uu'] += uu
                att_agg[nm]['cl'] += cl

        for att in day.get('attribution_second', []):
            uu, cl = att['unique_users'], att['total_clicks']
            for nm in _llmo_split_multi_names(att.get('name')):
                if _llmo_name_excluded_from_tracking(nm):
                    continue
                att2_agg[nm]['uu'] += uu
                att2_agg[nm]['cl'] += cl

        for att in day.get('attribution_third', []):
            uu, cl = att['unique_users'], att['total_clicks']
            for nm in _llmo_split_multi_names(att.get('name')):
                if _llmo_name_excluded_from_tracking(nm):
                    continue
                att3_agg[nm]['uu'] += uu
                att3_agg[nm]['cl'] += cl

        for bc in day.get('brand_conversion', []):
            uu, cl = bc['unique_users'], bc['total_clicks']
            for part in _llmo_split_multi_names(bc.get('name')):
                if _llmo_name_excluded_from_tracking(part):
                    continue
                lk = part.strip().lower()
                if not lk:
                    continue
                if lk not in brand_conv_agg:
                    brand_conv_agg[lk] = {'uu': 0, 'cl': 0, 'display': part.strip()}
                brand_conv_agg[lk]['uu'] += uu
                brand_conv_agg[lk]['cl'] += cl

        for rc in day.get('retailer_conversion', []):
            uu, cl = rc['unique_users'], rc['total_clicks']
            for part in _llmo_split_multi_names(rc.get('name')):
                if _llmo_name_excluded_from_tracking(part):
                    continue
                lk = part.strip().lower()
                if not lk:
                    continue
                if lk not in retailer_conv_agg:
                    retailer_conv_agg[lk] = {'uu': 0, 'cl': 0, 'display': part.strip()}
                retailer_conv_agg[lk]['uu'] += uu
                retailer_conv_agg[lk]['cl'] += cl

        for fl in day.get('flows', []):
            src_parts = [p for p in _llmo_split_multi_names(fl.get('source')) if not _llmo_name_excluded_from_tracking(p)]
            dst_parts = [p for p in _llmo_split_multi_names(fl.get('destination')) if not _llmo_name_excluded_from_tracking(p)]
            uu, cl = fl['unique_users'], fl['clicks']
            if not src_parts or not dst_parts:
                continue
            n_pairs = max(1, len(src_parts) * len(dst_parts))
            w = 1.0 / n_pairs
            for s in src_parts:
                for t in dst_parts:
                    flow_agg[(s, t)]['uu'] += uu * w
                    flow_agg[(s, t)]['cl'] += cl * w

        for s in day.get('searches', []):
            search_agg[s['term']] += s['count']

        for b in day.get('browsers', []):
            browser_agg[b['name']] += b['unique_users']

        for p in day.get('platforms', []):
            platform_agg[p['name']] += p['unique_users']

    llm_totals_uu = {name: v['uu'] for name, v in llm_agg.items()}

    total_clicks_all = sum(v['cl'] for v in llm_agg.values())
    llm_sorted = sorted(llm_agg.items(), key=lambda x: x[1]['uu'], reverse=True)
    llm_data = []
    for rank, (name, v) in enumerate(llm_sorted, 1):
        uu, cl = v['uu'], v['cl']
        llm_data.append({
            'rank': rank, 'name': name,
            'unique_users': uu, 'unique_users_projected': round(uu * M),
            'pct_of_total': round(uu / total_users * 100, 2) if total_users else 0,
            'total_clicks': cl, 'total_clicks_projected': round(cl * M),
            'category_share': round(cl / total_clicks_all * 100, 2) if total_clicks_all else 0,
            # Sessions per unique user for this AI platform (range aggregate; same as total_sessions / unique_users)
            'avg_sessions_per_user': round(cl / uu, 2) if uu else 0,
        })

    llm_data = _llmo_enrich_llm_genpop(llm_data)

    att_sorted = sorted(att_agg.items(), key=lambda x: x[1]['uu'], reverse=True)[:100]
    attribution = [{'name': n, 'unique_users': v['uu'], 'unique_users_projected': round(v['uu'] * M),
                    'total_clicks': v['cl'], 'total_clicks_projected': round(v['cl'] * M)}
                   for n, v in att_sorted]

    att2_sorted = sorted(att2_agg.items(), key=lambda x: x[1]['uu'], reverse=True)[:100]
    attribution_second = [{'name': n, 'unique_users': v['uu'], 'unique_users_projected': round(v['uu'] * M),
                          'total_clicks': v['cl'], 'total_clicks_projected': round(v['cl'] * M)}
                         for n, v in att2_sorted]

    att3_sorted = sorted(att3_agg.items(), key=lambda x: x[1]['uu'], reverse=True)[:100]
    attribution_third = [{'name': n, 'unique_users': v['uu'], 'unique_users_projected': round(v['uu'] * M),
                         'total_clicks': v['cl'], 'total_clicks_projected': round(v['cl'] * M)}
                        for n, v in att3_sorted]

    total_brand_uu = sum(v['uu'] for v in brand_conv_agg.values()) if brand_conv_agg else 0
    bc_sorted = sorted(brand_conv_agg.items(), key=lambda x: x[1]['uu'], reverse=True)[:100]
    brand_conversion = [{
        'name': v['display'],
        'unique_users': v['uu'], 'unique_users_projected': round(v['uu'] * M),
        'total_clicks': v['cl'], 'total_clicks_projected': round(v['cl'] * M),
        'pct_of_ai_users': round(v['uu'] / total_users * 100, 2) if total_users else 0,
        # Share of brand-conversion volume (sum of per-brand UUs in range) — same construction as retailer category_share
        'category_share': round(v['uu'] / total_brand_uu * 100, 2) if total_brand_uu else 0,
    } for _, v in bc_sorted]
    brand_conversion = _llmo_enrich_brand_conversion_rows(brand_conversion)

    total_retailer_uu = sum(v['uu'] for v in retailer_conv_agg.values()) if retailer_conv_agg else 0
    rt_sorted = sorted(retailer_conv_agg.items(), key=lambda x: x[1]['uu'], reverse=True)[:100]
    retailer_conversion = [{
        'name': v['display'],
        'unique_users': v['uu'], 'unique_users_projected': round(v['uu'] * M),
        'total_clicks': v['cl'], 'total_clicks_projected': round(v['cl'] * M),
        'pct_of_ai_users': round(v['uu'] / total_users * 100, 2) if total_users else 0,
        # Share of retailer-conversion volume (unique users) across the selected range — sums to 100% over full agg
        'category_share': round(v['uu'] / total_retailer_uu * 100, 2) if total_retailer_uu else 0,
    } for _, v in rt_sorted]
    retailer_conversion = _llmo_enrich_retailer_conversion_rows(retailer_conversion)

    # More rows so UI can filter by destination category without emptying the list
    flow_sorted = sorted(flow_agg.items(), key=lambda x: x[1]['uu'], reverse=True)[:500]
    flows = []
    for k, v in flow_sorted:
        src, dst = k[0], k[1]
        db, dr = _llmo_flow_destination_brand_retailer_flags(dst)
        flows.append({
            'source': src,
            'destination': dst,
            'unique_users': round(v['uu'] * M),
            'clicks': round(v['cl'] * M),
            'dest_brand': db,
            'dest_retailer': dr,
        })

    search_sorted = sorted(search_agg.items(), key=lambda x: x[1], reverse=True)[:100]
    searches = [{'term': t, 'count': round(c * M)} for t, c in search_sorted]

    browsers = [{'name': n, 'unique_users': round(u * M)} for n, u in sorted(browser_agg.items(), key=lambda x: x[1], reverse=True)]
    platforms = [{'name': n, 'unique_users': round(u * M)} for n, u in sorted(platform_agg.items(), key=lambda x: x[1], reverse=True)]

    llmo_extended_insights = _llmo_build_extended_insights_payload(
        summary_data, matching_dates, date_str, date_end, flow_agg, search_agg, llm_data, llm_totals_uu,
    )

    return {
        'success': True, 'loading': False,
        'date': date_str, 'date_end': date_end,
        'total_unique_users': total_users,
        'total_unique_users_projected': round(total_users * M),
        'total_clicks': total_clicks,
        'total_clicks_projected': round(total_clicks * M),
        'llm_count': len(llm_data), 'llms': llm_data,
        'attribution': attribution,
        'attribution_second': attribution_second,
        'attribution_third': attribution_third,
        'brand_conversion': brand_conversion,
        'retailer_conversion': retailer_conversion,
        'flows': flows,
        'searches': searches,
        'trend_dates': matching_dates, 'trend_by_llm': trend_by_llm,
        'browsers': browsers, 'platforms': platforms,
        'llmo_extended_insights': llmo_extended_insights,
    }


# --- LLMO: AI search theme rollup (noise + PII filter, OpenAI clustering) ---
LLMO_PII_THEME = 'Personal Information Query'
_LLM_SEARCH_NOISE_EXACT = frozenset({
    'chatgpt', 'chat gpt', 'gpt', 'openai', 'claude', 'claude ai', 'perplexity', 'gemini',
    'google gemini', 'bard', 'copilot', 'microsoft copilot', 'deepseek', 'meta ai',
    'login', 'logout', 'sign in', 'sign up', 'home', 'search', 'help', 'settings',
    'fs', 'none', 'pending', 'consent', 'select_account', 'null', 'undefined', 'na', 'n/a',
    'api', 'cdn', 'www', 'chat', 'gpt-4', 'gpt 4', 'gpt4', 'new chat', 'new thread',
    'openai.com', 'chatgpt.com',
})
_LLM_SEARCH_PII_EMAIL = re.compile(
    r'\b[A-Za-z0-9][A-Za-z0-9._%+-]{0,63}@[A-Za-z0-9][A-Za-z0-9.-]{0,252}\.[A-Za-z]{2,}\b'
)
_LLM_SEARCH_PII_PHONE = re.compile(
    r'\b(?:\+?1[-.\s]?)?(?:\(\s*\d{3}\s*\)|\d{3})[-.\s]?\d{3}[-.\s]?\d{4}\b'
)
_LLM_SEARCH_PII_SSN = re.compile(r'\b\d{3}-\d{2}-\d{4}\b')


def _llmo_search_term_has_pii(term):
    if not term or not isinstance(term, str):
        return False
    if _LLM_SEARCH_PII_EMAIL.search(term):
        return True
    if _LLM_SEARCH_PII_SSN.search(term):
        return True
    if _LLM_SEARCH_PII_PHONE.search(term):
        return True
    return False


def _llmo_search_term_is_noise(term):
    """Drop navigational / one-word brand stubs / URLs / OAuth-style tokens."""
    if not term or not isinstance(term, str):
        return True
    t = term.strip()
    if not t:
        return True
    low = t.lower()
    if low.startswith('http://') or low.startswith('https://'):
        return True
    norm_ws = re.sub(r'\s+', ' ', low).strip()
    norm_alnum = re.sub(r'[^a-z0-9\s]', '', norm_ws)
    if norm_alnum in _LLM_SEARCH_NOISE_EXACT:
        return True
    words = norm_ws.split()
    if len(t) < 8:
        return True
    if len(t) < 12 and len(words) < 3:
        return True
    if re.fullmatch(r'[a-z][a-z0-9_-]{1,40}', low.replace('-', '_')) and '_' in low.replace('-', '_'):
        return True
    if re.fullmatch(r'[a-z][a-z0-9_]{2,35}', low) and '_' in low:
        return True
    return False


def _llmo_extract_json_from_llm_text(text):
    if not text:
        return None
    raw = text.strip()
    m = re.search(r'```(?:json)?\s*(\{.*?\})\s*```', raw, re.DOTALL)
    if m:
        try:
            return json.loads(m.group(1))
        except json.JSONDecodeError:
            pass
    try:
        i = raw.index('{')
        j = raw.rindex('}') + 1
        return json.loads(raw[i:j])
    except (ValueError, json.JSONDecodeError):
        return None


def _llmo_search_themes_cache_dir():
    ensure_cache_dir()
    d = os.path.join(AI_CACHE_DIR, 'llmo_search_themes')
    os.makedirs(d, exist_ok=True)
    return d


def _llmo_build_search_themes_payload(searches, date_str, date_end):
    """Returns dict for API: categories with pct + examples, meta."""
    from collections import defaultdict

    pii_weight = 0
    kept = []
    for s in searches or []:
        term = (s.get('term') or '').strip()
        try:
            cnt = int(round(float(s.get('count', 0))))
        except (TypeError, ValueError):
            cnt = 0
        if not term or cnt <= 0:
            continue
        if _llmo_search_term_has_pii(term):
            pii_weight += cnt
            continue
        if _llmo_search_term_is_noise(term):
            continue
        kept.append({'term': term[:800], 'count': cnt})

    total_weight = pii_weight + sum(x['count'] for x in kept)
    if total_weight <= 0:
        return {
            'success': True,
            'categories': [],
            'meta': {
                'total_weight': 0, 'pii_weight': 0, 'queries_sent_to_model': 0,
                'message': 'No qualifying searches after PII/noise filters.',
            },
        }

    client = get_openai_client()
    if not client:
        return {
            'success': False,
            'error': 'OpenAI not configured (OPENAI_API_KEY). Theme rollup requires the API.',
            'categories': [],
            'meta': {'total_weight': total_weight, 'pii_weight': pii_weight},
        }

    theme_weight = defaultdict(int)
    if pii_weight > 0:
        theme_weight[LLMO_PII_THEME] = pii_weight

    theme_examples = defaultdict(list)
    assignments = {}

    batch_size = max(20, min(LLMO_SEARCH_THEMES_BATCH, 100))
    for start in range(0, len(kept), batch_size):
        batch = kept[start:start + batch_size]
        lines = []
        for i, row in enumerate(batch):
            global_i = start + i
            safe = json.dumps(row['term'], ensure_ascii=False)
            lines.append(f'{global_i}\t{safe}')
        block = '\n'.join(lines)
        sys_msg = (
            'You label analytics search strings from AI chat products. '
            'Each line is INDEX<TAB>JSON-encoded query string. '
            'For each index, assign exactly ONE short theme name in Title Case (2–5 words), e.g. '
            '"Image Generation", "Software Development", "Writing & Editing", "Sports Discussion", '
            '"Current Events", "Education & Homework", "Health & Fitness", "Shopping & Products", '
            '"Entertainment Recommendations", "Humor & Games". '
            f'If the query contains or solicits private personal data (addresses, phones, emails, SSN, doxxing), '
            f'use exactly "{LLMO_PII_THEME}". '
            'Do not copy long slurs or harassment into the theme name—summarize neutrally. '
            'Return ONLY valid JSON: {"items":[{"i":0,"theme":"..."}]} with one entry per input line, same indices.'
        )
        try:
            response = client.chat.completions.create(
                model=LLMO_SEARCH_THEMES_MODEL,
                messages=[
                    {'role': 'system', 'content': sys_msg},
                    {'role': 'user', 'content': f'Classify each query:\n{block}'},
                ],
                max_tokens=4000,
                temperature=0.15,
            )
            content = (response.choices[0].message.content or '').strip()
            parsed = _llmo_extract_json_from_llm_text(content)
            items = (parsed or {}).get('items') or []
            for it in items:
                try:
                    ii = int(it.get('i'))
                    th = (it.get('theme') or 'General Interest').strip()
                    if not th:
                        th = 'General Interest'
                    assignments[ii] = th
                except (TypeError, ValueError):
                    continue
        except Exception as e:
            print(f'[LLMO search themes] OpenAI batch error: {e}')
            traceback.print_exc()
            for i in range(len(batch)):
                assignments[start + i] = 'General Interest'

    for idx, row in enumerate(kept):
        th = assignments.get(idx, 'General Interest')
        if th == LLMO_PII_THEME:
            th = 'General Interest'
        c = row['count']
        theme_weight[th] += c
        if len(theme_examples[th]) < 100:
            theme_examples[th].append(row['term'])

    cats = []
    for theme, w in sorted(theme_weight.items(), key=lambda x: -x[1]):
        pct = round(100.0 * w / total_weight, 2) if total_weight else 0.0
        show_ex = theme != LLMO_PII_THEME
        ex = [] if not show_ex else theme_examples.get(theme, [])[:100]
        cats.append({
            'theme': theme,
            'pct': pct,
            'examples': ex,
            'show_examples': show_ex,
        })

    cats.sort(key=lambda x: (x['theme'] == LLMO_PII_THEME, -x['pct']))

    return {
        'success': True,
        'categories': cats,
        'meta': {
            'total_weight': total_weight,
            'pii_weight': pii_weight,
            'queries_sent_to_model': len(kept),
            'model': LLMO_SEARCH_THEMES_MODEL,
        },
    }


def _llmo_merge_search_theme_daily_payloads(payloads):
    """Merge per-day search_themes objects (from Snowflake summary) into one API payload."""
    from collections import defaultdict
    if not payloads:
        return None
    merged_w = defaultdict(int)
    merged_ex = defaultdict(list)
    seen_q = defaultdict(set)
    models = []
    queries_sent = 0
    for st in payloads:
        if not isinstance(st, dict) or not st.get('success'):
            return None
        meta = st.get('meta') or {}
        mq = meta.get('queries_sent_to_model')
        if mq is not None:
            try:
                queries_sent += int(mq)
            except (TypeError, ValueError):
                pass
        mdl = meta.get('model')
        if mdl:
            models.append(mdl)
        for c in st.get('categories') or []:
            theme = (c.get('theme') or 'General Interest').strip() or 'General Interest'
            w = c.get('weight')
            if w is None:
                return None
            try:
                wint = int(round(float(w)))
            except (TypeError, ValueError):
                return None
            merged_w[theme] += wint
            if theme == LLMO_PII_THEME:
                continue
            for q in (c.get('examples') or [])[:100]:
                qs = str(q).strip()
                if qs and qs not in seen_q[theme] and len(merged_ex[theme]) < 100:
                    seen_q[theme].add(qs)
                    merged_ex[theme].append(qs)
    total_weight = sum(merged_w.values())
    if total_weight <= 0:
        return {
            'success': True,
            'categories': [],
            'meta': {
                'total_weight': 0, 'pii_weight': 0, 'queries_sent_to_model': queries_sent,
                'message': 'No qualifying searches after PII/noise filters.',
                'source': 'summary_merge',
            },
        }
    cats = []
    for theme, w in sorted(merged_w.items(), key=lambda x: -x[1]):
        pct = round(100.0 * w / total_weight, 2)
        show_ex = theme != LLMO_PII_THEME
        ex = [] if not show_ex else merged_ex.get(theme, [])[:100]
        cats.append({
            'theme': theme,
            'pct': pct,
            'examples': ex,
            'show_examples': show_ex,
        })
    cats.sort(key=lambda x: (x['theme'] == LLMO_PII_THEME, -x['pct']))
    return {
        'success': True,
        'categories': cats,
        'meta': {
            'total_weight': total_weight,
            'pii_weight': int(merged_w.get(LLMO_PII_THEME, 0)),
            'queries_sent_to_model': queries_sent,
            'model': models[0] if models else None,
            'source': 'summary_cortex_merged',
            'merged_days': len(payloads),
        },
    }


def _llmo_day_has_search_volume(day_blob):
    """True if summary row has any non-empty search term with positive count."""
    if not isinstance(day_blob, dict):
        return False
    for s in day_blob.get('searches') or []:
        if not isinstance(s, dict):
            continue
        term = (s.get('term') or '').strip()
        if not term:
            continue
        try:
            cnt = int(round(float(s.get('count', 0))))
        except (TypeError, ValueError):
            cnt = 0
        if cnt > 0:
            return True
    return False


def _llmo_try_merge_search_themes_from_summary(summary_data, date_str, date_end):
    """Merge precomputed search_themes for the range when every day is covered.

    - Days with successful ``search_themes`` are merged normally.
    - Days with no search volume may use ``search_themes: null`` (treated as empty success).
    - If any day has searches but missing/failed ``search_themes``, return None (OpenAI path).
    """
    if not summary_data or not isinstance(summary_data.get('by_date'), dict):
        return None
    by_date = summary_data['by_date']
    matching = sorted(d for d in by_date.keys() if isinstance(d, str) and date_str <= d <= date_end)
    if not matching:
        return None
    payloads = []
    for d in matching:
        row = by_date.get(d) or {}
        st = row.get('search_themes')
        if isinstance(st, dict) and st.get('success'):
            payloads.append(st)
            continue
        if not _llmo_day_has_search_volume(row):
            payloads.append({
                'success': True,
                'version': 1,
                'categories': [],
                'meta': {'total_weight': 0, 'pii_weight': 0, 'queries_sent_to_model': 0, 'source': 'no_search_volume'},
            })
            continue
        return None
    return _llmo_merge_search_theme_daily_payloads(payloads)


def _llmo_merge_demographics_days(blobs):
    """Merge multiple single-day demographics blobs by summing counts, recomputing pct.

    Not perfectly deduplicated across days (same user counted per day), but matches
    the behavior noted elsewhere for multi-day metrics.
    """
    if len(blobs) == 1:
        return blobs[0]
    merged_dem = {}
    merged_trend = {}
    for blob in blobs:
        dem = blob.get('demographics') or {}
        for cat, items in dem.items():
            if not isinstance(items, list):
                continue
            if cat not in merged_dem:
                merged_dem[cat] = {}
            for item in items:
                v = item.get('value', '')
                merged_dem[cat][v] = merged_dem[cat].get(v, 0) + (item.get('count') or 0)
        dt = blob.get('demo_trend') or {}
        for cat, by_date in dt.items():
            if not isinstance(by_date, dict):
                continue
            merged_trend.setdefault(cat, {}).update(by_date)
    demographics = {}
    for cat, val_counts in merged_dem.items():
        total = sum(val_counts.values())
        items = sorted(val_counts.items(), key=lambda x: -x[1])
        demographics[cat] = [
            {'value': v, 'count': c, 'pct': round(c / total * 100, 2) if total else 0}
            for v, c in items
        ]
    return {'demographics': demographics, 'demo_trend': merged_trend}


def _llmo_try_demographics_from_summary(summary_data, date_str, date_end, agent=None):
    """Use precomputed demographics from S3 summary.

    Supports single-day and multi-day ranges (sums counts, recomputes pct).
    When ``agent`` is provided, uses ``llmo_demographics_by_agent`` per-day data.
    Falls back to None (live Snowflake) only if precomputed data is missing.
    """
    if not summary_data or not isinstance(summary_data.get('by_date'), dict):
        return None
    by_date = summary_data['by_date']
    matching = sorted(d for d in by_date if isinstance(d, str) and date_str <= d <= date_end)
    if not matching:
        return None

    agent_key = str(agent).strip().lower() if agent else ''

    blobs = []
    for d in matching:
        row = by_date.get(d)
        if not isinstance(row, dict):
            return None
        if agent_key:
            by_agent = row.get('llmo_demographics_by_agent')
            if not isinstance(by_agent, dict):
                return None
            blob = by_agent.get(agent_key)
            if blob is None:
                for k, v in by_agent.items():
                    if agent_key in k or k in agent_key:
                        blob = v
                        break
            if not isinstance(blob, dict):
                return None
        else:
            blob = row.get('llmo_demographics')
            if not isinstance(blob, dict):
                return None
        dem = blob.get('demographics')
        if not isinstance(dem, dict) or not dem:
            return None
        blobs.append(blob)

    merged = _llmo_merge_demographics_days(blobs)
    return {'success': True, 'demographics': merged.get('demographics', {}),
            'demo_trend': merged.get('demo_trend', {})}


@app.route('/api/llmo-iq/search-themes', methods=['GET'])
@requires_auth
def llmo_iq_search_themes():
    """PII/noise-filtered search terms → precomputed summary (Cortex) or OpenAI theme rollup; disk cache."""
    if not _current_user_has_llmo_iq_access():
        return jsonify({'success': False, 'error': 'LLMO IQ access denied'}), 403
    date_str = request.args.get('date') or datetime.now().strftime('%Y-%m-%d')
    date_end = request.args.get('date_end') or date_str

    try:
        summary = _llmo_ensure_loaded()
        if summary is None:
            return jsonify({'success': True, 'loading': True}), 200

        merged = _llmo_try_merge_search_themes_from_summary(summary, date_str, date_end)
        if merged is not None and merged.get('success'):
            return jsonify(merged)

        combined = _llmo_combine_date_range(summary, date_str, date_end)
        searches = combined.get('searches') or []

        cache_key_src = json.dumps(
            {'from': date_str, 'to': date_end, 'searches': searches},
            sort_keys=True,
            default=str,
        )
        cache_h = hashlib.sha256(cache_key_src.encode('utf-8')).hexdigest()[:48]
        cache_path = os.path.join(_llmo_search_themes_cache_dir(), f'{cache_h}.json')

        if os.path.isfile(cache_path):
            try:
                with open(cache_path, 'r', encoding='utf-8') as cf:
                    cached = json.load(cf)
                if isinstance(cached, dict) and cached.get('success'):
                    return jsonify(cached)
            except Exception:
                pass

        payload = _llmo_build_search_themes_payload(searches, date_str, date_end)
        if payload.get('success'):
            try:
                with open(cache_path, 'w', encoding='utf-8') as cf:
                    json.dump(payload, cf, ensure_ascii=False)
            except Exception as wex:
                print(f'[LLMO search themes] cache write: {wex}')

        return jsonify(payload)
    except Exception as e:
        traceback.print_exc()
        print(f'[LLMO search themes] Error: {e}')
        return jsonify({'success': False, 'error': str(e)}), 500


