@app.route('/api/llmo-iq/demographics', methods=['GET'])
@requires_auth
def llmo_iq_demographics():
    """Return demographic breakdown for LLMO users from Snowflake (async load)."""
    if not _current_user_has_llmo_iq_access():
        return jsonify({'success': False, 'error': 'LLMO IQ access denied'}), 403
    import datetime as _dt
    date_str = request.args.get('date')
    date_end = request.args.get('date_end')
    if not date_str:
        date_str = datetime.now().strftime('%Y-%m-%d')
    if not date_end:
        date_end = date_str
    agent = (request.args.get('agent') or '').strip()

    try:
        summary = _llmo_ensure_loaded()
        if summary is None:
            return jsonify({'success': True, 'loading': True}), 200
        from_summary = _llmo_try_demographics_from_summary(summary, date_str, date_end, agent=agent)
        if from_summary is not None:
            return jsonify(from_summary)

        # Live fallback (rare — only hit when the precomputed summary lacks
        # llmo_demographics for the requested range). Native ClickHouse SQL
        # against clickstream.llmo_events + userdata.user_data_sanitized.
        # No Snowflake / Cortex involved.
        conn = _ch_connect()
        cur = conn.cursor()

        agent_filter_sql = "AND lower(trim(COMMON_NAME)) LIKE %(agent)s" if agent else ""
        agent_param = {'agent': f'%{agent.lower()}%'} if agent else {}
        params = {'d1': date_str, 'd2': date_end, **agent_param}

        cur.execute(f"""
            SELECT 'gender' AS cat, d.GENDER AS val, uniqExact(u.UID) AS cnt
            FROM (SELECT DISTINCT UID FROM clickstream.llmo_events
                  WHERE MATCH_TYPE = 'AI_AGENT' AND DELIVERED BETWEEN toDate(%(d1)s) AND toDate(%(d2)s)
                    {agent_filter_sql}) u
            INNER JOIN userdata.user_data_sanitized d ON u.UID = d.UID
            WHERE d.GENDER != '' AND upper(trim(d.GENDER)) NOT IN ('PREFER NOT TO SAY','NONE','N/A')
            GROUP BY d.GENDER
            UNION ALL
            SELECT 'age', d.AGE, uniqExact(u.UID)
            FROM (SELECT DISTINCT UID FROM clickstream.llmo_events
                  WHERE MATCH_TYPE = 'AI_AGENT' AND DELIVERED BETWEEN toDate(%(d1)s) AND toDate(%(d2)s)
                    {agent_filter_sql}) u
            INNER JOIN userdata.user_data_sanitized d ON u.UID = d.UID
            WHERE d.AGE != '' AND upper(trim(d.AGE)) NOT IN ('PREFER NOT TO SAY','NONE','N/A')
            GROUP BY d.AGE
            UNION ALL
            SELECT 'ethnicity', d.ETHNICITY, uniqExact(u.UID)
            FROM (SELECT DISTINCT UID FROM clickstream.llmo_events
                  WHERE MATCH_TYPE = 'AI_AGENT' AND DELIVERED BETWEEN toDate(%(d1)s) AND toDate(%(d2)s)
                    {agent_filter_sql}) u
            INNER JOIN userdata.user_data_sanitized d ON u.UID = d.UID
            WHERE d.ETHNICITY != '' AND upper(trim(d.ETHNICITY)) NOT IN ('PREFER NOT TO SAY','NONE','N/A')
            GROUP BY d.ETHNICITY
            UNION ALL
            SELECT 'income', d.INCOME, uniqExact(u.UID)
            FROM (SELECT DISTINCT UID FROM clickstream.llmo_events
                  WHERE MATCH_TYPE = 'AI_AGENT' AND DELIVERED BETWEEN toDate(%(d1)s) AND toDate(%(d2)s)
                    {agent_filter_sql}) u
            INNER JOIN userdata.user_data_sanitized d ON u.UID = d.UID
            WHERE d.INCOME != '' AND upper(trim(d.INCOME)) NOT IN ('PREFER NOT TO SAY','NONE','N/A')
            GROUP BY d.INCOME
            UNION ALL
            SELECT 'education', d.EDUCATION, uniqExact(u.UID)
            FROM (SELECT DISTINCT UID FROM clickstream.llmo_events
                  WHERE MATCH_TYPE = 'AI_AGENT' AND DELIVERED BETWEEN toDate(%(d1)s) AND toDate(%(d2)s)
                    {agent_filter_sql}) u
            INNER JOIN userdata.user_data_sanitized d ON u.UID = d.UID
            WHERE d.EDUCATION != '' AND upper(trim(d.EDUCATION)) NOT IN ('PREFER NOT TO SAY','NONE','N/A')
            GROUP BY d.EDUCATION
        """, params)
        overall_rows = cur.fetchall()

        cur.execute(f"""
            SELECT 'gender' AS cat, toString(u.d) AS d, d.GENDER AS val, uniqExact(u.UID) AS cnt
            FROM (SELECT DISTINCT UID, DELIVERED AS d FROM clickstream.llmo_events
                  WHERE MATCH_TYPE = 'AI_AGENT' AND DELIVERED BETWEEN toDate(%(d1)s) AND toDate(%(d2)s)
                    {agent_filter_sql}) u
            INNER JOIN userdata.user_data_sanitized d ON u.UID = d.UID
            WHERE d.GENDER != '' AND upper(trim(d.GENDER)) NOT IN ('PREFER NOT TO SAY','NONE','N/A')
            GROUP BY u.d, d.GENDER
            UNION ALL
            SELECT 'age', toString(u.d), d.AGE, uniqExact(u.UID)
            FROM (SELECT DISTINCT UID, DELIVERED AS d FROM clickstream.llmo_events
                  WHERE MATCH_TYPE = 'AI_AGENT' AND DELIVERED BETWEEN toDate(%(d1)s) AND toDate(%(d2)s)
                    {agent_filter_sql}) u
            INNER JOIN userdata.user_data_sanitized d ON u.UID = d.UID
            WHERE d.AGE != '' AND upper(trim(d.AGE)) NOT IN ('PREFER NOT TO SAY','NONE','N/A')
            GROUP BY u.d, d.AGE
            UNION ALL
            SELECT 'ethnicity', toString(u.d), d.ETHNICITY, uniqExact(u.UID)
            FROM (SELECT DISTINCT UID, DELIVERED AS d FROM clickstream.llmo_events
                  WHERE MATCH_TYPE = 'AI_AGENT' AND DELIVERED BETWEEN toDate(%(d1)s) AND toDate(%(d2)s)
                    {agent_filter_sql}) u
            INNER JOIN userdata.user_data_sanitized d ON u.UID = d.UID
            WHERE d.ETHNICITY != '' AND upper(trim(d.ETHNICITY)) NOT IN ('PREFER NOT TO SAY','NONE','N/A')
            GROUP BY u.d, d.ETHNICITY
            UNION ALL
            SELECT 'income', toString(u.d), d.INCOME, uniqExact(u.UID)
            FROM (SELECT DISTINCT UID, DELIVERED AS d FROM clickstream.llmo_events
                  WHERE MATCH_TYPE = 'AI_AGENT' AND DELIVERED BETWEEN toDate(%(d1)s) AND toDate(%(d2)s)
                    {agent_filter_sql}) u
            INNER JOIN userdata.user_data_sanitized d ON u.UID = d.UID
            WHERE d.INCOME != '' AND upper(trim(d.INCOME)) NOT IN ('PREFER NOT TO SAY','NONE','N/A')
            GROUP BY u.d, d.INCOME
            UNION ALL
            SELECT 'education', toString(u.d), d.EDUCATION, uniqExact(u.UID)
            FROM (SELECT DISTINCT UID, DELIVERED AS d FROM clickstream.llmo_events
                  WHERE MATCH_TYPE = 'AI_AGENT' AND DELIVERED BETWEEN toDate(%(d1)s) AND toDate(%(d2)s)
                    {agent_filter_sql}) u
            INNER JOIN userdata.user_data_sanitized d ON u.UID = d.UID
            WHERE d.EDUCATION != '' AND upper(trim(d.EDUCATION)) NOT IN ('PREFER NOT TO SAY','NONE','N/A')
            GROUP BY u.d, d.EDUCATION
        """, params)
        trend_rows = cur.fetchall()
        conn.close()

        cat_data = {}
        for r in overall_rows:
            cat, val, cnt = r
            cat_data.setdefault(cat, []).append((val, cnt))
        demographics = {}
        for cat, items in cat_data.items():
            items.sort(key=lambda x: -x[1])
            total_d = sum(x[1] for x in items)
            demographics[cat] = [{'value': v, 'count': c, 'pct': round(c / total_d * 100, 2) if total_d else 0} for v, c in items]

        trend_data = {}
        for r in trend_rows:
            cat, d, val, cnt = r
            d_str = str(d)
            trend_data.setdefault(cat, {}).setdefault(d_str, []).append({'value': val, 'count': cnt})
        demo_trend = {}
        for cat, by_date in trend_data.items():
            for d_str, items in by_date.items():
                total_d = sum(x['count'] for x in items)
                for x in items:
                    x['pct'] = round(x['count'] / total_d * 100, 2) if total_d else 0
            demo_trend[cat] = by_date

        return jsonify({'success': True, 'demographics': demographics, 'demo_trend': demo_trend})
    except Exception as e:
        import traceback; traceback.print_exc()
        print(f"[LLMO IQ demographics] Error: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


