@app.route('/api/admin/tickers-without-images')
@requires_admin
def get_tickers_without_images():
    """Get list of all tickers that don't have custom images."""
    try:
        # Load all tickers
        tickers_response = list_hedge_fund_tickers()
        tickers_data = tickers_response.get_json()
        
        if not tickers_data.get('success'):
            return jsonify({'success': False, 'error': 'Could not load tickers'}), 500
        
        all_tickers = tickers_data.get('tickers', [])
        
        # Load ticker images cache from S3
        ticker_images = load_json_from_s3(TICKER_IMAGES_FILE)
        
        # Separate tickers with and without images
        tickers_without_images = []
        tickers_with_images = []
        
        for ticker_data in all_tickers:
            ticker = ticker_data['ticker']
            
            if ticker in ticker_images and ticker_images[ticker].get('image_url'):
                tickers_with_images.append({
                    'ticker': ticker,
                    'display_name': ticker_data['display_name'],
                    'kpi': ticker_data['kpi'],
                    'image_url': ticker_images[ticker]['image_url']
                })
            else:
                tickers_without_images.append({
                    'ticker': ticker,
                    'display_name': ticker_data['display_name'],
                    'kpi': ticker_data['kpi']
                })
        
        return jsonify({
            'success': True,
            'without_images': tickers_without_images,
            'with_images': tickers_with_images,
            'total_count': len(all_tickers),
            'missing_count': len(tickers_without_images),
            'has_image_count': len(tickers_with_images)
        })
        
    except Exception as e:
        print(f"Error in get_tickers_without_images: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/admin/tickers-full')
@requires_admin
def get_tickers_full():
    """Get all tickers with images and profile mappings in one call for admin panel."""
    try:
        # Get all tickers
        tickers_response = list_hedge_fund_tickers()
        tickers_data = tickers_response.get_json()
        
        if not tickers_data.get('success'):
            return jsonify({'success': False, 'error': 'Could not load tickers'}), 500
        
        all_tickers = tickers_data.get('tickers', [])
        
        # Load ticker images and profile mappings from S3 (cached)
        ticker_images = load_json_from_s3(TICKER_IMAGES_FILE)
        profile_mappings = load_json_from_s3(TICKER_PROFILES_FILE)
        
        # Enrich each ticker with image and profile data
        enriched_tickers = []
        for ticker_data in all_tickers:
            ticker = ticker_data['ticker']
            
            # Get image info
            has_image = False
            image_url = None
            if ticker in ticker_images and ticker_images[ticker].get('image_url'):
                has_image = True
                image_url = ticker_images[ticker].get('image_url')
            
            # Get profile mappings
            profiles = [ticker]  # Default
            has_custom_profile = False
            if ticker in profile_mappings:
                profiles = profile_mappings[ticker]
                if isinstance(profiles, str):
                    profiles = [profiles]
                has_custom_profile = profiles[0] != ticker if profiles else False
            
            enriched_tickers.append({
                'ticker': ticker,
                'display_name': ticker_data.get('display_name', ticker),
                'kpi': ticker_data.get('kpi', 'Customers'),
                'relevance_percentage': ticker_data.get('relevance_percentage'),
                's3_key': ticker_data.get('s3_key'),  # Include s3_key for metadata updates
                'hasImage': has_image,
                'imageUrl': image_url,
                'profiles': profiles,
                'profileFilename': profiles[0] if profiles else ticker,
                'hasCustomProfile': has_custom_profile
            })
        
        return jsonify({
            'success': True,
            'tickers': enriched_tickers,
            'count': len(enriched_tickers)
        })
        
    except Exception as e:
        print(f"❌ Error in get_tickers_full: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/job-data/<job_id>')
@requires_auth
def get_job_data(job_id):
    """Get job result data as JSON for dashboard display."""
    if job_id not in jobs:
        return jsonify({'success': False, 'error': 'Job not found'}), 404
    
    job = jobs[job_id]
    if job['status'] != 'completed':
        return jsonify({'success': False, 'error': 'Job not completed'}), 400
    
    if not job['result_file'] or not os.path.exists(job['result_file']):
        return jsonify({'success': False, 'error': 'Result file not found'}), 404
    
    try:
        df = pd.read_csv(job['result_file'])
        # Replace NaN with empty string for valid JSON
        df = df.fillna('')
        
        # Extract brand and date range
        brand_name = job['project_name']
        date_range = extract_date_range_from_profile_df(df)
        metadata_rows = df[df['Column'] == 'INPUT_METADATA']
        if not metadata_rows.empty:
            metadata_value = str(metadata_rows.iloc[0]['Value'])
            if 'BRAND:' in metadata_value:
                brand_name = metadata_value.split('BRAND:')[1].split('_')[0]
        
        data = df.to_dict('records')
        
        return jsonify({
            'success': True,
            'data': data,
            'brand': brand_name.upper(),
            'date_range': date_range
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/submit', methods=['POST'])
@requires_auth
def submit_analysis():
    """Submit a new behavioral graph analysis job."""
    try:
        # Check user credits first (Profile Analysis costs 5 credits)
        username = session.get('username')
        if not has_credits_for(username, CREDITS_PROFILE_ANALYSIS):
            _, credits_left = check_user_credits(username)
            return jsonify({
                'error': f'Profile Analysis requires {CREDITS_PROFILE_ANALYSIS} credits. You have {"no" if credits_left == 0 else credits_left} remaining. Please contact an administrator to get more credits.',
                'credits_left': 0 if credits_left != -1 else -1
            }), 403
        
        data = request.json
        
        # Validate required fields (support both old and new date field names)
        if not data.get('project_name'):
            return jsonify({'error': 'Missing required field: project_name'}), 400
        geo_zip_codes_raw = data.get('geo_zip_codes', '').strip()
        geo_dma_raw = data.get('geo_dma', '').strip()
        is_geo_profile = bool(geo_zip_codes_raw and geo_dma_raw)
        if not is_geo_profile and not data.get('brands'):
            return jsonify({'error': 'Missing required field: brands (or provide zip codes + DMA)'}), 400
        if not (data.get('sample_start') or data.get('start_date')):
            return jsonify({'error': 'Missing required field: start date'}), 400
        if not (data.get('sample_end') or data.get('end_date')):
            return jsonify({'error': 'Missing required field: end date'}), 400
        
        # Create job ID
        job_id = str(uuid.uuid4())[:8]
        
        # Parse inputs
        project_name = data['project_name'].replace(' ', '_')
        project_name = re.sub(r'[<>:"/\\|?*]', '_', project_name)
        
        # Parse geo parameters
        geo_zip_codes = None
        geo_dma = None
        if is_geo_profile:
            geo_zip_codes = [z.strip() for z in geo_zip_codes_raw.replace('\n', ',').split(',') if z.strip()]
            geo_dma = geo_dma_raw
            brands = []
            print(f"📍 Geographic profile: {len(geo_zip_codes)} zip codes, DMA='{geo_dma}'")
        else:
            # Parse brands (same as terminal: comma-separated, optional URL strip)
            brands_raw = data['brands'].replace('\n', ',')
            brands = []
            for b in brands_raw.split(','):
                b = b.strip()
                if not b:
                    continue
                match = re.search(r'https?://([^/]+)', b)
                clean_brand = match.group(1).lower() if match else b.lower()
                brands.append(clean_brand)
            # Full expansion to all name combos (like terminal "Auto Format Inputs? Y") is done in run_analysis via bg.generate_brand_variations
        
        # Parse dates
        try:
            # Support both old format (start_date/end_date) and new format (sample_start/sample_end)
            start_date = data.get('sample_start') or data.get('start_date')
            end_date = data.get('sample_end') or data.get('end_date')
            behavior_start = data.get('behavior_start') or start_date
            behavior_end = data.get('behavior_end') or end_date
            
            start_date = datetime.strptime(start_date, '%Y-%m-%d').strftime('%Y-%m-%d')
            end_date = datetime.strptime(end_date, '%Y-%m-%d').strftime('%Y-%m-%d')
            behavior_start = datetime.strptime(behavior_start, '%Y-%m-%d').strftime('%Y-%m-%d')
            behavior_end = datetime.strptime(behavior_end, '%Y-%m-%d').strftime('%Y-%m-%d')
        except ValueError:
            return jsonify({'error': 'Invalid date format. Use YYYY-MM-DD'}), 400
        
        # Optional parameters — auto-detect GenPop from brand names if caller omits is_genpop
        _brand_lower = [b.strip().lower() for b in brands]
        is_genpop = data.get('is_genpop', any(b in ('gen pop', 'gen_pop', 'genpop') for b in _brand_lower))
        purchasers_only = data.get('purchasers_only', False)
        # Track whether the user explicitly set these so we know if it's safe to
        # inherit from an auto-detected reference profile (= what the old YES /
        # "rerun with different dates" path used to do explicitly).
        _user_set_category = 'brand_category' in data and (data.get('brand_category') or '').strip() not in ('', 'GENERAL')
        _user_set_listener = 'is_listener_watcher' in data
        _user_set_platform = 'platform_name' in data and (data.get('platform_name') or '').strip() != ''
        brand_category = data.get('brand_category', 'GENERAL')
        include_frequency = data.get('include_frequency', False)
        is_listener_watcher = data.get('is_listener_watcher', False)
        platform_name = data.get('platform_name', None) if is_listener_watcher else None
        previous_file = data.get('previous_file', None) if data.get('is_update', False) else None
        
        # Automatically search for similar files for demographic consistency.
        # This block is the unified replacement for the old YES / "rerun with
        # different dates" UI: we look up any matching prior profile for this
        # same brand/input and inherit its persona, demographics, sample size,
        # category and listener/watcher settings as a consistency baseline.
        reference_demographics = None
        reference_sample_size = None
        reference_file_key = None
        reference_metadata = None
        
        # Search S3 for existing runs with same brand (skip for geo profiles)
        try:
            brand_label = brands[0] if brands else f"GEO_{geo_dma}"
            if brands:
                print(f"🔍 Checking for existing runs of '{brands[0]}' for consistency validation...")
                exact_match, similar_files = check_s3_for_existing(brands[0], start_date, end_date)
            else:
                exact_match, similar_files = None, []
            
            # If there's a similar file (same brand, different dates), use it as reference
            if similar_files:
                # Use the most recent similar file as reference
                similar_files.sort(key=lambda x: x.get('last_modified', ''), reverse=True)
                reference_file = similar_files[0]
                reference_file_key = reference_file['key']
                reference_demographics = reference_file['demographics']
                reference_sample_size = reference_file['sample_size']
                reference_metadata = reference_file.get('metadata') or {}
                print(f"📋 Found reference file: {reference_file_key}")
                print(f"   Reference sample size: {reference_sample_size}")
                print(f"   Will enforce ±2% consistency for demographics and sample size")

                # Inherit run-shape settings from the reference when the user
                # didn't explicitly override them. Mirrors what the old YES
                # path's /api/submit-rerun did.
                if not _user_set_category:
                    ref_cat = (reference_metadata.get('BRAND_CATEGORY') or '').strip()
                    if ref_cat:
                        brand_category = ref_cat
                        print(f"   ↳ Inherited brand_category='{brand_category}' from reference")
                if not _user_set_listener:
                    ref_lw = str(reference_metadata.get('LISTENER_WATCHER') or '').strip().lower() == 'true'
                    if ref_lw:
                        is_listener_watcher = True
                        print(f"   ↳ Inherited is_listener_watcher=True from reference")
                if is_listener_watcher and not _user_set_platform:
                    ref_plat = (reference_metadata.get('PLATFORM_NAME') or '').strip()
                    if ref_plat:
                        platform_name = ref_plat
                        print(f"   ↳ Inherited platform_name='{platform_name}' from reference")
            else:
                print(f"📋 No previous runs found for '{brands[0] if brands else brand_label}' - will create baseline")
        except Exception as e:
            print(f"⚠️ Error checking for reference files: {e}")
        
        # Demographic filters - support both object format and individual fields
        filters = data.get('filters', {})
        if not filters:
            filters = {}
            for demo_field in ['gender', 'age', 'ethnicity', 'income', 'education', 'relationship', 'sexual_orientation', 'parental_status']:
                if data.get(demo_field):
                    filters[demo_field.upper()] = [data[demo_field]]
        
        # Skew settings - support both object format and individual fields
        skew_settings = data.get('skew_settings', {})
        if not skew_settings:
            skew_settings = {}
            if data.get('enable_skew', False) and data.get('skew_category') and data.get('skew_target'):
                targets = [t.strip() for t in data['skew_target'].split(',')]
                skew_settings[data['skew_category']] = {
                    'target': targets,
                    'strength': data.get('skew_strength', 'medium')
                }
        
        # Surface the auto-anchor in the queued message so the user can see
        # the unified pipeline picked up a prior profile as a baseline.
        if reference_file_key:
            ref_basename = os.path.basename(reference_file_key)
            queued_message = f"Queued — auto-anchored to {ref_basename} for consistency"
        else:
            queued_message = 'Queued'

        # Initialize job with simpler status tracking
        jobs[job_id] = {
            'status': 'queued',
            'progress': 0,
            'message': queued_message,
            'created_at': datetime.now().isoformat(),
            'project_name': project_name,
            'brands': brand_label,
            'result_file': None,
            'error': None,
            'logs': [],
            'reference_demographics': reference_demographics,
            'reference_sample_size': reference_sample_size,
            'reference_file_key': reference_file_key,
            'created_by': username,
            's3_key': None,
        }
        if s3_client:
            _save_job_status_to_s3(job_id, jobs[job_id])
        
        enqueue_profile_analysis_run(
            run_analysis,
            (job_id, project_name, brands, start_date, end_date,
             behavior_start, behavior_end, filters, skew_settings,
             is_genpop, purchasers_only, brand_category,
             include_frequency, is_listener_watcher, platform_name, previous_file,
             reference_demographics, reference_sample_size, reference_file_key),
            {'geo_zip_codes': geo_zip_codes, 'geo_dma': geo_dma},
            queued_job_id=job_id,
        )
        
        # Consume credits for this run (record what it was used for)
        desc = f"{project_name} ({brand_label} {start_date}–{end_date})"
        consume_credit(username, description=desc, job_id=job_id, pull_type='Profile Analysis', credits_used=CREDITS_PROFILE_ANALYSIS)

        # Get updated credits
        _, credits_left = check_user_credits(username)
        
        return jsonify({
            'job_id': job_id,
            'message': 'Analysis job submitted successfully',
            'status': 'queued',
            'credits_left': credits_left,
            'brands_count': len(brands)
        })
        
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/api/incidence-check', methods=['POST'])
@requires_auth
def incidence_check():
    """Submit an incidence check job (background thread, same pattern as Profile Analysis).

    Returns a job_id immediately. Frontend polls /api/incidence-check/status/<job_id>.
    """
    try:
        data = request.json
        if not data.get('brands'):
            return jsonify({'error': 'Missing required field: search terms'}), 400
        if not data.get('start_date'):
            return jsonify({'error': 'Missing required field: start date'}), 400
        if not data.get('end_date'):
            return jsonify({'error': 'Missing required field: end date'}), 400

        job_id = f"ic-{uuid.uuid4().hex[:8]}"

        jobs[job_id] = {
            'status': 'running',
            'progress': 10,
            'message': 'Starting incidence check...',
            'created_at': datetime.now().isoformat(),
            'project_name': (data.get('project_name') or data['brands'].split(',')[0]).strip(),
            'error': None,
            'logs': [],
            'result': None,
        }

        thread = threading.Thread(
            target=_run_incidence_check_bg,
            args=(job_id, data),
            daemon=True
        )
        thread.start()

        return jsonify({'job_id': job_id, 'status': 'running'})

    except Exception as e:
        return jsonify({'error': str(e)}), 500


def _run_incidence_check_bg(job_id, data):
    """Background worker for incidence check (mirrors run_analysis pattern)."""
    try:
        import bg
        import time as _time

        project_name = (data.get('project_name') or data['brands'].split(',')[0]).strip()
        brand_category = data.get('brand_category', 'GENERAL')
        start_date = data['start_date']
        end_date = data['end_date']

        brands_raw = data['brands'].replace('\n', ',')
        brands = []
        for b in brands_raw.split(','):
            b = b.strip()
            if not b:
                continue
            match = re.search(r'https?://([^/]+)', b)
            clean_brand = match.group(1).lower() if match else b.lower()
            brands.append(clean_brand)

        if hasattr(bg, 'generate_brand_variations'):
            expanded = []
            for b in brands:
                expanded.extend(bg.generate_brand_variations(b))
            brands = list(dict.fromkeys(expanded))

        update_job_status(job_id, progress=15, message=f'Expanded to {len(brands)} brand variants...')

        GENPOP_SAMPLE_CAP = 10_000_000

        # Gen Pop CSV lookup (instant)
        genpop_result = None
        genpop_sample = None
        try:
            genpop_pct, genpop_cat = bg.get_genpop_penetration_for_brand(project_name, brand_category, brands=brands)
            if genpop_pct is not None and genpop_pct > 0:
                genpop_sample = round(genpop_pct / 100 * GENPOP_SAMPLE_CAP)
                genpop_sample = (genpop_sample // 10) * 10
                genpop_sample = max(genpop_sample, 10_000)
                genpop_result = {
                    'penetration_pct': round(genpop_pct, 4),
                    'category': genpop_cat,
                    'derived_sample_size': genpop_sample,
                }
        except Exception as e:
            print(f"⚠️ Incidence check: Gen Pop lookup failed: {e}")

        # Connect to database
        update_job_status(job_id, progress=20, message='Connecting to database...')
        conn = bg.connect_snowflake()

        # Full universe scan (same function Profile Analysis calls)
        update_job_status(job_id, progress=30, message='Running universe scan...')
        print(f"🔍 Incidence check [{job_id}]: {len(brands)} brand variants, {start_date} to {end_date}")
        t0 = _time.time()
        results = bg.perform_full_universe_scan(conn, brands, start_date, end_date, purchasers_only=False)
        query_seconds = round(_time.time() - t0, 1)
        print(f"✅ Incidence check [{job_id}] completed in {query_seconds}s")

        try:
            conn.close()
        except Exception:
            pass

        universe_result = None
        if results:
            total_universe = results['total_universe']
            total_visits = results.get('total_visits', 0)

            bounded = min(int(total_universe), GENPOP_SAMPLE_CAP)
            if bounded >= GENPOP_SAMPLE_CAP:
                bounded = GENPOP_SAMPLE_CAP - max(1, int(GENPOP_SAMPLE_CAP * 0.005))
            INFLATION_OPTIONS = [35, 25, 5, 2.5, 1]
            inflation_factor = 1
            for mult in INFLATION_OPTIONS:
                if bounded * mult <= GENPOP_SAMPLE_CAP:
                    inflation_factor = mult
                    break
            inflated_sample = min(int(bounded * inflation_factor), GENPOP_SAMPLE_CAP)
            inflated_sample = (inflated_sample // 10) * 10

            digital_panel_estimate = None
            try:
                dp_est = bg.estimate_sample_size_for_unknown_brand(brand_category, actual_universe_size=total_universe)
                if dp_est:
                    digital_panel_estimate = dp_est
            except Exception:
                pass

            universe_result = {
                'total_unique_users': total_universe,
                'total_visits': total_visits,
                'avg_visits_per_user': round(total_visits / total_universe, 2) if total_universe > 0 else 0,
                'inflation_factor': inflation_factor,
                'inflated_sample_size': inflated_sample,
                'digital_panel_estimate': digital_panel_estimate,
            }

        final_sample_size = None
        sample_size_source = None
        if genpop_sample is not None:
            final_sample_size = genpop_sample
            sample_size_source = 'genpop'
        elif universe_result and universe_result.get('digital_panel_estimate'):
            final_sample_size = universe_result['digital_panel_estimate']
            sample_size_source = 'digital_panel'
        elif universe_result:
            final_sample_size = universe_result['inflated_sample_size']
            sample_size_source = 'inflation'

        # Store result and mark complete
        jobs[job_id]['result'] = {
            'success': True,
            'project_name': project_name,
            'brands': brands[:10],
            'brand_count': len(brands),
            'brand_category': brand_category,
            'date_range': f"{start_date} to {end_date}",
            'genpop': genpop_result,
            'universe': universe_result,
            'final_sample_size': final_sample_size,
            'sample_size_source': sample_size_source,
            'query_seconds': query_seconds,
        }
        update_job_status(job_id, status='complete', progress=100, message='Done')

    except Exception as e:
        import traceback
        traceback.print_exc()
        update_job_status(job_id, status='failed', progress=100, message=str(e), error=str(e))


@app.route('/api/incidence-check/status/<job_id>')
@requires_auth
def incidence_check_status(job_id):
    """Poll incidence check job status (same pattern as /api/status/<job_id>)."""
    job = jobs.get(job_id)
    if job is None:
        return jsonify({'error': 'Job not found'}), 404
    resp = {
        'job_id': job_id,
        'status': job.get('status', 'unknown'),
        'progress': job.get('progress', 0),
        'message': job.get('message', ''),
    }
    if job.get('status') == 'complete' and job.get('result'):
        resp['result'] = job['result']
    if job.get('error'):
        resp['error'] = job['error']
    return jsonify(resp)


@app.route('/api/status/<job_id>', strict_slashes=False)
@app.route('/api/job-status/<job_id>', strict_slashes=False)
@requires_auth
def get_job_status(job_id):
    """Get simplified status of a specific job. Falls back to S3 when not in memory (Render multi-worker)."""
    job = jobs.get(job_id)
    if job is None and s3_client:
        all_jobs = _load_jobs_status_from_s3()
        job = all_jobs.get(job_id)
    if job is None:
        return jsonify({'error': 'Job not found'}), 404
    return jsonify({
        'job_id': job_id,
        'project_name': job.get('project_name', ''),
        'status': job.get('status', 'unknown'),
        'progress': job.get('progress', 0),
        'message': job.get('message', ''),
        'created_at': job.get('created_at', ''),
        'error': job.get('error'),
        'result_file': job.get('result_file'),
        's3_key': job.get('s3_key'),
        'demographic_validation': job.get('demographic_validation')
    })


@app.route('/api/download/<job_id>', strict_slashes=False)
@requires_auth
def download_result(job_id):
    """Download the result CSV file for a completed job. Uses S3 when local file unavailable (Render multi-worker)."""
    job = jobs.get(job_id)
    if job is None and s3_client:
        all_jobs = _load_jobs_status_from_s3()
        job = all_jobs.get(job_id)
    if job is None:
        return jsonify({'error': 'Job not found'}), 404
    if job.get('status') != 'completed':
        return jsonify({'error': 'Job not completed yet'}), 400

    # Try local file first
    result_file = job.get('result_file')
    if result_file and os.path.exists(result_file):
        return send_file(
            result_file,
            mimetype='text/csv',
            as_attachment=True,
            download_name=f"{job.get('project_name', 'data')}_behavioral_graph.csv"
        )

    # Fallback: stream from S3
    s3_key = job.get('s3_key')
    if s3_client and s3_key:
        try:
            response = s3_client.get_object(Bucket=S3_BUCKET, Key=s3_key)
            from io import BytesIO
            body = response['Body'].read()
            return send_file(
                BytesIO(body),
                mimetype='text/csv',
                as_attachment=True,
                download_name=f"{job.get('project_name', 'data')}_behavioral_graph.csv"
            )
        except Exception as e:
            return jsonify({'error': f'Download failed: {str(e)}'}), 500

    return jsonify({'error': 'Result file not found'}), 404


# Cache for S3 file list - now persisted to S3 for faster loads
s3_cache = {
    'jobs': [],
    'categories': [],
    'last_updated': None,
    'file_count': 0,
    'last_full_scan': None  # Track when we did a full scan
}
S3_CACHE_TTL = 300  # 5 minutes cache
S3_CACHE_KEY = 'system/s3_cache.json'  # Persisted cache location

# Per-worker tracking so we can cheaply detect when *another* worker has
# updated the persisted cache (e.g. after a purgatory release) without
# downloading the full file on every /api/jobs hit. We HEAD the cache key,
# compare ETags, and only GET when it actually changed. The throttle prevents
# a flurry of dashboard polls from pounding S3.
_persisted_cache_etag = None
_persisted_cache_last_head_ts = 0.0
_PERSISTED_CACHE_HEAD_INTERVAL_SECS = 3.0
S3_DEMO_CACHE_KEY = 'system/demographics_cache.json'  # Cached demographic summaries
S3_IMAGE_CACHE_KEY = 'system/profile_images_cache.json'  # Cached profile images

# Demographics cache - stores pre-computed demographic summaries for each profile
demographics_cache = {}

# Profile image cache - stores image URLs to avoid repeated API calls
profile_image_cache = {}
profile_image_cache_dirty = False  # Track if cache needs saving
_profile_image_cache_ts = 0  # last time cache was loaded from S3 (epoch seconds)
_PROFILE_IMAGE_CACHE_TTL = 15  # reload from S3 at most every 15 seconds
_profile_image_cache_lock = threading.Lock()


def _read_profile_image_cache_from_s3():
    """Read the profile image cache JSON from S3.

    Returns the parsed dict on success, {} if the file does not exist yet,
    or None on transient errors (network, throttling, timeout) so callers
    can distinguish 'empty cache' from 'failed to read'.
    """
    if not s3_client:
        return None
    try:
        response = s3_client.get_object(Bucket=S3_BUCKET, Key=S3_IMAGE_CACHE_KEY)
        data = json.loads(response['Body'].read().decode('utf-8'))
        return data if isinstance(data, dict) else {}
    except s3_client.exceptions.NoSuchKey:
        return {}
    except Exception as e:
        print(f"⚠️ _read_profile_image_cache_from_s3 error (transient): {e}")
        return None


def _merge_profile_image_caches(incoming, existing, deleted_keys=None):
    """
    Merge in-memory updates into the S3 cache without dropping admin uploads.
    Never overwrite is_custom entries with auto-prefetch results.
    """
    deleted_keys = set(deleted_keys or [])
    incoming = incoming or {}
    existing = existing or {}
    merged = {}
    all_keys = (set(existing.keys()) | set(incoming.keys())) - deleted_keys

    for key in all_keys:
        cur = existing.get(key)
        inc = incoming.get(key)

        if cur is None:
            merged[key] = inc
            continue
        if inc is None:
            merged[key] = cur
            continue

        cur_custom = bool(cur.get('is_custom'))
        inc_custom = bool(inc.get('is_custom'))

        if cur_custom and not inc_custom:
            merged[key] = cur
            continue
        if inc_custom and not cur_custom:
            merged[key] = inc
            continue
        if cur_custom and inc_custom:
            cur_at = cur.get('cached_at') or ''
            inc_at = inc.get('cached_at') or ''
            merged[key] = inc if inc_at >= cur_at else cur
            continue

        # Auto-sourced entries: prefer one with an image URL; never replace URL with not_found.
        if inc.get('image_url') and not cur.get('image_url'):
            merged[key] = inc
        elif cur.get('image_url') and not inc.get('image_url'):
            merged[key] = cur
        else:
            merged[key] = inc

    return merged


def load_profile_image_cache(force=False):
    """Load profile image cache from S3.

    Returns True if cache is usable (loaded from S3 or still valid in memory).
    Never replaces an existing in-memory cache with an empty result from a
    transient S3 error — this prevents the cascade where a single read failure
    leads to custom images being permanently overwritten by auto-sourced entries.
    """
    global profile_image_cache, _profile_image_cache_ts
    import time as _time
    if not s3_client:
        return False
    now = _time.time()
    if not force and profile_image_cache and (now - _profile_image_cache_ts) < _PROFILE_IMAGE_CACHE_TTL:
        return True
    with _profile_image_cache_lock:
        result = _read_profile_image_cache_from_s3()
        if result is None:
            # Transient S3 error — keep existing in-memory cache to avoid data loss
            print(f"⚠️ S3 read failed for image cache; keeping {len(profile_image_cache)} in-memory entries")
            return bool(profile_image_cache)
        profile_image_cache = result
        _profile_image_cache_ts = now
    if profile_image_cache:
        print(f"✅ Loaded profile image cache: {len(profile_image_cache)} images")
        return True
    print("📂 No profile image cache found")
    return False

def save_profile_image_cache(deleted_keys=None):
    """Save profile image cache to S3 with read-merge-write so concurrent workers don't clobber uploads.

    Anti-corruption guard: refuses to write if the merged result would lose
    a significant number of is_custom entries compared to what's currently on
    S3. This prevents transient read failures from cascading into permanent
    data loss of admin-uploaded images.
    """
    global profile_image_cache, profile_image_cache_dirty, _profile_image_cache_ts
    if not s3_client:
        print("⚠️ Cannot save profile image cache: S3 client not available")
        return False

    import time

    with _profile_image_cache_lock:
        remote = _read_profile_image_cache_from_s3()
        if remote is None:
            # S3 read failed — cannot safely merge, abort save to prevent data loss
            print("⚠️ Cannot save image cache: S3 read failed (transient). Aborting to protect custom entries.")
            return False
        merged = _merge_profile_image_caches(profile_image_cache, remote, deleted_keys=deleted_keys)

        # Anti-corruption check: count is_custom entries in remote vs merged
        remote_custom_count = sum(1 for v in remote.values() if v.get('is_custom'))
        merged_custom_count = sum(1 for v in merged.values() if v.get('is_custom'))
        if remote_custom_count > 0 and merged_custom_count < remote_custom_count:
            lost = remote_custom_count - merged_custom_count
            print(f"⚠️ ABORT SAVE: would lose {lost} custom image entries ({remote_custom_count} → {merged_custom_count}). Restoring from S3.")
            profile_image_cache = remote
            return False

        profile_image_cache = merged
        cache_json = json.dumps(profile_image_cache, indent=2)
        cache_size = len(cache_json)
        print(f"   💾 Writing cache to S3: {len(profile_image_cache)} entries, {cache_size} bytes")

        for attempt in range(3):
            try:
                # Re-read and merge on retry so we never overwrite a concurrent custom upload.
                if attempt > 0:
                    remote = _read_profile_image_cache_from_s3()
                    if remote is None:
                        print(f"⚠️ S3 re-read failed on retry {attempt + 1}, aborting save")
                        return False
                    merged = _merge_profile_image_caches(profile_image_cache, remote, deleted_keys=deleted_keys)
                    profile_image_cache = merged
                    cache_json = json.dumps(profile_image_cache, indent=2)

                s3_client.put_object(
                    Bucket=S3_BUCKET,
                    Key=S3_IMAGE_CACHE_KEY,
                    Body=cache_json,
                    ContentType='application/json'
                )
                profile_image_cache_dirty = False
                _profile_image_cache_ts = time.time()
                print(f"   ✅ Successfully wrote cache to S3: {S3_IMAGE_CACHE_KEY} (attempt {attempt + 1})")
                print(f"💾 Saved profile image cache: {len(profile_image_cache)} images")
                return True
            except Exception as e:
                print(f"⚠️ Error saving profile image cache (attempt {attempt + 1}/3): {e}")
                if attempt < 2:
                    time.sleep(0.5)
                else:
                    import traceback
                    traceback.print_exc()
                    return False
    return False


S3_PROFILE_DISPLAY_OVERRIDES_KEY = 'system/profile_display_overrides.json'
profile_display_overrides = {}
_profile_display_overrides_ts = 0
_PROFILE_DISPLAY_OVERRIDES_TTL = 15
_profile_display_overrides_lock = threading.Lock()


def _read_profile_display_overrides_from_s3():
    """Read per-profile title/tooltip overrides from S3. Returns {} if missing."""
    if not s3_client:
        return {}
    try:
        response = s3_client.get_object(Bucket=S3_BUCKET, Key=S3_PROFILE_DISPLAY_OVERRIDES_KEY)
        data = json.loads(response['Body'].read().decode('utf-8'))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def load_profile_display_overrides(force=False):
    """Load profile display overrides (hover tooltip, platform suffix) from S3."""
    global profile_display_overrides, _profile_display_overrides_ts
    import time as _time
    if not s3_client:
        return False
    now = _time.time()
    if not force and profile_display_overrides and (now - _profile_display_overrides_ts) < _PROFILE_DISPLAY_OVERRIDES_TTL:
        return True
    with _profile_display_overrides_lock:
        profile_display_overrides = _read_profile_display_overrides_from_s3()
        _profile_display_overrides_ts = now
    return True


def save_profile_display_overrides():
    """Persist profile display overrides to S3 (read-merge-write)."""
    global profile_display_overrides, _profile_display_overrides_ts
    if not s3_client:
        return False
    import time
    with _profile_display_overrides_lock:
        remote = _read_profile_display_overrides_from_s3()
        merged = dict(remote or {})
        merged.update(profile_display_overrides or {})
        cache_json = json.dumps(merged, indent=2)
        for attempt in range(3):
            try:
                if attempt > 0:
                    remote = _read_profile_display_overrides_from_s3()
                    merged = dict(remote or {})
                    merged.update(profile_display_overrides or {})
                    cache_json = json.dumps(merged, indent=2)
                s3_client.put_object(
                    Bucket=S3_BUCKET,
                    Key=S3_PROFILE_DISPLAY_OVERRIDES_KEY,
                    Body=cache_json,
                    ContentType='application/json'
                )
                profile_display_overrides = merged
                _profile_display_overrides_ts = time.time()
                return True
            except Exception as e:
                print(f"⚠️ Error saving profile display overrides (attempt {attempt + 1}/3): {e}")
                if attempt < 2:
                    time.sleep(0.5)
    return False


def serialize_profile_display_override(s3_key):
    """Return override dict for API responses, or None if none set."""
    if not s3_key:
        return None
    load_profile_display_overrides()
    entry = profile_display_overrides.get(s3_key)
    if not entry:
        return None
    out = {}
    if entry.get('hover_tooltip'):
        out['hover_tooltip'] = entry['hover_tooltip']
    if entry.get('platform_name'):
        out['platform_name'] = entry['platform_name']
    if entry.get('platform_removed'):
        out['platform_removed'] = True
    return out or None


