def resolve_subscriber_iq_s3_key(file_key):
    """Admin content keys use svod-acquisition/ prefix; Subscriber IQ API uses bare S3 key."""
    key = (file_key or '').strip()
    if key.startswith('svod-acquisition/'):
        return key[len('svod-acquisition/'):]
    return key


def _episode_is_date_like(value):
    """True when the string looks like a calendar date, not an episode label."""
    s = (value or '').strip()
    if not s:
        return False
    if '/' in s:
        return True
    return bool(re.match(r'^\d{1,2}-\d{1,2}-\d{2,4}$', s))


def _episode_number_for_admin(ep, index):
    """Match Subscriber IQ Episode Dates tab: Episode 1, not 1/16/26."""
    raw = str(ep.get('episode') or '').strip()
    date_raw = str(ep.get('episode_date') or '').strip()

    if raw and raw.replace(' ', '').isdigit():
        return raw.replace(' ', '')

    if raw:
        head = raw.split('/')[0].split('-')[0].strip()
        if head.isdigit():
            n = int(head)
            # PER-DATE CSVs store the air date in episode; dashboard uses parseInt → 1
            if _episode_is_date_like(raw) or (date_raw and date_raw == raw):
                return str(n)

    if raw and not _episode_is_date_like(raw):
        return raw

    return str(index + 1)


def _episode_release_date_for_admin(ep):
    """Release date column value for admin editor."""
    raw = str(ep.get('episode') or '').strip()
    date_raw = str(ep.get('episode_date') or '').strip()
    if date_raw:
        return date_raw
    if _episode_is_date_like(raw):
        return raw
    return ''


def _episode_admin_sort_key(row):
    """Numeric sort for admin episode editor (Episode 1, 2, 3… not CSV row order)."""
    ep = str((row or {}).get('episode') or '').strip()
    if ep.isdigit():
        return (0, int(ep))
    head = ep.split('/')[0].split('-')[0].strip()
    if head.isdigit():
        return (0, int(head))
    return (1, ep.lower())


def _episode_rows_from_parsed(parsed):
    """Episode # + release date rows for Episode Dates tab (all tracked episodes)."""
    rows = []
    for i, ep in enumerate(parsed.get('episode_attribution') or []):
        rows.append({
            'episode': _episode_number_for_admin(ep, i),
            'episode_date': _episode_release_date_for_admin(ep),
        })
    rows.sort(key=_episode_admin_sort_key)
    return rows


def apply_subscriber_episode_overrides(s3_key, parsed):
    """Apply admin-edited episode numbers and release dates onto parsed Subscriber IQ data."""
    if not s3_key:
        return
    load_subscriber_episode_overrides()
    entry = subscriber_episode_overrides.get(s3_key)
    if not entry or not entry.get('episodes'):
        return
    csv_eps = list(parsed.get('episode_attribution') or [])
    merged = []
    for i, ov in enumerate(entry['episodes']):
        ep_num = str(ov.get('episode', '')).strip()
        ep_date = str(ov.get('episode_date', '')).strip()
        base = dict(csv_eps[i]) if i < len(csv_eps) else {}
        base['episode'] = ep_num
        base['episode_date'] = ep_date
        merged.append(base)
    parsed['episode_attribution'] = merged
    parsed['_episode_dates_admin_override'] = True


def _csv_data_json_response(data, brand_name, date_range, s3_key):
    """Build get-csv-data JSON with optional display_override."""
    payload = {
        'success': True,
        'data': data,
        'brand': brand_name,
        'date_range': date_range,
        's3_key': s3_key,
    }
    override = serialize_profile_display_override(s3_key)
    if override:
        payload['display_override'] = override
    return payload


