def load_persisted_cache():
    """Load the S3 file cache from S3 storage."""
    global s3_cache, _persisted_cache_etag
    if not s3_client:
        return False
    try:
        response = s3_client.get_object(Bucket=S3_BUCKET, Key=S3_CACHE_KEY)
        cached_data = json.loads(response['Body'].read().decode('utf-8'))
        s3_cache['jobs'] = cached_data.get('jobs', [])
        s3_cache['categories'] = cached_data.get('categories', [])
        s3_cache['last_updated'] = cached_data.get('last_updated')
        s3_cache['file_count'] = cached_data.get('file_count', 0)
        s3_cache['last_full_scan'] = cached_data.get('last_full_scan')
        # Track ETag so other workers can detect changes via cheap HEAD requests.
        _persisted_cache_etag = (response.get('ETag') or '').strip('"') or None
        print(f"✅ Loaded persisted cache: {len(s3_cache['jobs'])} files")
        return True
    except s3_client.exceptions.NoSuchKey:
        print("📂 No persisted cache found, will do full scan")
        return False
    except Exception as e:
        print(f"⚠️ Error loading persisted cache: {e}")
        return False

def save_persisted_cache():
    """Save the S3 file cache to S3 storage.

    Merges in any "extension" fields (currently `imdb_id` / `imdb_label`)
    from the live S3 copy before writing. This is the difference between
    "this worker's view of jobs" and "the global jobs record": fields
    populated by side-channel writers (e.g. `migration/scrape_imdb_ids.py`)
    must survive a save from a worker that hasn't yet seen them.

    Without this read-then-write merge, a worker that loaded the cache at
    boot — before the IMDB scraper ran — would happily clobber every
    `imdb_id` the next time *anything* triggered a save (a profile upload,
    a delete, an admin action, etc.). The new fields then re-disappear from
    the UI and we'd have to keep re-running the scraper. Merging keeps
    those fields sticky.

    Cheap because the IMDB merge is keyed by `profile_subject` (~250 jobs)
    and only touches the in-memory copy — no extra S3 round-trip beyond the
    one GET we'd usually do at boot anyway.
    """
    global _persisted_cache_etag, _persisted_cache_last_head_ts
    if not s3_client:
        return
    try:
        # Read-then-write: pull the latest S3 copy and merge its imdb_id /
        # imdb_label values onto our in-memory jobs by profile_subject. Any
        # job we don't have a record of in memory but exists on S3 with an
        # imdb_id is left alone (other workers may add jobs we haven't seen
        # yet — but we never WRITE jobs that aren't in our in-memory list,
        # so they stay on S3 untouched).
        try:
            remote = s3_client.get_object(Bucket=S3_BUCKET, Key=S3_CACHE_KEY)
            remote_cache = json.loads(remote['Body'].read().decode('utf-8'))
            remote_imdb = {}
            for j in (remote_cache.get('jobs') or []):
                subj = (j.get('profile_subject') or '').strip()
                if not subj:
                    continue
                imdb = j.get('imdb_id')
                label = j.get('imdb_label')
                if imdb or label:
                    remote_imdb[subj] = (imdb, label)
            if remote_imdb:
                for j in (s3_cache.get('jobs') or []):
                    subj = (j.get('profile_subject') or '').strip()
                    if not subj:
                        continue
                    pair = remote_imdb.get(subj)
                    if not pair:
                        continue
                    imdb, label = pair
                    # Only restore from remote if local doesn't already
                    # have a value — local writes (if any) win, but the
                    # common case is "local has nothing, remote has the
                    # scraped id."
                    if imdb and not j.get('imdb_id'):
                        j['imdb_id'] = imdb
                    if label and not j.get('imdb_label'):
                        j['imdb_label'] = label
        except s3_client.exceptions.NoSuchKey:
            pass
        except Exception as merge_err:
            # Merge is a soft guarantee; never fail a save on it.
            print(f"⚠️ persisted-cache imdb merge failed (non-fatal): {merge_err}")

        cache_data = {
            'jobs': s3_cache.get('jobs', []),
            'categories': s3_cache.get('categories', []),
            'last_updated': s3_cache.get('last_updated'),
            'file_count': s3_cache.get('file_count', 0),
            'last_full_scan': s3_cache.get('last_full_scan')
        }
        put_resp = s3_client.put_object(
            Bucket=S3_BUCKET,
            Key=S3_CACHE_KEY,
            Body=json.dumps(cache_data),
            ContentType='application/json'
        )
        # Stamp our own ETag so we don't bounce-reload our own write on the
        # next /api/jobs request (would be wasted work).
        new_etag = (put_resp.get('ETag') or '').strip('"') or None
        if new_etag:
            _persisted_cache_etag = new_etag
        _persisted_cache_last_head_ts = time.time()
        print(f"💾 Saved cache to S3: {len(s3_cache['jobs'])} files")
    except Exception as e:
        print(f"⚠️ Error saving persisted cache: {e}")


def maybe_refresh_persisted_cache_if_changed():
    """Cheap cross-worker propagation hook.

    Does a throttled S3 HEAD on the persisted cache file. If another worker
    updated it (different ETag), pulls the fresh copy. Throttled to at most
    one HEAD per ~3 seconds per worker so dashboard polling can't pound S3.

    Designed to be called from hot read endpoints (/api/jobs, /api/my-results)
    so newly-released-from-purgatory items show up automatically without the
    user having to click the refresh button.
    """
    global _persisted_cache_last_head_ts, _persisted_cache_etag
    if not s3_client:
        return
    now = time.time()
    if (now - _persisted_cache_last_head_ts) < _PERSISTED_CACHE_HEAD_INTERVAL_SECS:
        return
    _persisted_cache_last_head_ts = now
    try:
        head = s3_client.head_object(Bucket=S3_BUCKET, Key=S3_CACHE_KEY)
        remote_etag = (head.get('ETag') or '').strip('"') or None
        if remote_etag and remote_etag != _persisted_cache_etag:
            load_persisted_cache()
    except Exception as e:
        # Silent best-effort — never fail a page load on this.
        if not isinstance(e, getattr(s3_client.exceptions, 'NoSuchKey', Exception)):
            print(f"⚠️ persisted-cache HEAD probe failed: {e}")


