# Map old age brackets to new display brackets with split ratios (old -> [(new_bucket, ratio), ...])
# Used so older files show age inline with new bracket labels and redistributed percentages.
_OLD_AGE_TO_NEW = {
    '<16': [('17 and Under', 1.0)],
    'under 16': [('17 and Under', 1.0)],
    '16-18': [('17 and Under', 0.67), ('18-24', 0.33)],
    '17-18': [('17 and Under', 0.67), ('18-24', 0.33)],
    '19-20': [('18-24', 1.0)],
    '18-20': [('18-24', 1.0)],
    '21-25': [('18-24', 0.8), ('25-34', 0.2)],
    '26-30': [('25-34', 1.0)],
    '31-40': [('25-34', 0.4), ('35-44', 0.6)],
    '41-49': [('35-44', 0.21), ('45-54', 0.53), ('55-64', 0.26)],
    '41-59': [('35-44', 0.21), ('45-54', 0.53), ('55-64', 0.26)],
    '60+': [('55-64', 0.25), ('65 or Older', 0.75)],
    '65+': [('55-64', 0.25), ('65 or Older', 0.75)],
    'over 65': [('55-64', 0.25), ('65 or Older', 0.75)],
}


def _norm_age_key(s):
    """Normalize age value for mapping: strip, lower, collapse spaces around dashes (e.g. '18 - 24' -> '18-24')."""
    if s is None:
        return ""
    s = str(s).strip().lower()
    s = re.sub(r"\s*-\s*", "-", s)
    s = re.sub(r"\s+", " ", s)
    return s


def _normalize_age_buckets_from_raw(age_raw_dict):
    """Redistribute old age bracket *raw counts* into new buckets, then return new bucket percentages.
    Each old bucket's count is split by ratio (e.g. 17-18: 67% -> 17 and Under, 33% -> 18-24);
    new percentage = (summed raw for bucket / total age raw) * 100.
    """
    if not age_raw_dict:
        return {}
    new_raw = {}
    for old_key, raw_count in age_raw_dict.items():
        raw_count = int(float(str(raw_count).replace(",", ""))) if raw_count else 0
        if raw_count <= 0:
            continue
        key_norm = _norm_age_key(old_key)
        mapping = _OLD_AGE_TO_NEW.get(key_norm) or _OLD_AGE_TO_NEW.get((old_key or "").strip().lower()) or _OLD_AGE_TO_NEW.get(old_key)
        if mapping:
            for new_bucket, ratio in mapping:
                new_raw[new_bucket] = new_raw.get(new_bucket, 0) + raw_count * ratio
        else:
            new_raw[old_key] = new_raw.get(old_key, 0) + raw_count
    total = sum(new_raw.values())
    if total <= 0:
        return {}
    return {b: round((r / total) * 100.0, 4) for b, r in new_raw.items()}


def normalize_age_buckets_for_display(age_dict):
    """Redistribute old age bracket percentages into new display buckets (percentage-based fallback)."""
    if not age_dict:
        return dict(age_dict)
    new_age = {}
    for old_key, pct in age_dict.items():
        key_norm = _norm_age_key(old_key)
        mapping = _OLD_AGE_TO_NEW.get(key_norm) or _OLD_AGE_TO_NEW.get((old_key or '').strip().lower()) or _OLD_AGE_TO_NEW.get(old_key)
        if mapping:
            for new_bucket, ratio in mapping:
                new_age[new_bucket] = new_age.get(new_bucket, 0) + pct * ratio
        else:
            new_age[old_key] = new_age.get(old_key, 0) + pct
    return new_age


def extract_demographics_summary(csv_content):
    """Extract demographic summary from CSV content."""
    try:
        df = pd.read_csv(io.StringIO(csv_content))
        
        summary = {
            'gender': {},
            'age': {},
            'income': {},
            'ethnicity': {},
            'sampleSize': 0,
            'projectedUS': 0
        }
        
        age_raw = {}  # value -> Original Raw Numbers for AGE rows
        for _, row in df.iterrows():
            category = str(row.get('Column', '')).upper()
            value = row.get('Value', '')
            # ALWAYS use Brand Penetration (Row) = Column C, NEVER fall back to Category Share (Column D)
            brand_pen_val = row.get("Brand Penetration (Row)")
            if brand_pen_val is not None and str(brand_pen_val).strip() != '':
                try:
                    pct = float(brand_pen_val)
                except (ValueError, TypeError):
                    pct = 0
            else:
                pct = 0

            if category == "SAMPLE SIZE":
                summary['sampleSize'] = int(row.get('Category Share', 0) or row.get('Original Raw Numbers', 0) or 0)
            elif category == 'BRAND INPUT':
                summary['projectedUS'] = int(row.get('US Gen Pop Projection', 0) or 0)
            elif category == 'GENDER' and value:
                summary['gender'][value] = pct
            elif category == 'AGE' and value:
                summary['age'][value] = pct
                raw_val = row.get('Original Raw Numbers', 0)
                if raw_val is not None and str(raw_val).strip() != '':
                    try:
                        age_raw[value] = int(float(str(raw_val).replace(',', '')))
                    except (ValueError, TypeError):
                        pass
            elif category == 'INCOME' and value:
                summary['income'][value] = pct
            elif category == 'ETHNICITY' and value:
                summary['ethnicity'][value] = pct
        
        # Use raw counts to build new age buckets, then derive percentages.
        # Pipeline CSVs often have empty Original Raw Numbers for AGE; derive from pct and sample size.
        if not age_raw and summary["age"] and summary["sampleSize"] > 0:
            for k, pct in summary["age"].items():
                age_raw[k] = max(0, round((pct / 100.0) * summary["sampleSize"]))
        if age_raw:
            summary["age"] = _normalize_age_buckets_from_raw(age_raw)
        else:
            summary["age"] = normalize_age_buckets_for_display(summary["age"])
        return summary
    except Exception as e:
        print(f"Error extracting demographics: {e}")
        return None

# Cache loading is handled in background thread - see quick_startup_cache()


@app.route('/api/queue/status', strict_slashes=False)
@requires_auth
def get_queue_status():
    """Return live state of the cross-tool analysis throttle:
       - profile-analysis queue: configured workers, queued, in-flight
       - heavy-analysis throttle: capacity, in-flight (per-tool), waiting (per-tool)
       - heartbeat / stale-sweep tunables, for visibility from the UI

    The heavy-analysis throttle is shared across Profile Analysis,
    Subscriber IQ (SVOD Acquisition), ROAS IQ, Talent Theater / Search,
    Watch Time, Cross Show, Campaign ROI, Ticket Sales Tracker,
    SF/LF + Flywheel Conversion, and Ecommerce IQ.
    """
    try:
        with _profile_analysis_queue_inflight_lock:
            pa_inflight_ids = list(_profile_analysis_queue_inflight)
        depth = profile_analysis_run_queue_depth()
        snap = _heavy_status_snapshot()

        def _by_tool(d):
            counts = {}
            for info in d.values():
                t = (info or {}).get('tool') or 'unknown'
                counts[t] = counts.get(t, 0) + 1
            return counts

        return jsonify({
            'profile_analysis_queue': {
                'workers': _PROFILE_QUEUE_WORKERS,
                'inflight': len(pa_inflight_ids),
                'inflight_ids': pa_inflight_ids,
                'queued': max(0, depth),
                'capacity': _PROFILE_QUEUE_WORKERS,
                'free_slots': max(0, _PROFILE_QUEUE_WORKERS - len(pa_inflight_ids)),
            },
            'heavy_throttle': {
                'capacity': BG_HEAVY_ANALYSIS_CONCURRENCY,
                'inflight': len(snap['inflight']),
                'inflight_ids': list(snap['inflight'].keys()),
                'inflight_by_tool': _by_tool(snap['inflight']),
                'waiting': len(snap['waiting']),
                'waiting_ids': list(snap['waiting'].keys()),
                'waiting_by_tool': _by_tool(snap['waiting']),
                'free_slots': max(0, BG_HEAVY_ANALYSIS_CONCURRENCY - len(snap['inflight'])),
            },
            'clickhouse_throttle': _safe_ch_throttle_stats(),
            # Back-compat: keep the old top-level fields so existing UI code
            # (anything pointing at workers/inflight/queued at the root) keeps
            # working. New consumers should use the structured fields above.
            'workers': _PROFILE_QUEUE_WORKERS,
            'inflight': len(pa_inflight_ids),
            'inflight_ids': pa_inflight_ids,
            'queued': max(0, depth),
            'capacity': _PROFILE_QUEUE_WORKERS,
            'free_slots': max(0, _PROFILE_QUEUE_WORKERS - len(pa_inflight_ids)),
            'stale_after_seconds': BG_JOB_STALE_AFTER_SECONDS,
            'heartbeat_interval_seconds': BG_HEARTBEAT_INTERVAL_SECONDS,
            'sweep_interval_seconds': BG_STALE_SWEEP_INTERVAL_SECONDS,
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/api/jobs')
@requires_auth
def list_jobs():
    """List all jobs (local + S3 cached) with caching for performance. Use ?refresh=1 to sync from S3 before returning."""
    import time
    
    try:
        job_list = []
        categories = set()
        
        # Return quickly if cache is still loading
        if not cache_loading_complete and not s3_cache.get('jobs'):
            return jsonify({
                'jobs': [],
                'categories': [],
                'cache_info': {'loading': True, 'message': 'Loading profiles...'},
                'loading': True
            })
        
        # Cheap cross-worker propagation: throttled HEAD on the persisted cache
        # file — if another worker (e.g. the one that handled a purgatory
        # release) updated it, pull the fresh copy. Adds ~0ms in steady state
        # (in-memory throttle), ~20-30ms when ETag actually changed. Means
        # newly-released profiles appear without the user clicking refresh.
        if s3_client and cache_loading_complete:
            try:
                maybe_refresh_persisted_cache_if_changed()
            except Exception as e:
                print(f"⚠️ list_jobs cross-worker probe failed: {e}")

        # If refresh=1, also do a full S3 listing sync (catches files written
        # outside the in-app release path, e.g. manual uploads).
        if request.args.get('refresh') and s3_client and cache_loading_complete:
            try:
                load_persisted_cache()  # Pick up cache saved by other workers (e.g. after release from purgatory)
                smart_cache_update()   # Sync with actual S3 listing (add new, remove deleted)
            except Exception as e:
                print(f"⚠️ list_jobs refresh error: {e}")
        
        # Update user's last activity time (but don't block on it)
        username = session.get('username')
        if username:
            try:
                users = load_users()
                if username in users:
                    users[username]['last_activity'] = time.time()
                    save_users(users)
            except Exception:
                pass  # Don't block on activity tracking
        
        # Add local jobs (always fresh); for purgatory s3_keys merge display name and category from purgatory metadata
        # Track s3_keys we've already added so we never emit the same profile twice
        # (e.g. a recently-finished local job whose s3_key is also in the persisted
        # S3 cache — without this dedup, the dashboard would render it as
        # "(2 date ranges)" with two identical entries underneath).
        purgatory_meta = load_purgatory_metadata() if s3_client else {}
        seen_s3_keys = set()
        for job_id, job in jobs.items():
            s3_key = job.get('s3_key') or ''
            entry = {
                'job_id': job_id,
                'project_name': job.get('project_name', ''),
                'status': job.get('status', 'unknown'),
                'progress': job.get('progress', 0),
                'created_at': job.get('created_at', ''),
                'source': 'local',
                'category': 'LOCAL',
                's3_key': s3_key or job.get('s3_key'),
                'display_name': job.get('display_name'),
                'profile_subject': get_profile_subject_from_s3_key(s3_key) if s3_key else ''
            }
            if s3_key.startswith(S3_PURGATORY_PREFIX):
                purgatory_id = f"{S3_BUCKET}:{s3_key}"
                if purgatory_id in purgatory_meta:
                    item = purgatory_meta[purgatory_id]
                    entry['category'] = item.get('category') or 'Uncategorized'
                    entry['project_name'] = item.get('title') or item.get('project_name') or entry['project_name']
                    entry['display_name'] = item.get('title') or entry['project_name']
                    # Use released key if item was released so "View in Dashboard" works without 404
                    if item.get('released_key'):
                        entry['s3_key'] = item['released_key']
                    categories.add(entry['category'])
            else:
                categories.add('LOCAL')
            job_list.append(entry)
            final_sk = entry.get('s3_key') or ''
            if final_sk:
                seen_s3_keys.add(final_sk)
        
        # Use persisted cache only - no S3 scanning on page load for speed
        # If cache is empty, try to load persisted cache
        cache_jobs = s3_cache.get('jobs') or []
        if not cache_jobs and s3_client:
            load_persisted_cache()
            cache_jobs = s3_cache.get('jobs') or []
        
        # Add cached S3 jobs (ensure each has created_at for sorting).
        # Skip any whose s3_key was already emitted as a local job above so the
        # same CSV never appears twice in the profile selector.
        for j in cache_jobs:
            if isinstance(j, dict):
                sk = j.get('s3_key') or ''
                if sk and sk in seen_s3_keys:
                    continue
                entry = {
                    'job_id': j.get('job_id') or sk or '',
                    'project_name': j.get('project_name') or j.get('name', 'Unknown'),
                    'status': j.get('status', 'cached'),
                    'progress': j.get('progress', 100),
                    'created_at': j.get('created_at') or j.get('last_modified', ''),
                    'source': j.get('source', 's3'),
                    'category': j.get('category', 'OTHER'),
                    's3_key': sk,
                    'display_name': j.get('display_name'),
                    'profile_subject': j.get('profile_subject') or get_profile_subject_from_s3_key(sk) if sk else ''
                }
                # Preserve bucket/is_svod for SVOD profile detection
                if 'bucket' in j:
                    entry['bucket'] = j['bucket']
                if 'is_svod' in j:
                    entry['is_svod'] = j['is_svod']
                if j.get('secondary_category'):
                    entry['secondary_category'] = j['secondary_category']
                # Pass IMDB enrichment through to the frontend so the Profile IQ
                # dashboard can render a clickable "IMDB: nm0000123" pill under
                # the date range header. Backfilled by migration/scrape_imdb_ids.py
                # and merged onto in-memory jobs by load_persisted_cache(). Only
                # forward when present + truthy (skips both "never scraped" and
                # "scraped but no person match" cases so the frontend can cleanly
                # hide the block without a separate null check). Same source the
                # IQ Ranker uses for its inline IMDB chip.
                imdb_val = j.get('imdb_id')
                if imdb_val:
                    entry['imdb_id'] = imdb_val
                    if j.get('imdb_label'):
                        entry['imdb_label'] = j['imdb_label']
                job_list.append(entry)
                if sk:
                    seen_s3_keys.add(sk)
                cat = j.get('category')
                if cat:
                    categories.add(cat)
        
        # DO NOT include purgatory items - they should NEVER appear in the profile selector
        # Purgatory items are only visible in the Admin purgatory review section
        
        # Filter out any purgatory items that may have been added from cache
        job_list = [e for e in job_list if not (e.get('s3_key') or '').startswith('purgatory/')]
        job_list = [e for e in job_list if not (e.get('s3_key') or '').startswith(S3_PURGATORY_PREFIX)]
        job_list = [e for e in job_list if e.get('status') != 'pending' and not e.get('in_purgatory')]

        # Profile IQ must only surface files at the root of dashboard-inputs.
        # Any cached entry whose s3_key contains '/' belongs to a subfolder
        # (sentiment-iq/, roas-iq/, brand-partnership-iq/, metadata/, reference/,
        # persona_cache/, _backups/, backups/, system/, etc.) and is filtered
        # out here as a safety net for stale cache entries — the cache build
        # paths (smart_cache_update / refresh_s3_cache) already exclude them
        # at ingest time. SVOD/Ticket entries live in different buckets and
        # use synthetic prefixes (svod-acquisition/, ticket-sales-iq/, etc.)
        # — they're stripped above via is_svod_entry / not stored in this cache.
        job_list = [e for e in job_list if '/' not in (e.get('s3_key') or '')]
        
        # Profile IQ must not show SVOD Acquisition — only Subscriber IQ shows those
        def is_svod_entry(e):
            if e.get('is_svod'):
                return True
            sk = (e.get('s3_key') or '')
            jid = (e.get('job_id') or '')
            if sk.startswith('svod-acquisition/') or jid.startswith('svod-acquisition/'):
                return True
            # Catch legacy cache entries that lack is_svod (e.g. old purgatory-released or migrated cache)
            cat = (e.get('category') or '').strip().upper()
            if cat == 'SVOD ACQUISITION':
                return True
            return False
        job_list = [e for e in job_list if not is_svod_entry(e)]
        
        # Filter out OTHER and UNCATEGORIZED categories - these should never appear in profile selector
        job_list = [e for e in job_list if (e.get('category') or '').upper() not in ('OTHER', 'UNCATEGORIZED', '')]
        
        # Gen Pop: always show the canonical S3 key + clean display name so
        # profile selector only ever loads the canonical file and shows "Gen Pop 2026"
        # (not the date-stamped filename of legacy entries).
        seen_gen_pop = False
        new_job_list = []
        for e in job_list:
            sk = (e.get('s3_key') or '').lower()
            if 'gen_pop' in sk:
                if seen_gen_pop:
                    continue  # keep only one Gen Pop entry
                seen_gen_pop = True
                e = dict(e)
                e['s3_key'] = GEN_POP_CANONICAL_KEY
                e['job_id'] = GEN_POP_CANONICAL_KEY
                # Force the clean name regardless of what's in the cache.
                e['project_name'] = 'Gen Pop 2026'
                e['display_name'] = 'Gen Pop 2026'
                e['name'] = 'Gen Pop 2026'
                e['title'] = 'Gen Pop 2026'
            new_job_list.append(e)
        job_list = new_job_list
        
        # Mark run access: tag each profile with 'accessible' flag instead of filtering
        allowed_runs = None
        allowed_categories = None
        u = None
        try:
            _users_data = load_users()
            u = _users_data.get('users', {}).get(session.get('username')) if session.get('username') else None
            if u is not None:
                allowed_runs = u.get('allowed_runs')
                allowed_categories = u.get('allowed_categories')
        except Exception:
            pass
        has_all_access = allowed_runs is None or (isinstance(allowed_runs, list) and len(allowed_runs) == 1 and allowed_runs[0] == '*')
        # Category Access also grants access: if a user is subscribed to a category,
        # all profiles in that category are accessible (not just future ones).
        has_all_cats = (
            allowed_categories is None
            or (isinstance(allowed_categories, list) and '*' in allowed_categories)
        )
        allowed_cats_upper = set()
        if not has_all_cats and isinstance(allowed_categories, list):
            allowed_cats_upper = {(c or '').upper() for c in allowed_categories if c}
        if has_all_access:
            for e in job_list:
                e['accessible'] = True
        else:
            allowed_set = set(allowed_runs or [])
            for e in job_list:
                sk = e.get('s3_key') or ''
                cat_upper = (e.get('category') or '').upper()
                if sk in allowed_set or 'gen_pop' in sk.lower():
                    e['accessible'] = True
                elif has_all_cats or (cat_upper and cat_upper in allowed_cats_upper):
                    e['accessible'] = True
                else:
                    e['accessible'] = False
        
        categories = {e.get('category') for e in job_list if e.get('category')}
        
        # Final safety-net dedup: if the same s3_key somehow ended up in
        # job_list more than once (edge cases like merged cache + local job +
        # purgatory-released item all pointing at the same file), keep the
        # entry with the most-complete metadata (prefers local/in-flight over
        # cached, then prefers entries with a non-empty project_name).
        def _dedup_priority(e):
            src_priority = 0 if e.get('source') == 'local' else 1
            has_name = 0 if (e.get('project_name') or '').strip() else 1
            return (src_priority, has_name)
        deduped = {}
        order_counter = 0
        order_map = {}
        for e in job_list:
            sk = e.get('s3_key') or ''
            if not sk:
                # No s3_key -> can't dedup; keep as-is with a unique synthetic key
                synth = f"__nokey__{order_counter}"
                order_counter += 1
                deduped[synth] = e
                order_map[synth] = order_counter
                continue
            existing = deduped.get(sk)
            if existing is None or _dedup_priority(e) < _dedup_priority(existing):
                deduped[sk] = e
            if sk not in order_map:
                order_counter += 1
                order_map[sk] = order_counter
        job_list = list(deduped.values())

        # Sort by created_at descending (safe key for missing/None values)
        sorted_jobs = sorted(job_list, key=lambda x: x.get('created_at') or '', reverse=True)
        
        return jsonify({
            'jobs': sorted_jobs,
            'categories': sorted(list(categories)),
            'cache_info': {
                'last_updated': s3_cache.get('last_updated'),
                'file_count': s3_cache.get('file_count', 0),
                'cached': True
            }
        })
    except Exception as e:
        traceback.print_exc()
        print(f"⚠️ list_jobs error: {e}")
        # Return empty jobs instead of 500 so UI can still render
        return jsonify({
            'jobs': [],
            'categories': [],
            'cache_info': {'error': str(e), 'cached': False},
            'loading': False
        }), 200


