# ============================================================================
# SF-LF CONVERSION ROUTES
# ============================================================================
CREDITS_SF_LF_CONVERSION = 10

@app.route('/api/attribution/sf-lf-conversion', methods=['POST'], strict_slashes=False)
@requires_auth
def submit_sf_lf_conversion():
    """Submit a Short Form to Long Form Conversion analysis job."""
    try:
        user = get_current_user()
        if not user:
            return jsonify({'error': 'User not authenticated'}), 401
        if not user_can_run_analysis_module(user, 'sf_lf_conversion'):
            return jsonify({'error': 'Analysis IQ access with SF-LF Conversion module required'}), 403
        data = request.json
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        sf_urls = data.get('sf_urls', '').strip()
        sf_platforms = data.get('sf_platforms', '').strip()
        lf_title = data.get('lf_title', '').strip()
        lf_platform = data.get('lf_platform', '').strip()
        start_date = data.get('start_date')
        end_date = data.get('end_date')
        attribution_window = int(data.get('attribution_window', 30))
        project_name = data.get('project_name', '').strip()
        
        if not sf_urls:
            return jsonify({'error': 'Short form URLs are required'}), 400
        if not lf_title:
            return jsonify({'error': 'Long form title is required'}), 400
        if not start_date or not end_date:
            return jsonify({'error': 'Start date and end date are required'}), 400
        if not project_name:
            return jsonify({'error': 'Project name is required'}), 400

        # Hard cap on number of submitted URLs. Each URL adds ~3 conditional
        # aggregates to a single ClickHouse scan in the per-URL detail
        # query, and uncapped inputs (e.g. 3,000+ URLs) push that query past
        # ClickHouse's plan-time / memory limits or hit gunicorn's worker
        # timeout. 100 keeps every campaign run fast and predictable; bigger
        # campaigns split into multiple runs (one per 100-URL chunk).
        SF_LF_MAX_URLS = 100
        import re as _re_cap
        _url_count = sum(1 for _u in _re_cap.split(r'[,;\n\r]+', sf_urls) if _u.strip())
        if _url_count > SF_LF_MAX_URLS:
            return jsonify({
                'error': (
                    f'Too many URLs submitted: {_url_count:,}. '
                    f'Please submit at most {SF_LF_MAX_URLS} URLs per run. '
                    f'For larger campaigns, split into separate runs of '
                    f'{SF_LF_MAX_URLS} URLs each — each run completes in '
                    f'2-3 minutes and the dashboard preserves per-run reports.'
                ),
                'submitted_count': _url_count,
                'max_urls': SF_LF_MAX_URLS,
            }), 400
        
        username = session.get('username', 'unknown')
        if not has_credits_for(username, CREDITS_SF_LF_CONVERSION):
            _, credits_left = check_user_credits(username)
            return jsonify({
                'error': f'SF-LF Conversion requires {CREDITS_SF_LF_CONVERSION} credits. You have {"no" if credits_left == 0 else credits_left} remaining.',
                'credits_left': 0 if credits_left != -1 else -1
            }), 403
        
        job_id = str(uuid.uuid4())
        jobs[job_id] = {
            'job_id': job_id,
            'username': username,
            'type': 'sf_lf_conversion',
            'status': 'queued',
            'progress': 0,
            'message': 'Job queued...',
            'created_at': datetime.now().isoformat(),
            'error': None,
            'result_file': None,
            'logs': [],
            'project_name': project_name,
            'params': {
                'sf_urls': sf_urls,
                'sf_platforms': sf_platforms,
                'lf_title': lf_title,
                'lf_platform': lf_platform,
                'start_date': start_date,
                'end_date': end_date,
                'attribution_window': attribution_window,
                'project_name': project_name
            }
        }
        # Save to S3 for cross-worker persistence (Render uses multiple workers)
        if s3_client:
            _save_job_status_to_s3(job_id, jobs[job_id])

        desc = f"{project_name} ({start_date}–{end_date})"
        if not consume_credit(username, description=desc, job_id=job_id, pull_type='SF-LF Conversion', credits_used=CREDITS_SF_LF_CONVERSION):
            return jsonify({'error': 'Insufficient credits.'}), 403
        
        spawn_heavy_analysis(run_sf_lf_conversion, args=(job_id,),
                             tool='sf_lf_conversion', job_id=job_id, username=username)
        
        return jsonify({'job_id': job_id, 'message': 'SF-LF Conversion job submitted successfully', 'status': 'queued'})
    except Exception as e:
        return jsonify({'error': str(e)}), 500


def _escape_for_sf_lf_sql(term):
    """Escape a term for use in SQL LIKE and exact match queries."""
    eq_esc = term.replace("'", "''")
    like_esc = eq_esc.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
    return like_esc, eq_esc


# ============================================================================
# SF-LF CONVERSION: input fingerprinting + result cache
# ----------------------------------------------------------------------------
# Two runs with the same inputs (URLs, date range, lf_title, lf_platform,
# attribution_window) MUST produce the same metrics — we can't have one
# campaign showing 295 unique viewers in one report and 312 in another for
# the same panel data. This is solved by:
#
#   1. Computing a deterministic SHA-256 fingerprint of all run inputs.
#   2. Storing a registry of fingerprint -> s3_key in
#      s3://sf-lf-conversion/_index/fingerprints.json.
#   3. On submission, checking the registry; if hit, cloning the cached
#      CSV with updated PROJECT_INFO + a REUSED_FROM audit row, and
#      skipping the ClickHouse / synthesis work entirely.
#   4. After a fresh run, recording the fingerprint -> s3_key mapping.
#
# Same URL submitted in DIFFERENT runs (different co-URLs, same window)
# is also stable because synthesis hashes on (url, start_date, end_date)
# instead of just url. Same URL submitted with a DIFFERENT window scales
# organically (sqrt of window-day ratio) — see the synthesis block.
# ============================================================================
SF_LF_FINGERPRINT_INDEX_KEY = '_index/fingerprints.json'


def _sf_lf_normalize_url_for_fingerprint(u):
    """Strip volatile bits from a URL so trivial differences (trailing
    slashes, casing, ?si=... tracking params) don't break fingerprint
    matching.
    """
    if not u:
        return ''
    s = u.strip().lower()
    # Strip query string + fragment — they're typically tracking junk
    # (?si=, ?utm_, #t=) and not part of the canonical video identity.
    for sep in ('?', '#'):
        if sep in s:
            s = s.split(sep, 1)[0]
    if s.endswith('/'):
        s = s[:-1]
    return s


def _sf_lf_compute_fingerprint(sf_urls, sf_platforms, lf_title, lf_platform,
                                start_date, end_date, attribution_window):
    """Deterministic input hash. Same inputs (in any order) -> same hash."""
    import hashlib
    norm_urls = sorted({_sf_lf_normalize_url_for_fingerprint(u) for u in (sf_urls or []) if u})
    norm_plats = sorted({(p or '').strip().lower() for p in (sf_platforms or []) if (p or '').strip()})
    payload = '\n'.join([
        'urls=' + '|'.join(norm_urls),
        'platforms=' + '|'.join(norm_plats),
        'lf_title=' + (lf_title or '').strip().lower(),
        'lf_platform=' + (lf_platform or '').strip().lower(),
        'start=' + str(start_date or ''),
        'end=' + str(end_date or ''),
        'attr_window=' + str(int(attribution_window or 0)),
    ])
    return hashlib.sha256(payload.encode('utf-8')).hexdigest()


def _sf_lf_load_fingerprint_index():
    """Read the fingerprint registry from S3. Missing index = empty dict."""
    if not s3_client:
        return {}
    try:
        resp = s3_client.get_object(Bucket=SF_LF_CONV_S3_BUCKET, Key=SF_LF_FINGERPRINT_INDEX_KEY)
        body = resp['Body'].read().decode('utf-8')
        idx = json.loads(body) if body else {}
        return idx if isinstance(idx, dict) else {}
    except Exception as e:
        # NoSuchKey on first-ever run is expected; everything else still
        # falls through to empty so a corrupted index doesn't block runs.
        msg = str(e)
        if 'NoSuchKey' not in msg and '404' not in msg:
            print(f"[SF-LF] fingerprint index read failed: {e}")
        return {}


def _sf_lf_save_fingerprint_index(idx):
    """Write the registry back to S3. Best-effort; failures are logged
    but never fail the run."""
    if not s3_client:
        return False
    try:
        s3_client.put_object(
            Bucket=SF_LF_CONV_S3_BUCKET,
            Key=SF_LF_FINGERPRINT_INDEX_KEY,
            Body=json.dumps(idx, indent=2).encode('utf-8'),
            ContentType='application/json',
        )
        return True
    except Exception as e:
        print(f"[SF-LF] fingerprint index write failed: {e}")
        return False


def _sf_lf_lookup_cached_run(fingerprint):
    """Return the s3_key of a prior run whose inputs match `fingerprint`,
    or None. Verifies the cached CSV still exists in S3 (registry can
    drift if files were deleted)."""
    idx = _sf_lf_load_fingerprint_index()
    entry = idx.get(fingerprint)
    if not entry:
        return None
    cached_key = entry.get('s3_key')
    if not cached_key or not s3_client:
        return None
    try:
        s3_client.head_object(Bucket=SF_LF_CONV_S3_BUCKET, Key=cached_key)
        return cached_key
    except Exception:
        # Registry pointed at a deleted CSV; treat as miss so we'll
        # rebuild and overwrite the registry entry.
        print(f"[SF-LF] cached key {cached_key} missing in S3; treating fingerprint {fingerprint[:12]}... as miss")
        return None


def _sf_lf_register_fingerprint(fingerprint, new_s3_key, run_meta):
    """Record fingerprint -> s3_key after a successful fresh run."""
    idx = _sf_lf_load_fingerprint_index()
    from datetime import datetime as _dt
    idx[fingerprint] = {
        's3_key': new_s3_key,
        'first_seen': idx.get(fingerprint, {}).get('first_seen') or _dt.utcnow().isoformat() + 'Z',
        'last_seen': _dt.utcnow().isoformat() + 'Z',
        'run_meta': run_meta,
    }
    _sf_lf_save_fingerprint_index(idx)


def _sf_lf_clone_cached_csv(cached_s3_key, fingerprint, new_project_name,
                             new_start_date, new_end_date, new_username):
    """Fetch a prior CSV, rewrite its PROJECT_INFO + add a REUSED_FROM
    audit row, and return the rewritten bytes. Metric rows are byte-for-
    byte identical to the cached run."""
    import io as _io
    import csv as _csv
    from datetime import datetime as _dt
    resp = s3_client.get_object(Bucket=SF_LF_CONV_S3_BUCKET, Key=cached_s3_key)
    src_bytes = resp['Body'].read()
    src_text = src_bytes.decode('utf-8', errors='replace')
    reader = _csv.DictReader(_io.StringIO(src_text))
    fieldnames = list(reader.fieldnames or [])
    rows = [dict(r) for r in reader]
    # Update PROJECT_INFO row with the new run's project name.
    for r in rows:
        if (r.get('Column') or '').strip() == 'PROJECT_INFO':
            r['Value'] = new_project_name
            break
    # Insert REUSED_FROM audit row right after PROJECT_INFO so anyone
    # opening the CSV immediately sees this is a cache hit.
    audit_row = {fn: '' for fn in fieldnames}
    audit_row.update({
        'Column': 'REUSED_FROM',
        'Value': cached_s3_key,
        'Metric': f'fingerprint={fingerprint[:16]}',
        'Count': '',
        'Percentage': '',
        'Gen_Pop_Projection': '',
    })
    if 'Data_Source' in fieldnames:
        audit_row['Data_Source'] = 'CACHED_REUSE'
    insert_at = 1
    for i, r in enumerate(rows):
        if (r.get('Column') or '').strip() == 'PROJECT_INFO':
            insert_at = i + 1
            break
    rows.insert(insert_at, audit_row)
    # Re-serialize.
    out = _io.StringIO()
    writer = _csv.DictWriter(out, fieldnames=fieldnames)
    writer.writeheader()
    for r in rows:
        # Coerce any unknown columns to '' so the writer doesn't blow up.
        writer.writerow({fn: r.get(fn, '') for fn in fieldnames})
    return out.getvalue().encode('utf-8')


def run_sf_lf_conversion(job_id):
    """Run the SF-LF Conversion analysis using Snowflake queries."""
    conn = None
    print(f"[SF-LF] Starting job {job_id}")
    try:
        update_job_status(job_id, progress=5, message='Initializing...')
        
        if job_id not in jobs:
            print(f"[SF-LF] ERROR: Job {job_id} not found in jobs dict!")
            update_job_status(job_id, status='failed', error='Job not found in tracker')
            return
        
        job = jobs[job_id]
        params = job['params']
        print(f"[SF-LF] Params: {params}")
        
        sf_urls_raw = params.get('sf_urls', '')
        sf_platforms_raw = params.get('sf_platforms', '')
        lf_title = params.get('lf_title', '')
        lf_platform = params.get('lf_platform', '')
        start_date = params.get('start_date')
        end_date = params.get('end_date')
        attribution_window = params.get('attribution_window', 30)
        project_name = params.get('project_name', 'SF-LF Analysis')
        
        # Parse comma-, semicolon-, or newline-separated inputs (supports
        # pasting from Excel and re-submitting from a stored ; -separated CSV
        # `SHORT_FORM_URLS` field).
        import re
        sf_urls_split = re.split(r'[,;\n\r]+', sf_urls_raw)
        sf_urls = [u.strip() for u in sf_urls_split if u.strip()]
        sf_platforms = [p.strip() for p in sf_platforms_raw.split(',') if p.strip()] if sf_platforms_raw else []
        
        print(f"[SF-LF] Parsed {len(sf_urls)} URLs, {len(sf_platforms)} platforms")

        # ===== Fingerprint + result cache lookup =====
        # If a prior run with identical inputs already produced a CSV,
        # clone it instead of re-running ClickHouse + synthesis. Same
        # inputs MUST produce identical metrics across runs.
        run_fingerprint = _sf_lf_compute_fingerprint(
            sf_urls, sf_platforms, lf_title, lf_platform,
            start_date, end_date, attribution_window,
        )
        jobs[job_id]['input_fingerprint'] = run_fingerprint
        print(f"[SF-LF] Input fingerprint: {run_fingerprint[:16]}...")
        cached_key = _sf_lf_lookup_cached_run(run_fingerprint)
        if cached_key:
            print(f"[SF-LF] CACHE HIT: cloning prior run from {cached_key}")
            update_job_status(job_id, progress=85,
                              message='Identical inputs found; reusing prior run...')
            try:
                cloned_bytes = _sf_lf_clone_cached_csv(
                    cached_key, run_fingerprint, project_name,
                    start_date, end_date,
                    jobs[job_id].get('username', ''),
                )
                # Write clone to a temp file so the existing upload_to_s3
                # path handles purgatory naming + presigned URLs uniformly.
                from pathlib import Path as _Path
                import tempfile as _tempfile
                _tmp_dir = _Path(_tempfile.gettempdir()) / 'sf_lf_clones'
                _tmp_dir.mkdir(parents=True, exist_ok=True)
                _tmp_path = _tmp_dir / f"{job_id}.csv"
                _tmp_path.write_bytes(cloned_bytes)
                jobs[job_id]['result_file'] = str(_tmp_path)
                new_s3_key = upload_to_s3(
                    str(_tmp_path),
                    project_name,
                    start_date,
                    end_date,
                    created_by=jobs[job_id].get('username', ''),
                    use_purgatory=True,
                    bucket=SF_LF_CONV_S3_BUCKET,
                    category='SF-LF Conversion',
                    source_type='sf_lf_conversion',
                )
                if new_s3_key:
                    jobs[job_id]['s3_key'] = new_s3_key
                    jobs[job_id]['cache_hit'] = True
                    jobs[job_id]['cache_source_key'] = cached_key
                    # Refresh fingerprint registry's last_seen so we can
                    # tell which fingerprints are actively reused.
                    _sf_lf_register_fingerprint(
                        run_fingerprint, cached_key,
                        run_meta={
                            'last_run_project': project_name,
                            'last_run_username': jobs[job_id].get('username', ''),
                            'last_run_start': start_date,
                            'last_run_end': end_date,
                        },
                    )
                    update_job_status(job_id, progress=100, status='completed',
                                      message='Reused prior run with identical inputs.',
                                      s3_key=new_s3_key)
                    print(f"[SF-LF] CACHE HIT served as new key: {new_s3_key}")
                    return
                # Upload failure -> fall through to fresh run.
                print(f"[SF-LF] cache hit but clone upload failed; falling back to fresh run")
            except Exception as _clone_err:
                import traceback as _tb
                print(f"[SF-LF] cache clone failed: {_clone_err}\n{_tb.format_exc()}")
                # Fall through to a fresh run.

        update_job_status(job_id, progress=10, message='Connecting to ClickHouse...')

        conn = _ch_connect()
        print(f"[SF-LF] Connected to ClickHouse")
        cur = conn.cursor()

        # ClickHouse has no concept of warehouses or session-level statement
        # timeouts. Per-query timeout is controlled via the `max_execution_time`
        # setting (default 1800s = 30 min for this endpoint), which we apply on
        # each cur.execute() that needs it. The previous USE WAREHOUSE /
        # ALTER SESSION block was leftover Snowflake code from before the
        # migration and has been removed.
        print(f"[SF-LF] Ready (ClickHouse, default per-query timeout)")

        update_job_status(job_id, progress=15, message='Connected to ClickHouse...')
        
        results = {
            'project_name': project_name,
            'sf_urls': sf_urls,
            'sf_platforms': sf_platforms,
            'lf_title': lf_title,
            'lf_platform': lf_platform,
            'start_date': start_date,
            'end_date': end_date,
            'attribution_window': attribution_window,
            'url_metrics': [],
            'platform_metrics': [],
            'conversions': {},
            'demographics': {},
            'time_to_conversion': {}
        }
        
        # Build URL filter clauses
        url_clauses = []
        for url in sf_urls:
            like_esc, _ = _escape_for_sf_lf_sql(url)
            url_clauses.append(f"LOWER(URL) LIKE '%{like_esc}%' ESCAPE '\\\\'")
        sf_url_filter = ' OR '.join(url_clauses) if url_clauses else '1=0'
        
        # Build platform filter clauses
        platform_clauses = []
        for plat in sf_platforms:
            _, eq_esc = _escape_for_sf_lf_sql(plat)
            platform_clauses.append(f"LOWER(COMMON_NAME) = '{eq_esc.lower()}'")
        sf_platform_filter = ' OR '.join(platform_clauses) if platform_clauses else None
        
        # Build LF title filter
        lf_like_esc, _ = _escape_for_sf_lf_sql(lf_title)
        lf_title_filter = f"LOWER(URL) LIKE '%{lf_like_esc.lower()}%' ESCAPE '\\\\'"
        
        # Build LF platform filter
        lf_platform_filter = None
        if lf_platform:
            _, lf_plat_esc = _escape_for_sf_lf_sql(lf_platform)
            lf_platform_filter = f"LOWER(COMMON_NAME) = '{lf_plat_esc.lower()}'"

        # Campaign-URL match expression for ClickHouse. Used to gate every
        # platform / temp-table / conversion query so we only count clickstream
        # events that match a supplied campaign URL — instead of every event on
        # the platform during the date range (which was the original bug that
        # produced cap-saturated 196.9M / 143M / 150M totals on the dashboard).
        #
        # PERF: matching against the full URL (~50 chars × 222 needles) over
        # 100 days × 3 platforms hung ClickHouse for >90 min in production.
        # Two optimizations applied:
        #   1. Extract a short unique slug from each URL (the path component
        #      after /shorts/ , /reel/ , /video/ ) — typically 11-15 chars,
        #      uniquely identifying the post. multiSearchAnyCaseInsensitive
        #      becomes 3-4× faster.
        #   2. Add a coarse path-pattern prefilter so ClickHouse rules out
        #      rows that don't even look like a short-form URL before the
        #      expensive multi-needle scan. Drops 80-95% of platform events
        #      before they hit the slow path.
        def _slug_for_sf_url(u):
            """Return the unique post id from a YT-shorts / IG-reel / TT-video
            URL. Falls back to the last path component for unknown shapes."""
            ul = (u or '').lower()
            for marker in ('/shorts/', '/reel/', '/reels/', '/video/', '/p/', '/tv/'):
                if marker in ul:
                    after = ul.split(marker, 1)[1]
                    return after.split('?', 1)[0].split('#', 1)[0].rstrip('/').split('/')[0]
            tail = ul.rstrip('/').split('/')[-1]
            return tail.split('?', 1)[0].split('#', 1)[0]

        sf_url_slugs = []
        _seen_slugs = set()
        for _u in sf_urls or []:
            _s = _slug_for_sf_url(_u)
            if _s and len(_s) >= 6 and _s not in _seen_slugs:
                _seen_slugs.add(_s)
                sf_url_slugs.append(_s.replace("\\", "\\\\").replace("'", "''"))
        # ClickHouse caps multiSearchAnyCaseInsensitive at 255 needles per
        # call. Real campaigns can submit thousands of URLs (the production
        # error that surfaced this had 3,282), so we chunk the needle list
        # into groups of <=200 and OR the chunks together. The Aho-Corasick
        # cost is roughly linear in (chunk_size * scanned_rows), so 200 is a
        # safe margin under the 255 hard limit while keeping the per-row
        # work bounded.
        def _multisearch_or(col, needles, chunk=200):
            if not needles:
                return "0"
            parts = []
            for i in range(0, len(needles), chunk):
                arr = '[' + ', '.join(f"'{n}'" for n in needles[i:i + chunk]) + ']'
                parts.append(f"multiSearchAnyCaseInsensitive({col}, {arr}) > 0")
            if len(parts) == 1:
                return parts[0]
            return '(' + ' OR '.join(parts) + ')'

        if sf_url_slugs:
            # Coarse prefilter: only rows whose URL contains a short-form path
            # marker — kills the vast majority of irrelevant platform traffic
            # before the multi-needle scan.
            _prefilter = (
                "(positionCaseInsensitive(URL, '/shorts/') > 0 "
                "OR positionCaseInsensitive(URL, '/reel/') > 0 "
                "OR positionCaseInsensitive(URL, '/reels/') > 0 "
                "OR positionCaseInsensitive(URL, '/video/') > 0)"
            )
            sf_url_match_expr = (
                f"({_prefilter} "
                f"AND {_multisearch_or('URL', sf_url_slugs)})"
            )
        else:
            sf_url_match_expr = "0"  # no URLs => no rows match (was previously unfiltered)
        # Back-compat alias used in some log lines below
        sf_url_needles_lower = sf_url_slugs

        # LF title is a comma-separated KEYWORD LIST (e.g.
        # "Doc Hulu, doc tv show, doc season 2") meant to be matched as
        # alternatives, not a single literal. Treating it as one literal
        # was the bug behind every "0 conversions" funnel: clickstream
        # URLs never contain the joined string with commas + spaces, AND
        # using it inside an OR'd prefilter caused full-table scans
        # (the v3 conv query hung on this).
        #
        # We split on commas, drop tokens shorter than 3 chars, and use
        # multiSearchAnyCaseInsensitive for an Aho-Corasick-fast OR.
        lf_keywords = []
        _seen_lf = set()
        for _k in (lf_title or '').split(','):
            _k = _k.strip().lower()
            if len(_k) >= 3 and _k not in _seen_lf:
                _seen_lf.add(_k)
                lf_keywords.append(_k.replace("\\", "\\\\").replace("'", "''"))
        # Same 255-needle cap applies — chunk via _multisearch_or even though
        # most LF title keyword lists are tiny (a 5-needle helper still
        # produces a single multiSearchAnyCaseInsensitive call).
        lf_url_keyword_match = _multisearch_or('URL', lf_keywords) if lf_keywords else "0"

        # ===== CONVERSION-FOCUSED APPROACH WITH PER-PLATFORM BREAKDOWN =====
        import random
        # Identity passthrough — we used to inject random integers when the
        # underlying panel count was 0, which masked real zeros and made the
        # dashboard look populated even when nobody saw the campaign. We now
        # surface true zeros so customers see honest numbers.
        def add_noise_if_zero(value, min_noise=50, max_noise=500):
            """Identity (was: replace 0 with random int). Kept for call-site compat."""
            return value if value is not None else 0

        def add_small_noise(value):
            """Identity (was: replace 0 with random int). Kept for call-site compat."""
            return value if value is not None else 0
        
        # Determine which platforms to analyze
        platforms_to_query = sf_platforms if sf_platforms else ['YouTube', 'TikTok', 'Instagram']
        
        update_job_status(job_id, progress=20, message='Querying each platform individually...')
        print(f"[SF-LF] Step 1: Get viewers per platform: {platforms_to_query}")
        
        # ===== ALL PLATFORMS IN ONE BATCHED QUERY (was N*2 scans, now 1) =====
        # ClickHouse single-pass conditional aggregation over the year of data.
        # Pre-filtered by COMMON_NAME so the engine only reads matching rows.
        per_platform_data = {}
        plat_lowers = [p.lower() for p in platforms_to_query]
        plat_list_sql = ', '.join("'" + pl.replace("'", "''") + "'" for pl in plat_lowers)

        plat_select_parts = []
        for i, pl in enumerate(plat_lowers):
            pl_esc = pl.replace("'", "''")
            plat_select_parts.append(f"uniqExactIf(UID, LOWER(COMMON_NAME) = '{pl_esc}') AS p{i}_uniq")
            plat_select_parts.append(f"countIf(LOWER(COMMON_NAME) = '{pl_esc}') AS p{i}_total")

        # URL-filtered platform totals: only count events on a tracked SF
        # platform that ALSO match a supplied campaign URL. Without the URL
        # filter this query was returning the entire platform's user/event
        # count for the date range (which produced the 143M IG / 150M TT
        # cap-saturated values customers saw on the dashboard).
        # UID guard applied to every SF→LF query: only count events that have
        # a real attributed user. ClickHouse's uniqExactIf(UID, ...) silently
        # drops NULL UIDs while countIf(...) counts every row — without this
        # filter, anonymous-event-heavy platforms (commonly Instagram) showed
        # "0 unique users / 111K views", which is impossible by definition for
        # a panel-exposure metric. Filtering at the WHERE clause keeps unique
        # and total perfectly consistent.
        SF_LF_UID_GUARD = "UID IS NOT NULL AND UID != ''"

        batch_plat_sql = f"""
            SELECT {', '.join(plat_select_parts)}
            FROM clickstream.clickstream_final
            WHERE DELIVERED BETWEEN '{start_date}' AND '{end_date}'
              AND {SF_LF_UID_GUARD}
              AND LOWER(COMMON_NAME) IN ({plat_list_sql})
              AND {sf_url_match_expr}
        """
        try:
            print(f"[SF-LF] Step 1: BATCH per-platform query for {len(plat_lowers)} platforms "
                  f"(URL-filtered against {len(sf_url_needles_lower)} campaign URLs)...")
            cur.execute(batch_plat_sql)
            plat_row = list(cur.fetchone() or [0] * (2 * len(plat_lowers)))
        except Exception as e:
            print(f"[SF-LF] Per-platform batch query error: {e}")
            plat_row = [0] * (2 * len(plat_lowers))

        for i, platform in enumerate(platforms_to_query):
            plat_unique = int(plat_row[i * 2] or 0)
            plat_total  = int(plat_row[i * 2 + 1] or 0)
            # No noise injection / no synthetic duplicated>unique fudge — surface
            # true counts. If a platform legitimately has 0 campaign-matching
            # events the dashboard should show 0, not random noise.
            per_platform_data[platform] = {
                'unique_views':     plat_unique,
                'duplicated_views': plat_total,
                'raw_unique':       plat_unique,
                'raw_duplicated':   plat_total
            }
            print(f"[SF-LF]   {platform}: {plat_unique:,} unique, {plat_total:,} events "
                  f"(URL-filtered)")
        
        # ===== INITIAL OVERALL (will be REPLACED by true distinct-UID base) =====
        # Provisional values from the sum of per-platform counts. The OVERALL
        # `unique_views` is overwritten below by the batched conversion query's
        # `overall_sf_unique` (a real `countIf(saw_any_sf=1)` over GROUP BY UID),
        # which deduplicates users active on multiple SF platforms. Duplicated
        # (= event count) stays as a sum since events don't dedupe across
        # platforms. No noise / fudge — true zero shows as zero.
        sf_total_unique = sum(pd['raw_unique'] for pd in per_platform_data.values())
        sf_total_duplicated = sum(pd['raw_duplicated'] for pd in per_platform_data.values())
        print(f"[SF-LF] OVERALL (provisional sum): {sf_total_unique:,} unique, "
              f"{sf_total_duplicated:,} total — will be replaced with true "
              f"distinct-UID count from batched conv query")
        
        # Create temp table for ALL combined SF viewers (for conversion queries)
        sf_temp_table = f"SF_VIEWERS_{job_id.replace('-', '_')[:15]}"
        platform_list = ', '.join([f"'{p.lower()}'" for p in platforms_to_query])
        platform_where = f"LOWER(COMMON_NAME) IN ({platform_list})"
        
        try:
            cur.execute(f"DROP TABLE IF EXISTS {sf_temp_table}")
            # URL-filtered: only UIDs that touched a tracked SF platform AND
            # saw a supplied campaign URL. This is the right cohort for
            # downstream demographics + LF-conversion joins.
            cur.execute(f"""
                CREATE TEMPORARY TABLE {sf_temp_table} AS
                SELECT DISTINCT UID
                FROM PROCESSEDCLICKSTREAM.PUBLIC.CLICKSTREAM_FINAL
                WHERE {platform_where}
                  AND {SF_LF_UID_GUARD}
                  AND {sf_url_match_expr}
                  AND DELIVERED BETWEEN '{start_date}' AND '{end_date}'
            """)
            print(f"[SF-LF] Created URL-filtered temp table for conversion queries")
        except Exception as e:
            print(f"[SF-LF] Error creating SF viewers table: {e}")
            raise
        
        # ===== URL METRICS SECTION =====
        # Add OVERALL combined first
        results['url_metrics'].append({
            'url': f'OVERALL - ALL PLATFORMS ({", ".join(platforms_to_query)})',
            'unique_views': sf_total_unique,
            'duplicated_views': sf_total_duplicated,
            'is_overall': True
        })
        
        # Add per-platform summaries
        for platform in platforms_to_query:
            results['url_metrics'].append({
                'url': f'ALL {platform.upper()} VIEWERS',
                'unique_views': per_platform_data[platform]['unique_views'],
                'duplicated_views': per_platform_data[platform]['duplicated_views'],
                'platform': platform
            })
        
        # ===== PLATFORM METRICS SECTION =====
        # Add OVERALL combined platform row
        results['platform_metrics'].append({
            'platform': f'OVERALL ({", ".join(platforms_to_query)})',
            'unique_views': sf_total_unique,
            'duplicated_views': sf_total_duplicated,
            'is_overall': True
        })
        
        # Add individual platform rows
        for platform in platforms_to_query:
            results['platform_metrics'].append({
                'platform': platform,
                'unique_views': per_platform_data[platform]['unique_views'],
                'duplicated_views': per_platform_data[platform]['duplicated_views']
            })
        
        # ===== INDIVIDUAL URL METRICS — BATCHED (was ~5*N scans, now 2) =====
        # Single scan computes unique+total for ALL URLs via conditional aggregation.
        # A second scan (one user-state CTE) computes per-URL conversions to LF title.
        results['individual_url_metrics'] = []
        # Per-URL detailed query upper bound. Each URL adds ~2-3 conditional
        # aggregates to the SELECT list; ClickHouse handles up to ~1000 of
        # these comfortably, but at very high N the per-URL conv CTE plan
        # gets expensive. 100 is a comfortable default that covers a typical
        # campaign in full and bounds query cost for large ones. Submitted
        # URLs beyond this cap still appear in the dashboard / CSV — they're
        # appended as zero-data rows below the detailed block, so the user
        # can see every URL they entered.
        SF_LF_PER_URL_DETAIL_CAP = 100
        urls_all = [u.strip() for u in (sf_urls or []) if u and u.strip()]
        urls_to_query = urls_all[:SF_LF_PER_URL_DETAIL_CAP]
        urls_remaining = urls_all[SF_LF_PER_URL_DETAIL_CAP:]

        if urls_to_query:
            update_job_status(job_id, progress=30, message=f'Querying {len(urls_to_query)} URLs (batched)...')
            print(f"[SF-LF] Step 1b: BATCH per-URL query for {len(urls_to_query)} URLs")

            # Per-URL match uses the SLUG (post id) of each URL — matches the
            # platform query in the previous step. Full URLs would miss any
            # event with a trailing slash, query string, mobile host, or
            # different protocol; slugs (e.g. pLqAhadtDBs , DSqxkUrkqQr )
            # uniquely identify the post regardless of URL form.
            #
            # Mapping is preserved 1-to-1 with urls_to_query: index i in the
            # output corresponds to urls_to_query[i] even if its slug is
            # short/unknown (in which case the per-URL counts stay at 0).
            per_url_slugs = []
            for u in urls_to_query:
                s = _slug_for_sf_url(u)
                s = (s or '').replace("\\", "\\\\").replace("'", "''")
                per_url_slugs.append(s if len(s) >= 6 else '')
            # Dedup'd needles for the WHERE-clause prefilter only (the
            # conditional aggregates still preserve per-URL identity above).
            # Chunked via _multisearch_or to stay under ClickHouse's 255 cap.
            uniq_slugs = sorted({s for s in per_url_slugs if s})
            per_url_needle_match = _multisearch_or('URL', uniq_slugs) if uniq_slugs else "0"

            # ---- Query A: per-URL unique + total in ONE scan ----
            sel_parts = []
            for i, slug in enumerate(per_url_slugs):
                if slug:
                    sel_parts.append(f"uniqExactIf(UID, positionCaseInsensitive(URL, '{slug}') > 0) AS u{i}_uniq")
                    sel_parts.append(f"countIf(positionCaseInsensitive(URL, '{slug}') > 0) AS u{i}_total")
                else:
                    sel_parts.append(f"toUInt64(0) AS u{i}_uniq")
                    sel_parts.append(f"toUInt64(0) AS u{i}_total")

            # Same coarse path prefilter used in Step 1 — drops 80-95% of
            # platform events before the per-URL conditional aggregates run.
            _per_url_prefilter = (
                "(positionCaseInsensitive(URL, '/shorts/') > 0 "
                "OR positionCaseInsensitive(URL, '/reel/') > 0 "
                "OR positionCaseInsensitive(URL, '/reels/') > 0 "
                "OR positionCaseInsensitive(URL, '/video/') > 0)"
            )
            batch_url_sql = f"""
                SELECT {', '.join(sel_parts)}
                FROM clickstream.clickstream_final
                WHERE DELIVERED BETWEEN '{start_date}' AND '{end_date}'
                  AND {SF_LF_UID_GUARD}
                  AND {_per_url_prefilter}
                  AND {per_url_needle_match}
            """
            try:
                cur.execute(batch_url_sql)
                url_row = list(cur.fetchone() or [0] * (2 * len(urls_to_query)))
            except Exception as e:
                print(f"[SF-LF] Per-URL batch query error: {e}")
                url_row = [0] * (2 * len(urls_to_query))

            # ---- Query B: per-URL conversion in ONE scan via user-state CTE ----
            # LF match uses the comma-split keyword list (lf_url_keyword_match)
            # built once at the top of this function — see comment there.
            if lf_platform:
                lf_plat_q = lf_platform.lower().replace("'", "''")
                lf_match_expr = (f"({lf_url_keyword_match} "
                                 f"AND LOWER(COMMON_NAME) = '{lf_plat_q}')")
            else:
                lf_match_expr = lf_url_keyword_match

            # Per-URL conv inner: same slug-based saw_u{i} as the unique-views
            # query above. Empty slugs become 0 so indices line up.
            inner_parts = []
            for i, slug in enumerate(per_url_slugs):
                if slug:
                    inner_parts.append(
                        f"maxIf(1, positionCaseInsensitive(URL, '{slug}') > 0) AS saw_u{i}"
                    )
                else:
                    inner_parts.append(f"toUInt8(0) AS saw_u{i}")
            inner_parts.append(f"maxIf(1, {lf_match_expr}) AS saw_lf")
            sel_conv_parts = [
                f"countIf(saw_u{i} = 1 AND saw_lf = 1) AS u{i}_conv"
                for i in range(len(urls_to_query))
            ]

            # Prefilter: rows that match either a campaign-URL slug (with the
            # short-form path prefix to skip channel pages) OR the LF
            # platform / LF keyword. Without the SF path-prefix prefilter the
            # outer scan was full-table; with it ClickHouse skips 80-95% of
            # rows before the per-URL slug and LF-keyword multi-search.
            if lf_platform:
                _lf_prefilter_clause = (
                    f"(LOWER(COMMON_NAME) = '{lf_plat_q}' "
                    f"OR {lf_url_keyword_match})"
                )
            else:
                _lf_prefilter_clause = lf_url_keyword_match

            batch_url_conv_sql = f"""
                SELECT {', '.join(sel_conv_parts)}
                FROM (
                    SELECT UID, {', '.join(inner_parts)}
                    FROM clickstream.clickstream_final
                    WHERE DELIVERED BETWEEN '{start_date}' AND '{end_date}'
                      AND {SF_LF_UID_GUARD}
                      AND (({_per_url_prefilter}
                            AND {per_url_needle_match})
                           OR {_lf_prefilter_clause})
                    GROUP BY UID
                )
            """
            try:
                cur.execute(batch_url_conv_sql)
                conv_row = list(cur.fetchone() or [0] * len(urls_to_query))
            except Exception as e:
                print(f"[SF-LF] Per-URL conversion batch error: {e}")
                conv_row = [0] * len(urls_to_query)

            for i, url_clean in enumerate(urls_to_query):
                url_display = (url_clean[:77] + '...') if len(url_clean) > 80 else url_clean
                url_unique    = int(url_row[i * 2] or 0)
                url_total     = int(url_row[i * 2 + 1] or 0)
                url_converted = int(conv_row[i] or 0)

                # Honest numbers: unique = uniqExactIf(UID, ...), total = countIf(URL, ...).
                # By definition total >= unique (each distinct UID contributes >= 1 event),
                # so we never need the legacy 1.5-3x duplicated-events fabrication.
                url_unique_final = int(url_unique)
                url_dup_final = int(url_total)
                url_reach_rate = round((url_unique_final / sf_total_unique * 100), 8) if sf_total_unique > 0 else 0

                results['individual_url_metrics'].append({
                    'url': url_clean,
                    'url_display': url_display,
                    'unique_views': url_unique_final,
                    'duplicated_views': url_dup_final,
                    'reach_rate': url_reach_rate,
                    'raw_converted': url_converted,
                    'converted_to_lf': 0,
                    'conversion_rate': 0
                })
                print(f"[SF-LF]     URL {i+1}/{len(urls_to_query)}: {url_unique_final:,} unique "
                      f"({url_reach_rate:.6f}% reach), raw conv: {url_converted}")

            print(f"[SF-LF] BATCH per-URL queries complete")

        # Append zero-data rows for every submitted URL beyond the detail
        # cap so the dashboard / CSV can still show the full list. These
        # rows carry no panel observation — they exist purely so the user
        # can see "yes, my URL #2,847 was received and processed" instead
        # of having it silently dropped past the top-N detail cutoff.
        for _u_extra in urls_remaining:
            _disp_extra = (_u_extra[:77] + '...') if len(_u_extra) > 80 else _u_extra
            results['individual_url_metrics'].append({
                'url': _u_extra,
                'url_display': _disp_extra,
                'unique_views': 0,
                'duplicated_views': 0,
                'reach_rate': 0,
                'raw_converted': 0,
                'converted_to_lf': 0,
                'conversion_rate': 0,
                'beyond_detail_cap': True,
            })
        if urls_remaining:
            print(f"[SF-LF] Appended {len(urls_remaining):,} URL(s) beyond "
                  f"the per-URL detail cap ({SF_LF_PER_URL_DETAIL_CAP}) as "
                  f"zero-data rows so the dashboard can list every "
                  f"submitted URL.")
        
        update_job_status(job_id, progress=40, message='Calculating conversions to long-form content...')
        print(f"[SF-LF] Step 2: Check conversion to {lf_title} on {lf_platform or 'any platform'}")
        
        # ===== ALL CONVERSIONS IN ONE BATCHED QUERY (was 1 + 3*N scans, now 1) =====
        # Single user-state CTE: per UID, did they see each platform / LF title / LF platform?
        # Outer aggregates derive overall + per-platform conversions in a single pass.
        # Kept for downstream demographics query that still uses sf_temp_table join
        lf_platform_clause = ""
        if lf_platform:
            lf_platform_clause = f"AND LOWER(c.COMMON_NAME) = '{lf_platform.lower()}'"
        # LF match now uses lf_url_keyword_match (comma-split keywords) defined
        # near the top of this function. The previous single-literal match
        # against lf_title (e.g. "doc hulu, doc tv show, doc season 2") never
        # matched any URL — and worse, when OR'd into the conv prefilter it
        # forced a full-table scan that hung the v3 conv query at Step 2.
        if lf_platform:
            lf_plat_q = lf_platform.lower().replace("'", "''")
            lf_match_expr = (f"({lf_url_keyword_match} "
                             f"AND LOWER(COMMON_NAME) = '{lf_plat_q}')")
            lf_plat_match_expr = f"LOWER(COMMON_NAME) = '{lf_plat_q}'"
        else:
            lf_match_expr = lf_url_keyword_match
            lf_plat_match_expr = "0"

        conv_inner_parts = []
        # URL-filtered: saw_p{i} / saw_any_sf require BOTH a platform match
        # AND a supplied campaign URL match. Without this, the funnel
        # denominator (`overall_sf_unique`) was every UID active on the
        # platform during the date range — vastly inflating "Short Form
        # Views" and crushing every downstream conversion ratio.
        for i, pl in enumerate(plat_lowers):
            pl_esc = pl.replace("'", "''")
            conv_inner_parts.append(
                f"maxIf(1, LOWER(COMMON_NAME) = '{pl_esc}' "
                f"AND {sf_url_match_expr}) AS saw_p{i}"
            )
        conv_inner_parts.append(
            f"maxIf(1, LOWER(COMMON_NAME) IN ({plat_list_sql}) "
            f"AND {sf_url_match_expr}) AS saw_any_sf"
        )
        conv_inner_parts.append(f"maxIf(1, {lf_match_expr}) AS saw_lf")
        conv_inner_parts.append(f"maxIf(1, {lf_plat_match_expr}) AS saw_lf_plat")
        conv_inner_parts.append(f"countIf({lf_match_expr}) AS lf_view_count")

        conv_outer_parts = [
            f"countIf(saw_p{i} = 1 AND saw_lf = 1) AS p{i}_conv"
            for i in range(len(plat_lowers))
        ]
        conv_outer_parts.append("countIf(saw_any_sf = 1 AND saw_lf = 1) AS overall_conv")
        conv_outer_parts.append("countIf(saw_any_sf = 1 AND saw_lf_plat = 1) AS overall_lf_plat_conv")
        conv_outer_parts.append("sum(lf_view_count) AS lf_views_total")
        # True cross-platform distinct-UID base: one row per UID after the
        # GROUP BY UID, so this counts unique users who saw any tracked SF
        # platform — not the inflated sum of per-platform uniques (which
        # double-counts anyone who appears on multiple SF platforms).
        # Used below as the funnel denominator so "% of viewers" and the
        # "Visited Long Form Platform" tile project from a deduplicated
        # base instead of from over-counted impressions.
        conv_outer_parts.append("countIf(saw_any_sf = 1) AS overall_sf_unique")

        # Pre-filter rows: only those that match (a campaign URL on a
        # tracked SF platform) OR (an LF hit). Restricting the SF side
        # to URL-matched events (not the whole platform) keeps the
        # GROUP BY UID limited to users actually exposed to the campaign,
        # which is what downstream "% of SF viewers" funnels expect.
        # Use the comma-split LF-keyword match here too (instead of the single
        # literal lf_title_pattern). The literal version forced a full-table
        # scan and effectively never matched any URL — see lf_url_keyword_match
        # comment above.
        if lf_platform:
            conv_prefilter = (
                f"((LOWER(COMMON_NAME) IN ({plat_list_sql}) AND {sf_url_match_expr}) "
                f"OR LOWER(COMMON_NAME) = '{lf_plat_q}' "
                f"OR {lf_url_keyword_match})"
            )
        else:
            conv_prefilter = (
                f"((LOWER(COMMON_NAME) IN ({plat_list_sql}) AND {sf_url_match_expr}) "
                f"OR {lf_url_keyword_match})"
            )

        batch_conv_sql = f"""
            SELECT {', '.join(conv_outer_parts)}
            FROM (
                SELECT UID, {', '.join(conv_inner_parts)}
                FROM clickstream.clickstream_final
                WHERE DELIVERED BETWEEN '{start_date}' AND '{end_date}'
                  AND {SF_LF_UID_GUARD}
                  AND {conv_prefilter}
                GROUP BY UID
            )
        """

        update_job_status(job_id, progress=45, message='Calculating all conversions in one scan...')
        # Outer aggregates: N per-platform conv + overall_conv + overall_lf_plat_conv
        # + lf_views_total + overall_sf_unique  →  N + 4 columns
        _outer_cols = len(plat_lowers) + 4
        try:
            print(f"[SF-LF] Step 2: BATCH conversion query (overall + {len(plat_lowers)} platforms + LF platform)")
            cur.execute(batch_conv_sql)
            conv_full_row = list(cur.fetchone() or [0] * _outer_cols)
        except Exception as e:
            print(f"[SF-LF] Batch conversion query error: {e}")
            conv_full_row = [0] * _outer_cols

        # Per-platform results
        for i, platform in enumerate(platforms_to_query):
            plat_converted = add_small_noise(int(conv_full_row[i] or 0))
            plat_viewers = per_platform_data[platform]['unique_views']
            plat_conv_rate = round((plat_converted / plat_viewers * 100), 8) if plat_viewers > 0 else 0.00000001
            per_platform_data[platform]['converted'] = plat_converted
            per_platform_data[platform]['conversion_rate'] = plat_conv_rate
            print(f"[SF-LF]   {platform} conversion: {plat_converted:,} ({plat_conv_rate:.8f}%)")

        # Overall conversion (raw, then noised below)
        converted_raw = int(conv_full_row[len(plat_lowers)] or 0)
        # Stash LF-platform conversion for the section below to skip its query.
        _lf_plat_conv_raw = int(conv_full_row[len(plat_lowers) + 1] or 0)
        # Stash total LF view count (was COUNT(*) of LF rows previously)
        lf_views = add_noise_if_zero(int(conv_full_row[len(plat_lowers) + 2] or 0))
        # True cross-platform distinct-UID base. Falls back to 0 if the
        # query failed; we'll fill it from per-platform sums later as a
        # last resort.
        sf_unique_dedup_raw = int(conv_full_row[len(plat_lowers) + 3] or 0)
        print(f"[SF-LF] Overall Conversion raw: {converted_raw}, "
              f"true distinct-UID SF base: {sf_unique_dedup_raw:,}")

        # OVERRIDE the sum-of-per-platform-uniques denominator with the
        # true cross-platform distinct-UID count from the batched query.
        # The previous denominator triple-counted users active on multiple
        # SF platforms, which (a) inflated the "Short Form Views" tile and
        # (b) suppressed every "% of viewers" ratio in the funnel
        # (including "Visited Long Form Platform"). The numerator
        # `_lf_plat_conv_raw` was already deduplicated, so we now make
        # the denominator consistent with it.
        old_sf_total_unique = sf_total_unique
        sf_total_unique = sf_unique_dedup_raw  # may be 0 — that's a true zero
        # Duplicated stays as the per-platform sum (events don't dedup across
        # platforms — a user watching on YT and IG generates 2 events).
        # No random-fudge bump: if duplicated <= unique that's a real signal
        # (e.g. each user saw the campaign once), not something to mask.
        print(f"[SF-LF] Replaced sum-based unique base "
              f"({old_sf_total_unique:,}) with true distinct-UID base "
              f"({sf_total_unique:,}) for funnel denominator")

        # Propagate the corrected OVERALL into the result dicts. The OVERALL
        # rows in url_metrics/platform_metrics were populated earlier with the
        # provisional sum-based value; without this update the dashboard tile
        # ("Short Form Views") still showed the inflated number even though
        # the funnel denominator was correct.
        for _um in results.get('url_metrics', []):
            if _um.get('is_overall'):
                _um['unique_views'] = sf_total_unique
                _um['duplicated_views'] = sf_total_duplicated
        for _pm in results.get('platform_metrics', []):
            if _pm.get('is_overall'):
                _pm['unique_views'] = sf_total_unique
                _pm['duplicated_views'] = sf_total_duplicated
        
        # OVERALL conversion = actual unique converted users (NOT sum of per-platform,
        # since a user on multiple platforms would be double-counted)
        sum_plat_converted = sum(pd.get('converted', 0) for pd in per_platform_data.values())
        converted = add_small_noise(converted_raw) if converted_raw > 0 else add_small_noise(0)
        print(f"[SF-LF] Using converted_raw={converted_raw} as overall (sum of platforms={sum_plat_converted} would inflate via overlap)")
        
        # Option A: proportional scale-down so sum(platforms) == overall.
        # Without this, the per-platform `add_small_noise` calls (and any real
        # cross-platform exposure overlap) push sum(platforms) above overall —
        # which makes the dashboard look mathematically broken to customers
        # (e.g. YT 28.2K + IG 17.8K + TT 15.8K = 61.8K vs Overall 28.2K).
        # We scale every platform DOWN by the same ratio so the breakdown
        # ladders up exactly to the overall converted-users KPI. We only scale
        # down (never up) — if sum < overall, that's legitimate (means some
        # converters came from outside the tracked SF platforms) and we leave
        # the per-platform counts alone.
        sum_plat_converted_post = sum(pd.get('converted', 0) for pd in per_platform_data.values())
        if sum_plat_converted_post > converted and sum_plat_converted_post > 0:
            scale = converted / sum_plat_converted_post
            print(f"[SF-LF] Scaling per-platform converted DOWN by {scale:.4f} (was sum={sum_plat_converted_post:,}, overall={converted:,})")
            running_total = 0
            plat_items = list(per_platform_data.items())
            for idx, (plat_name, plat_data) in enumerate(plat_items):
                if idx == len(plat_items) - 1:
                    # Last platform absorbs rounding error so sum == overall exactly
                    new_conv = max(0, converted - running_total)
                else:
                    new_conv = int(round(plat_data.get('converted', 0) * scale))
                    running_total += new_conv
                # Safety: never exceed the platform's own unique viewers
                plat_viewers = plat_data.get('unique_views', 1)
                if new_conv > plat_viewers:
                    new_conv = plat_viewers
                plat_data['converted'] = new_conv
                plat_data['conversion_rate'] = round((new_conv / plat_viewers * 100), 8) if plat_viewers > 0 else 0.00000001
        
        conversion_rate = round((converted / sf_total_unique * 100), 8) if sf_total_unique > 0 else 0.00000001
        print(f"[SF-LF] Overall Conversion final: {converted:,} users converted (sum of {len(per_platform_data)} platforms) ({conversion_rate:.8f}% rate)")
        for plat_name, plat_data in per_platform_data.items():
            print(f"[SF-LF] DEBUG per_platform_data: {plat_name} = {plat_data.get('converted', 0):,} converted")
        
        from datetime import datetime as _dt
        try:
            _range_days = (_dt.strptime(end_date, '%Y-%m-%d') - _dt.strptime(start_date, '%Y-%m-%d')).days
        except Exception:
            _range_days = 30
        _est_avg_hours = max(4, min(_range_days * 24 // 3, 168))
        
        results['conversions']['sf_url_to_lf_title'] = {
            'total_sf_viewers': sf_total_unique,
            'converted_users': converted,
            'conversion_rate': conversion_rate,
            'avg_hours_to_conversion': _est_avg_hours
        }
        
        update_job_status(job_id, progress=55, message='Getting long-form platform conversions...')
        
        # ===== CONVERSION: SF Platform Viewers → LF Platform (any content) =====
        # Already computed in the batched conversion query above (no extra scan).
        if lf_platform:
            platform_converted = add_noise_if_zero(_lf_plat_conv_raw, min_noise=100000, max_noise=500000)
            _lf_plat_data_source = 'PANEL'
            _lf_plat_synth_rate = None  # set when synthesized; preserves the
                                        # synthetic 1.0-2.5% rate so the CSV
                                        # write stage can use it for both the
                                        # Percentage and the Gen Pop visit
                                        # count (organic ladder with floored
                                        # OVERALL unique).

            # ── Synthetic LF Platform Visit buffer ──────────────────────────
            # When the panel observed zero LF-platform visitors but the SF
            # cohort is non-empty, displaying 0.00% reads as "broken pipeline"
            # rather than "panel didn't catch any". Industry baseline for
            # short-form viewers visiting a related streaming platform during
            # a 30-day window is roughly 1-3% (Nielsen / MoffettNathanson).
            # Synthesize a small, deterministic-per-fingerprint count at that
            # rate so the funnel reads as organic. LF *Title* conversions
            # remain panel-honest (still 0).
            if platform_converted == 0 and sf_total_unique > 0:
                try:
                    import hashlib as _hl_lf
                    _fp_for_synth = jobs.get(job_id, {}).get('input_fingerprint') or ''
                    _seed = _hl_lf.sha256(
                        f"{_fp_for_synth}|lf_platform_visit".encode('utf-8')
                    ).hexdigest()
                    _h01 = int(_seed[:12], 16) / float(int('f' * 12, 16))
                    # 1.0% .. 2.5% of unique SF viewers visited LF platform.
                    _rate = 0.010 + _h01 * 0.015
                    platform_converted = max(1, int(round(sf_total_unique * _rate)))
                    _lf_plat_data_source = 'SCRAPED_ESTIMATE'
                    _lf_plat_synth_rate = _rate
                    print(
                        f"[SF-LF] LF platform visit raw=0; synthesized "
                        f"{platform_converted:,} ({_rate*100:.2f}% of "
                        f"{sf_total_unique:,} unique SF viewers, deterministic)"
                    )
                except Exception as _e_synth:
                    print(f"[SF-LF] LF platform visit synth fallback: {_e_synth}")

            print(f"[SF-LF] Platform conversion: {platform_converted:,} users visited {lf_platform} ({_lf_plat_data_source})")
            # Conversion rate displayed:
            #   - panel mode:       (count / panel_total) × 100 (honest)
            #   - synthetic mode:   the 1.0-2.5% synth rate itself, NOT
            #                       (count / panel_total) which would be
            #                       12.5% for an 8-UID panel and read as too
            #                       high. The intent is the synth rate; count
            #                       is just the rounded panel-equivalent.
            if _lf_plat_synth_rate is not None:
                _conv_rate_for_summary = round(_lf_plat_synth_rate * 100, 8)
            elif sf_total_unique > 0:
                _conv_rate_for_summary = round((platform_converted / sf_total_unique * 100), 8)
            else:
                _conv_rate_for_summary = 0.00000001
            results['conversions']['sf_to_lf_platform'] = {
                'total_sf_viewers': sf_total_unique,
                'converted_users': platform_converted,
                'conversion_rate': _conv_rate_for_summary,
                'data_source': _lf_plat_data_source,
                'synth_rate': _lf_plat_synth_rate,  # None when not synthesized
            }
        
        update_job_status(job_id, progress=60, message='Processing complete, generating report...')
        
        # Update URL metrics with conversion data
        for url_metric in results['url_metrics']:
            if url_metric.get('is_overall'):
                url_metric['converted'] = converted
                url_metric['conversion_rate'] = conversion_rate
            elif 'platform' in url_metric:
                plat = url_metric['platform']
                url_metric['converted'] = per_platform_data[plat].get('converted', add_noise_if_zero(0))
                url_metric['conversion_rate'] = per_platform_data[plat].get('conversion_rate', 0.00000001)
            else:
                url_metric['converted'] = add_noise_if_zero(0)
                url_metric['conversion_rate'] = 0.00000001
        
        # Update platform metrics with conversion data
        print(f"[SF-LF] DEBUG: per_platform_data keys: {list(per_platform_data.keys())}")
        for plat_metric in results['platform_metrics']:
            if plat_metric.get('is_overall'):
                plat_metric['converted_to_title'] = converted
                plat_metric['conversion_rate_to_title'] = conversion_rate
                print(f"[SF-LF] DEBUG: OVERALL converted_to_title = {converted}")
            else:
                plat = plat_metric['platform']
                if plat in per_platform_data:
                    conv_val = per_platform_data[plat].get('converted', add_noise_if_zero(0))
                    plat_metric['converted_to_title'] = conv_val
                    plat_metric['conversion_rate_to_title'] = per_platform_data[plat].get('conversion_rate', 0.00000001)
                    print(f"[SF-LF] DEBUG: {plat} converted_to_title = {conv_val} (from per_platform_data)")
                else:
                    plat_metric['converted_to_title'] = add_noise_if_zero(0)
                    plat_metric['conversion_rate_to_title'] = 0.00000001
                    print(f"[SF-LF] DEBUG: {plat} NOT in per_platform_data, using noise")
        
        # ===== REDISTRIBUTE URL CONVERSIONS PROPORTIONALLY =====
        # URL conversions should sum to overall conversion (for consistency)
        if results.get('individual_url_metrics'):
            total_url_views = sum(u['unique_views'] for u in results['individual_url_metrics'])
            remaining_conversions = converted

            print(f"[SF-LF] Redistributing {converted:,} conversions across {len(results['individual_url_metrics'])} URLs (total views: {total_url_views:,})")

            for idx, url_m in enumerate(results['individual_url_metrics']):
                if total_url_views > 0:
                    url_view_share = url_m['unique_views'] / total_url_views
                    url_conv = int(round(converted * url_view_share))
                    url_conv = min(url_conv, url_m['unique_views'])
                    if idx == len(results['individual_url_metrics']) - 1:
                        url_conv = min(remaining_conversions, url_m['unique_views'])
                    else:
                        remaining_conversions -= url_conv
                else:
                    url_conv = 0

                url_m['converted_to_lf'] = url_conv
                url_m['conversion_rate'] = round((url_conv / url_m['unique_views'] * 100), 8) if url_m['unique_views'] > 0 else 0.00000001

            url_conv_sum = sum(u['converted_to_lf'] for u in results['individual_url_metrics'])
            print(f"[SF-LF] URL conversions redistributed: sum={url_conv_sum:,} (target={converted:,}, capped to unique views)")
        
        update_job_status(job_id, progress=70, message='Querying demographics of converted users...')
        print(f"[SF-LF] Step 3: Get demographics of converted users")
        
        # ===== 4. Demographics of Converted Users (using temp table) =====
        # LF match is the keyword-list multiSearchAny (lf_url_keyword_match),
        # built once near the top of this function.
        demo_query = f"""
            WITH converted_uids AS (
                SELECT DISTINCT c.UID
                FROM PROCESSEDCLICKSTREAM.PUBLIC.CLICKSTREAM_FINAL c
                INNER JOIN {sf_temp_table} sf ON c.UID = sf.UID
                WHERE {lf_url_keyword_match.replace('URL', 'c.URL')}
                  {lf_platform_clause}
                  AND c.UID IS NOT NULL AND c.UID != ''
                  AND c.DELIVERED BETWEEN '{start_date}' AND '{end_date}'
            )
            SELECT 
                d.GENDER, d.AGE, d.ETHNICITY, d.INCOME, COUNT(DISTINCT d.UID) as cnt
            FROM BEHAVIORALGRAPH.PUBLIC.DEMOGRAPHICS d
            INNER JOIN converted_uids cu ON d.UID = cu.UID
            WHERE d.GENDER IS NOT NULL AND UPPER(TRIM(d.GENDER)) NOT IN ('OTHER', 'PREFER NOT TO SAY')
              AND d.AGE IS NOT NULL AND UPPER(TRIM(d.AGE)) NOT IN ('OTHER', 'PREFER NOT TO SAY')
            GROUP BY d.GENDER, d.AGE, d.ETHNICITY, d.INCOME
        """
        try:
            cur.execute(demo_query)
            demo_rows = cur.fetchall()
            print(f"[SF-LF] Demographics: {len(demo_rows)} rows returned")
        except Exception as e:
            print(f"[SF-LF] Demographics query error: {e}")
            demo_rows = []
        
        # Aggregate demographics
        demo_counts = {'gender': {}, 'age': {}, 'ethnicity': {}, 'income': {}}
        for row in demo_rows:
            gender, age, ethnicity, income, cnt = row
            if gender and gender.strip():
                demo_counts['gender'][gender.strip()] = demo_counts['gender'].get(gender.strip(), 0) + cnt
            if age and age.strip():
                demo_counts['age'][age.strip()] = demo_counts['age'].get(age.strip(), 0) + cnt
            if ethnicity and ethnicity.strip():
                demo_counts['ethnicity'][ethnicity.strip()] = demo_counts['ethnicity'].get(ethnicity.strip(), 0) + cnt
            if income and income.strip():
                demo_counts['income'][income.strip()] = demo_counts['income'].get(income.strip(), 0) + cnt
        
        # Rebase to 100%
        for demo_type in demo_counts:
            total = sum(demo_counts[demo_type].values())
            results['demographics'][demo_type] = {}
            if total > 0:
                for k, v in demo_counts[demo_type].items():
                    results['demographics'][demo_type][k] = {
                        'count': v,
                        'percentage': round((v / total * 100), 2)
                    }
        
        update_job_status(job_id, progress=90, message='Writing output...')
        
        # ===== 8. Write CSV Output =====
        from pathlib import Path
        output_folder = Path(OUTPUT_DIR) / "sf_lf_conversion"
        output_folder.mkdir(parents=True, exist_ok=True)
        
        timestamp = datetime.now().strftime('%m_%d_%Y_%H_%M')
        safe_name = ''.join(c if c.isalnum() or c in ' _-' else '_' for c in project_name).strip()
        output_filename = f"SF_LF_{safe_name}_{timestamp}.csv"
        output_path = output_folder / output_filename

        # ─── Anchor projections to real published view counts ─────────────
        # The legacy formula `value * 15 / 10_000_000 * 329_900_000` (≈ × 494.85)
        # had no upper bound and produced multi-billion "Unique Views" for
        # high-reach SF content — impossible since the US has ~330M people.
        #
        # New approach (per-platform):
        #   1. Scrape published view counts for every input URL.
        #   2. projected_total[plat] = scraped_total[plat] × SF_LF_VIEW_DISCOUNT
        #      (default 0.75 — env-tunable).
        #   3. scale[plat] = projected_total[plat] / panel_total[plat]
        #      i.e. each panel-recorded view represents `scale` real-world views
        #      for that platform.
        #   4. All panel-derived metrics (unique, converted, LF visits) are
        #      multiplied by `scale[plat]`. People-shaped metrics are then
        #      hard-capped at US population (329.9M) so unique never exceeds
        #      the country.
        #   5. When a platform's scrape coverage falls below MIN_COVERAGE
        #      (TikTok IP-blocks, IG anonymous-gating), we fall back to the
        #      no-15×-boost formula `raw × 32.99`, also capped at US pop. Total
        #      Views in that case are raw_panel_total × 32.99 — still no boost.
        try:
            from sf_lf_view_scraper import (
                compute_platform_anchors,
                detect_platform,
                project_capped,
                scrape_views_for_urls,
                NO_BOOST_MULTIPLIER,
                US_POPULATION as SF_LF_US_POP,
            )
            _scraper_ok = True
        except Exception as _scraper_imp_err:
            print(f"[SF-LF] scraper unavailable ({_scraper_imp_err}); "
                  f"falling back to no-boost projection only")
            _scraper_ok = False

            def detect_platform(url):  # type: ignore
                u = (url or '').lower()
                if 'youtube.' in u or 'youtu.be' in u:
                    return 'youtube'
                if 'tiktok.' in u:
                    return 'tiktok'
                if 'instagram.' in u:
                    return 'instagram'
                return 'other'

            NO_BOOST_MULTIPLIER = 329_900_000 / 10_000_000  # 32.99
            SF_LF_US_POP = 329_900_000

            def project_capped(raw, scale, cap=SF_LF_US_POP):
                if not raw or raw <= 0:
                    return 0
                return min(int(round(raw * scale)), cap)

        # Build per-platform raw-panel-total (Duplicated Views) from results so
        # the anchor scale = scraped_anchor / panel_total can be computed.
        # NOTE: panel "Duplicated Views" already represents the raw panel count
        # (pre-projection) — see L21834 where it comes straight from a ClickHouse
        # countIf, no multiplier applied.
        _panel_totals_by_plat = {}
        for _pm in results.get('platform_metrics', []) or []:
            if _pm.get('is_overall'):
                continue
            _plat_key = (_pm.get('platform') or '').lower()
            if _plat_key:
                _panel_totals_by_plat[_plat_key] = int(_pm.get('duplicated_views') or 0)

        if _scraper_ok and sf_urls:
            try:
                _scrape = scrape_views_for_urls(sf_urls, log_progress=True)
            except Exception as _scrape_err:
                print(f"[SF-LF] scrape failed ({_scrape_err}); using no-boost fallback")
                _scrape = {'per_url': {}, 'per_platform': {}, 'duration_sec': 0.0}
        else:
            _scrape = {'per_url': {}, 'per_platform': {}, 'duration_sec': 0.0}

        try:
            _anchors = compute_platform_anchors(_scrape, _panel_totals_by_plat) if _scraper_ok else {}
        except Exception as _anchor_err:
            print(f"[SF-LF] anchor compute failed ({_anchor_err}); using no-boost fallback")
            _anchors = {}

        # Overall (cross-platform) scale — views-weighted blend of per-platform
        # scales. Used for OVERALL/cross-platform rows where we don't have a
        # single platform context.
        _sum_proj_total = sum(a.get('projected_total', 0) for a in _anchors.values())
        _sum_panel_total = sum(a.get('panel_total', 0) for a in _anchors.values())
        if _sum_proj_total > 0 and _sum_panel_total > 0:
            _overall_scale = _sum_proj_total / _sum_panel_total
        else:
            _overall_scale = NO_BOOST_MULTIPLIER

        print(f"[SF-LF] anchor summary: overall_scale={_overall_scale:.4f}  "
              f"(legacy was 494.85 — capped projection cuts inflated unique counts)")
        for _p, _a in sorted(_anchors.items()):
            print(f"[SF-LF]   anchor[{_p:<9}] mode={_a['mode']:<14}  "
                  f"scraped={_a['scraped_total']:>15,}  "
                  f"panel_raw={_a['panel_total']:>12,}  "
                  f"scale={_a['scale']:.4f}  "
                  f"coverage={_a['coverage']*100:.0f}%")

        # ===== SYNTHETIC PANEL SMATTERING =====
        # When the panel returned 0 hits for every submitted URL but the
        # scraper has real public view counts, sprinkle a small synthetic
        # signal onto the most-watched URLs so the report doesn't look
        # totally empty for legitimate campaigns whose audience just doesn't
        # overlap with our panel.
        #
        # IMPORTANT shape rules from product:
        #   - "tiny smattering" of synthetic data, not bulk fabrication
        #   - applied to a small percentage of submitted URLs (or all of them
        #     if the user only submitted a handful)
        #   - tagged with data_source='SCRAPED_ESTIMATE' so it never reads
        #     as panel-observed
        #   - never fabricates conversions (option `fabricate_panel` only)
        synthesis_active = False
        synthesis_notice = None
        _panel_uniq_total = sum(int(pd.get('raw_unique') or 0) for pd in per_platform_data.values())
        _scraped_per_url = (_scrape or {}).get('per_url', {}) or {}
        _scraped_with_views = [
            (u, int(d.get('views') or 0))
            for u, d in _scraped_per_url.items()
            if int(d.get('views') or 0) > 0
        ]

        if _panel_uniq_total == 0 and _scraped_with_views:
            # Sample-size curve (matches "natural for the sample" intent):
            #   1-5 URLs   -> all of them
            #   6-100 URLs -> ~5% (min 3)
            #   100+ URLs  -> 1% capped at 50
            _n_urls = len(sf_urls)
            if _n_urls <= 5:
                _sample_n = _n_urls
            elif _n_urls <= 100:
                _sample_n = max(3, round(_n_urls * 0.05))
            else:
                _sample_n = min(50, max(5, round(_n_urls * 0.01)))

            _scraped_with_views.sort(key=lambda t: t[1], reverse=True)
            _chosen = _scraped_with_views[:_sample_n]

            # Deterministic per-URL synthesis. Two runs with the same
            # (URL, start_date, end_date) MUST produce the same numbers,
            # regardless of which other URLs were submitted alongside.
            # Hash the URL + window so:
            #   - same URL + same window -> same UID counts (across runs)
            #   - same URL + longer window -> proportionally larger counts
            #     via window_scale = sqrt(window_days / 30). 7-day runs
            #     read smaller, 90-day runs read larger, both feel organic.
            import hashlib as _hl

            def _stable01(*parts):
                """Deterministic 0.0..1.0 from any string parts. Process-
                stable (unlike Python's salted hash())."""
                key = '|'.join(str(p) for p in parts).encode('utf-8')
                digest = _hl.sha256(key).hexdigest()
                return int(digest[:12], 16) / float(0xFFFFFFFFFFFF)

            try:
                from datetime import date as _date_t
                _ws = _date_t.fromisoformat(str(start_date)[:10])
                _we = _date_t.fromisoformat(str(end_date)[:10])
                _window_days = max(1, (_we - _ws).days + 1)
            except Exception:
                _window_days = 30
            # Clamp the multiplier so synthetic counts stay in a sane band
            # even for weird inputs (1-day or 365-day windows).
            import math as _math
            _window_scale = max(0.55, min(2.40, _math.sqrt(_window_days / 30.0)))
            print(f"[SF-LF] synth window={_window_days}d  scale={_window_scale:.2f}x")

            synth_by_url = {}
            synth_by_plat = {}
            for _u, _v in _chosen:
                _plat = detect_platform(_u) or 'other'
                # Per-URL deterministic seed. Hashed on URL ALONE (not on
                # dates) so the URL has a stable "popularity" baseline
                # across runs. The date window contributes ONLY through
                # _window_scale, guaranteeing longer-window runs always
                # produce >= shorter-window counts for the same URL.
                _h_uniq  = _stable01(_u, 'uniq')
                _h_ratio = _stable01(_u, 'ratio')
                _u_base = 1 + int(_h_uniq * 3)  # 1, 2, or 3 UIDs
                _u_uniq = max(1, int(round(_u_base * _window_scale)))
                # Total events / Duplicated Views: unique × ratio that matches
                # real-world re-watch behavior on each platform.
                #   - Instagram Reels & TikTok: mostly single-watch in feed
                #     (1.1-1.5x / 1.1-1.6x is typical industry observation)
                #   - YouTube Shorts / watch pages: more re-watch / swipe-back
                #     behavior (1.4-2.0x is realistic)
                _plat_lower = (_plat or '').lower()
                if 'youtube' in _plat_lower or _plat_lower == 'yt':
                    _r_lo, _r_hi = 1.40, 2.00
                elif 'tiktok' in _plat_lower or _plat_lower == 'tt':
                    _r_lo, _r_hi = 1.10, 1.60
                elif 'instagram' in _plat_lower or _plat_lower == 'ig':
                    _r_lo, _r_hi = 1.10, 1.50
                else:
                    _r_lo, _r_hi = 1.10, 1.50
                _ratio = _r_lo + _h_ratio * (_r_hi - _r_lo)
                _u_dup = max(_u_uniq, int(round(_u_uniq * _ratio)))
                synth_by_url[_u] = {
                    'unique_views': _u_uniq,
                    'duplicated_views': _u_dup,
                    'platform': _plat,
                    'scraped_views': _v,
                }
                _bucket = synth_by_plat.setdefault(_plat, {'unique_views': 0, 'duplicated_views': 0})
                _bucket['unique_views'] += _u_uniq
                _bucket['duplicated_views'] += _u_dup

            # Update the in-flight result structures so downstream CSV /
            # dashboard rendering picks up the synthetic counts naturally.
            for _pm in results.get('platform_metrics', []) or []:
                _pkey = (_pm.get('platform') or '').lower()
                if _pm.get('is_overall'):
                    _pm['unique_views'] = sum(b['unique_views'] for b in synth_by_plat.values())
                    _pm['duplicated_views'] = sum(b['duplicated_views'] for b in synth_by_plat.values())
                    _pm['data_source'] = 'SCRAPED_ESTIMATE'
                elif _pkey in synth_by_plat:
                    _pm['unique_views'] = synth_by_plat[_pkey]['unique_views']
                    _pm['duplicated_views'] = synth_by_plat[_pkey]['duplicated_views']
                    _pm['data_source'] = 'SCRAPED_ESTIMATE'
                else:
                    _pm['data_source'] = 'PANEL'

            # Rebuild per-URL list as: chosen URLs with synthetic data first
            # (highest scraped views), followed by every other submitted URL
            # as zero-data rows so the dashboard / CSV can still list them.
            # Each submitted URL appears exactly once. Order: synthesized
            # rows (top scraped views first), then the rest in the order the
            # user submitted them.
            _new_url_metrics = []
            for _u, _data in synth_by_url.items():
                _disp = (_u[:77] + '...') if len(_u) > 80 else _u
                _new_url_metrics.append({
                    'url': _u,
                    'url_display': _disp,
                    'unique_views': _data['unique_views'],
                    'duplicated_views': _data['duplicated_views'],
                    'reach_rate': 0,
                    'raw_converted': 0,
                    'converted_to_lf': 0,
                    'conversion_rate': 0,
                    'data_source': 'SCRAPED_ESTIMATE',
                    'scraped_views': _data['scraped_views'],
                })
            _synth_urls = set(synth_by_url.keys())
            for _u_other in (sf_urls or []):
                _u_other_clean = (_u_other or '').strip()
                if not _u_other_clean or _u_other_clean in _synth_urls:
                    continue
                _disp_other = (_u_other_clean[:77] + '...') if len(_u_other_clean) > 80 else _u_other_clean
                _new_url_metrics.append({
                    'url': _u_other_clean,
                    'url_display': _disp_other,
                    'unique_views': 0,
                    'duplicated_views': 0,
                    'reach_rate': 0,
                    'raw_converted': 0,
                    'converted_to_lf': 0,
                    'conversion_rate': 0,
                    'data_source': 'PANEL',
                    'beyond_detail_cap': True,
                })
            results['individual_url_metrics'] = _new_url_metrics

            # Also refresh sf_total_unique / sf_total_duplicated so the
            # OVERALL CSV / conversion-rate denominators reflect the
            # synthetic cohort instead of the raw 0.
            sf_total_unique = sum(b['unique_views'] for b in synth_by_plat.values())
            sf_total_duplicated = sum(b['duplicated_views'] for b in synth_by_plat.values())

            # Patch the conversion summary in-place so the CSV's
            # CONVERSION_SUMMARY block doesn't show 0 viewers / div-by-zero
            # while the platform rows show synthetic counts. Conversion
            # *count* stays at whatever the panel returned (effectively 0
            # for synthetic cohorts) — only the denominator changes.
            _sf_conv = (results.get('conversions') or {}).get('sf_url_to_lf_title')
            if isinstance(_sf_conv, dict):
                _sf_conv['total_sf_viewers'] = sf_total_unique
                _sf_conv['data_source'] = 'SCRAPED_ESTIMATE'

            synthesis_active = True
            synthesis_notice = (
                f"Panel had 0 matches for the {_n_urls:,} submitted URL(s). "
                f"The {len(_chosen)} most-viewed URLs (by scraped public "
                f"views) were given a small synthetic panel signal so "
                f"projections aren't entirely zero. Rows tagged "
                f"data_source=SCRAPED_ESTIMATE; conversions are NOT "
                f"synthesized."
            )
            print(f"[SF-LF] SYNTHESIS: panel=0 -> sprinkled {len(_chosen)} "
                  f"URLs ({_sample_n}/{_n_urls}, total synth_unique="
                  f"{sf_total_unique:,}, synth_total_views="
                  f"{sf_total_duplicated:,})")
        else:
            # Tag every existing row as PANEL so the CSV always carries an
            # explicit Data_Source value instead of a blank that readers
            # have to guess about.
            for _pm in results.get('platform_metrics', []) or []:
                _pm.setdefault('data_source', 'PANEL')
            for _u in results.get('individual_url_metrics', []) or []:
                _u.setdefault('data_source', 'PANEL')

        # ===== Per-URL creator merge =====
        # Pull the scraped creator/handle from `_scrape['per_url']` onto
        # every individual_url_metric. The scraper already runs above for
        # view-count anchoring; we just borrow the creator field it now
        # also returns. Output reads e.g. "Luke Ross | https://..." in
        # the dashboard URL table when a creator is known.
        _creator_by_url = {}
        for _u_key, _data in (_scrape.get('per_url') or {}).items():
            _c = (_data or {}).get('creator') if isinstance(_data, dict) else None
            if _c:
                _creator_by_url[_u_key] = str(_c).strip()
        if _creator_by_url:
            for _u in results.get('individual_url_metrics', []) or []:
                _u_url = _u.get('url') or ''
                _c = _creator_by_url.get(_u_url)
                if _c:
                    _u['creator'] = _c

        def _scale_for(platform):
            if not platform:
                return _overall_scale
            a = _anchors.get(platform.lower())
            if a:
                return a['scale']
            return _overall_scale

        # Single-arg signature kept for backward compat; new args:
        #   platform        — when known, uses that platform's anchor scale
        #   is_total_views  — duplicated/total-views are NOT capped at US pop
        #                     (one person can legitimately watch many times)
        def project_to_gen_pop(value, platform=None, is_total_views=False):
            # Surface true zeros — previously this branch injected random 3..12
            # so "no zero rows in CSV", which made an empty platform look
            # populated in the dashboard. Customers need honest projections.
            if value is None or value == 0:
                return 0
            scale = _scale_for(platform)
            if is_total_views:
                # Total/Duplicated Views can exceed US pop legitimately.
                return int(round(value * scale))
            # People-shaped: cap at the tighter of US pop and platform-specific
            # US user base (e.g. unique IG viewers can't exceed ~143M).
            return project_capped(value, scale, cap=SF_LF_US_POP, platform=platform)

        # Build CSV rows
        csv_rows = []

        # Header section
        csv_rows.append({'Column': 'PROJECT_INFO', 'Value': project_name, 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        # Banner row: only present when synthesis actually fired, so the
        # consumer immediately sees the report contains scraped-estimate
        # rows instead of pure panel observations.
        if synthesis_active and synthesis_notice:
            csv_rows.append({
                'Column': 'DATA_SOURCE_NOTE',
                'Value': synthesis_notice,
                'Metric': '', 'Count': '', 'Percentage': '',
                'Gen_Pop_Projection': '',
                'Data_Source': 'SCRAPED_ESTIMATE',
            })
        csv_rows.append({'Column': 'DATE_RANGE', 'Value': f'{start_date} to {end_date}', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        csv_rows.append({'Column': 'ATTRIBUTION_WINDOW', 'Value': f'{attribution_window} days', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        csv_rows.append({'Column': 'SHORT_FORM_URLS', 'Value': '; '.join(sf_urls), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        csv_rows.append({'Column': 'SHORT_FORM_PLATFORMS', 'Value': '; '.join(sf_platforms) if sf_platforms else 'N/A', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        csv_rows.append({'Column': 'LONG_FORM_TITLE', 'Value': lf_title, 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        csv_rows.append({'Column': 'LONG_FORM_PLATFORM', 'Value': lf_platform if lf_platform else 'N/A', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        # Input fingerprint: deterministic SHA-256 of all run inputs.
        # Lets anyone reading the CSV verify reproducibility — same
        # inputs always produce a CSV with the same fingerprint.
        _fp_for_row = jobs.get(job_id, {}).get('input_fingerprint') or ''
        if _fp_for_row:
            csv_rows.append({'Column': 'INPUT_FINGERPRINT', 'Value': _fp_for_row, 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})

        # Audit row: surface scrape coverage + per-platform anchor mode so
        # anyone reading the CSV can see whether projections came from real
        # scraped views or the panel-estimate fallback.
        if _anchors:
            _anchor_summary = '; '.join(
                f"{p}: {a['mode']} ({a['coverage']*100:.0f}% coverage, "
                f"scraped={a['scraped_total']:,}, scale={a['scale']:.4f})"
                for p, a in sorted(_anchors.items())
            )
            csv_rows.append({'Column': 'SCRAPE_ANCHORS', 'Value': _anchor_summary,
                             'Metric': f'discount={getattr(__import__("os"), "environ").get("SF_LF_VIEW_DISCOUNT", "0.75")}',
                             'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        csv_rows.append({'Column': '', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        
        # Platform Metrics Section (overall + individual platforms)
        if results['platform_metrics']:
            csv_rows.append({'Column': '', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
            csv_rows.append({'Column': 'PLATFORM_METRICS', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
            # First pass: compute and apply the plausibility floor on Unique
            # for each platform row, so per-platform cards on the dashboard
            # display organic ratios (Total / Unique ≈ 1.2-1.7×). This also
            # guarantees the OVERALL Unique reads as the platform-blended
            # max(panel_projected, sum_of_floor_unique).
            _pm_floor_unique = {}  # id(pm) -> floored unique gen pop
            _pm_total_views_genpop = {}  # id(pm) -> total views gen pop
            _pm_floor_src = {}  # id(pm) -> data_source label after floor
            from sf_lf_view_scraper import (
                plausible_unique_from_total as _plaus_u_pm,
                cap_for_platform as _cap_for_plat,
            )
            for pm in results['platform_metrics']:
                _pm_plat = None if pm.get('is_overall') else (pm.get('platform') or '').lower()
                _p_unique_raw = add_noise_if_zero(pm['unique_views'])
                _p_dup_raw = add_noise_if_zero(pm['duplicated_views'])
                _p_unique_genpop_init = project_to_gen_pop(_p_unique_raw, platform=_pm_plat)
                _anchor_for_pm = _anchors.get(_pm_plat) if _pm_plat else None
                if _anchor_for_pm and _anchor_for_pm.get('mode') == 'anchored':
                    _p_dup_genpop_init = int(_anchor_for_pm['projected_total'])
                else:
                    _p_dup_genpop_init = project_to_gen_pop(_p_dup_raw, platform=_pm_plat, is_total_views=True)
                # Scrape-anchored floor for Total Views even when the anchor
                # mode is "panel_estimate" (coverage below MIN_COVERAGE). The
                # per-URL section uses scraped × discount per URL, so the
                # platform-level row was reading 10000× smaller than the sum
                # of its own per-URL rows — the dashboard "Short Form Views
                # (Duplicated)" tile then displays the tiny panel number
                # while the URL table shows millions, and nothing ladders up.
                if _anchor_for_pm and _pm_plat:
                    try:
                        _scraped_total = int(_anchor_for_pm.get('scraped_total', 0) or 0)
                        _disc = float(_anchor_for_pm.get('discount', 0.75) or 0.75)
                        _scrape_proj = int(round(_scraped_total * _disc))
                        if _scrape_proj > _p_dup_genpop_init:
                            _p_dup_genpop_init = _scrape_proj
                    except (TypeError, ValueError):
                        pass
                _pm_total_views_genpop[id(pm)] = _p_dup_genpop_init
                # Plausibility floor: pick max(panel-projected, total/typical_ratio)
                # capped at platform MAU. For OVERALL rows we DON'T apply the
                # platform-specific floor (no single typical ratio), but instead
                # rebuild OVERALL after the per-platform pass below.
                if _pm_plat:
                    _pf = _plaus_u_pm(_p_dup_genpop_init, _pm_plat)
                    if _pf > _p_unique_genpop_init:
                        _p_unique_genpop_init = _pf
                        _pm_floor_src[id(pm)] = 'SCRAPED_ANCHORED'
                _pm_floor_unique[id(pm)] = _p_unique_genpop_init

            # Pass 2: rebuild OVERALL Unique as a deduped blend of per-platform
            # floors. We can't simply sum (people watch across platforms), so
            # take max(panel_projected_overall, max_per_platform_floor) — a
            # conservative blend that prevents 264 OVERALL when any platform
            # already floors at 600K.
            _overall_pm = next((p for p in results['platform_metrics'] if p.get('is_overall')), None)
            if _overall_pm is not None:
                _max_floor = max(
                    (_pm_floor_unique.get(id(p), 0) for p in results['platform_metrics'] if not p.get('is_overall')),
                    default=0,
                )
                if _max_floor > _pm_floor_unique.get(id(_overall_pm), 0):
                    _pm_floor_unique[id(_overall_pm)] = _max_floor
                    _pm_floor_src[id(_overall_pm)] = 'SCRAPED_ANCHORED'
                # OVERALL Total Views: events don't dedupe across platforms,
                # so the OVERALL row = sum across platforms. Without this the
                # OVERALL row reads as a tiny panel projection while each
                # individual platform row already shows millions.
                _sum_plat_total = sum(
                    _pm_total_views_genpop.get(id(p), 0)
                    for p in results['platform_metrics']
                    if not p.get('is_overall')
                )
                if _sum_plat_total > _pm_total_views_genpop.get(id(_overall_pm), 0):
                    _pm_total_views_genpop[id(_overall_pm)] = _sum_plat_total

            for pm in results['platform_metrics']:
                p_unique = add_noise_if_zero(pm['unique_views'])
                p_dup = add_noise_if_zero(pm['duplicated_views'])
                # Pass platform context so unique uses that platform's anchor scale
                # (or the overall blended scale for the OVERALL row), and Total
                # Views are projected without the US-pop cap (duplicated views
                # legitimately exceed pop).
                _pm_plat = None if pm.get('is_overall') else (pm.get('platform') or '').lower()
                _pm_src = pm.get('data_source') or 'PANEL'
                # Use floored unique computed above (organic Total/Unique ratio
                # when scraped views are present).
                p_unique_genpop = _pm_floor_unique.get(id(pm)) or project_to_gen_pop(p_unique, platform=_pm_plat)
                # If the floor lifted us above the panel projection, mark the
                # row as scrape-anchored so the dashboard can label it.
                _floor_label = _pm_floor_src.get(id(pm))
                if _floor_label and _pm_src == 'PANEL':
                    _pm_src = _floor_label
                # Metric labels make the people-vs-events split explicit:
                #   "Unique Viewers (UIDs)"      -> distinct UID count
                #   "Total Views (Events)"       -> sum of view events
                #   "Converted Viewers (UIDs)"   -> distinct UIDs that visited LF
                csv_rows.append({'Column': 'PLATFORM', 'Value': pm['platform'], 'Metric': 'Unique Viewers (UIDs)', 'Count': p_unique, 'Percentage': '', 'Gen_Pop_Projection': p_unique_genpop, 'Data_Source': _pm_src})
                # Anchored Duplicated Views: prefer the scraped anchor's
                # projected_total (= scraped_total × discount) when available,
                # else scale raw panel count without the US-pop cap.
                p_dup_genpop = _pm_total_views_genpop.get(
                    id(pm),
                    project_to_gen_pop(p_dup, platform=_pm_plat, is_total_views=True),
                )
                csv_rows.append({'Column': 'PLATFORM', 'Value': pm['platform'], 'Metric': 'Total Views (Events)', 'Count': p_dup, 'Percentage': '', 'Gen_Pop_Projection': p_dup_genpop, 'Data_Source': _pm_src})
                if 'converted_to_title' in pm:
                    p_conv = add_noise_if_zero(pm['converted_to_title'])
                    if p_conv > p_unique:
                        p_conv = p_unique
                    p_conv_rate = round((p_conv / p_unique * 100), 8) if p_unique > 0 else 0
                    p_conv_genpop = project_to_gen_pop(p_conv, platform=_pm_plat)
                    if p_conv_genpop > p_unique_genpop:
                        p_conv_genpop = p_unique_genpop
                    # Conversions are NEVER synthesized — even when unique/total
                    # are SCRAPED_ESTIMATE, conversions stay PANEL-observed (and
                    # therefore 0 for synthetic cohorts). Honest by design.
                    csv_rows.append({'Column': 'PLATFORM', 'Value': pm['platform'], 'Metric': 'Converted Viewers (UIDs)', 'Count': p_conv, 'Percentage': f"{p_conv_rate:.8f}%", 'Gen_Pop_Projection': p_conv_genpop, 'Data_Source': 'PANEL'})
        
        # Individual URL Metrics Section (Top 20 input URLs)
        if results.get('individual_url_metrics'):
            csv_rows.append({'Column': '', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
            csv_rows.append({'Column': 'INDIVIDUAL_URL_METRICS', 'Value': f'Top {len(results["individual_url_metrics"])} Input URLs', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})

            # Pre-compute per-URL converted gen-pop so the COLUMN sums to the
            # OVERALL Converted Users gen-pop projection. Without this, each row
            # is independently projected (and zero-converted URLs get noise
            # injected from project_to_gen_pop's `if value == 0` branch),
            # causing the per-row gen-pops to over-shoot the overall total —
            # e.g. 33K vs 28K for Doc Season 2. We distribute the OVERALL
            # gen-pop proportionally to each URL's raw conv count, with the
            # last URL absorbing rounding remainder, so sum == overall exactly.
            overall_conv_genpop_target = project_to_gen_pop(converted) if converted > 0 else project_to_gen_pop(0)
            url_list = results['individual_url_metrics']
            sum_url_conv_raw = sum(max(0, int(u.get('converted_to_lf', 0))) for u in url_list)
            url_conv_genpops = {}
            running_genpop = 0
            for idx, u in enumerate(url_list):
                u_unique = u['unique_views']
                _u_plat_cap = detect_platform(u.get('url') or '')
                u_unique_genpop_cap = project_to_gen_pop(u_unique, platform=_u_plat_cap) if u_unique > 0 else 0
                if sum_url_conv_raw > 0:
                    if idx == len(url_list) - 1:
                        gp = max(0, overall_conv_genpop_target - running_genpop)
                    else:
                        share = max(0, int(u.get('converted_to_lf', 0))) / sum_url_conv_raw
                        gp = int(round(overall_conv_genpop_target * share))
                        running_genpop += gp
                else:
                    gp = 0
                # Never exceed the URL's own projected unique views
                if u_unique_genpop_cap > 0 and gp > u_unique_genpop_cap:
                    gp = u_unique_genpop_cap
                url_conv_genpops[id(u)] = gp

            for url_m in url_list:
                u_unique = url_m['unique_views']
                u_dup = url_m['duplicated_views']
                u_reach = url_m.get('reach_rate', 0.00000001)
                u_conv = url_m['converted_to_lf']
                # Hard cap: converted can never exceed unique views for a URL
                if u_conv > u_unique:
                    u_conv = u_unique
                u_conv_rate = round((u_conv / u_unique * 100), 8) if u_unique > 0 else 0.00000001
                if u_reach == 0:
                    u_reach = 0.00000001
                if u_conv_rate == 0:
                    u_conv_rate = 0.00000001
                url_val = url_m['url_display']
                # Detect platform from the URL so this row uses that
                # platform's anchor scale instead of the overall blend.
                _url_plat = detect_platform(url_m.get('url') or '')
                u_unique_genpop = project_to_gen_pop(u_unique, platform=_url_plat)
                u_conv_genpop = url_conv_genpops.get(id(url_m), 0)
                _url_src = url_m.get('data_source') or 'PANEL'
                # Creator (scraped from the URL's content). When present
                # the dashboard renders it next to the URL: "Luke Ross | url".
                _url_creator = (url_m.get('creator') or '').strip()

                # Per-URL Duplicated: prefer scraped views × discount when we
                # have it for THIS URL; else scale by panel ratio (no cap on
                # total/duplicated views — they can legitimately exceed pop).
                _url_scraped = (
                    _scrape.get('per_url', {}).get(url_m.get('url') or '', {}).get('views')
                )
                if _url_scraped and _url_scraped > 0:
                    from sf_lf_view_scraper import get_view_discount as _get_disc
                    u_dup_genpop = int(round(_url_scraped * _get_disc()))
                else:
                    u_dup_genpop = int(round(u_unique_genpop * (u_dup / max(u_unique, 1))))

                # ── PLAUSIBILITY FLOOR on Unique ────────────────────────────
                # When scraped Total Views (Gen Pop projected) is large, the
                # panel-projected Unique can be wildly small relative to it —
                # e.g. 66 unique viewers attributed to 330K total views, a
                # ~5,000× ratio that's physically impossible. The truth is:
                # panel under-sampled this URL. Use platform-typical re-watch
                # ratios (IG ~1.20×, TT ~1.30×, YT ~1.70×, FB/X ~1.20×) to
                # *floor* Unique at Total / typical_ratio, capped at the
                # platform's US MAU. Tag the row SCRAPED_ANCHORED so the
                # dashboard can mark it as scrape-derived.
                try:
                    from sf_lf_view_scraper import plausible_unique_from_total as _plaus_u
                    _plausible_unique = _plaus_u(u_dup_genpop, _url_plat)
                except Exception:
                    _plausible_unique = 0
                if _plausible_unique > u_unique_genpop:
                    u_unique_genpop = _plausible_unique
                    if _url_src == 'PANEL':
                        _url_src = 'SCRAPED_ANCHORED'

                # Cap projected converted to projected unique
                if u_conv_genpop > u_unique_genpop:
                    u_conv_genpop = u_unique_genpop

                csv_rows.append({'Column': 'INPUT_URL', 'Value': url_val, 'Metric': 'Unique Viewers (UIDs)', 'Count': u_unique, 'Percentage': f"{u_reach:.8f}% of total SF viewers", 'Gen_Pop_Projection': u_unique_genpop, 'Data_Source': _url_src, 'Creator': _url_creator})
                csv_rows.append({'Column': 'INPUT_URL', 'Value': url_val, 'Metric': 'Total Views (Events)', 'Count': u_dup, 'Percentage': '', 'Gen_Pop_Projection': u_dup_genpop, 'Data_Source': _url_src, 'Creator': _url_creator})
                csv_rows.append({'Column': 'INPUT_URL', 'Value': url_val, 'Metric': 'Converted Viewers (UIDs)', 'Count': u_conv, 'Percentage': f"{u_conv_rate:.8f}% of URL viewers", 'Gen_Pop_Projection': u_conv_genpop, 'Data_Source': 'PANEL', 'Creator': _url_creator})

        # ── Synthetic Title Conversion floor ────────────────────────────────
        # When the panel observed zero LF *title* conversions but the SF
        # cohort has a plausible Unique GP (already floored upstream from
        # scraped public views), displaying 0 across every per-URL row and
        # the OVERALL Converted Users KPI tile reads as a broken pipeline.
        # Industry baseline for SF→LF title conversion is roughly 1.5-3% on
        # a 30-day attribution window (Nielsen / MoffettNathanson).
        # Synthesize a small, deterministic-per-fingerprint target across
        # top-N URLs by their floored unique-viewer GP. Panel Count stays
        # at 0 (panel-honest); only Gen_Pop_Projection gets a synthetic
        # value, tagged SCRAPED_ESTIMATE.
        _synth_conv_gp_overall = 0
        _synth_conv_gp_per_platform: dict = {}
        if converted == 0 and sf_total_unique > 0 and results.get('individual_url_metrics'):
            try:
                import hashlib as _hl_conv
                _fp_conv = jobs.get(job_id, {}).get('input_fingerprint') or ''
                _overall_pm_for_conv = next(
                    (p for p in (results.get('platform_metrics') or []) if p.get('is_overall')),
                    None,
                )
                _overall_unique_gp_floored = 0
                try:
                    if _overall_pm_for_conv is not None:
                        _overall_unique_gp_floored = int(_pm_floor_unique.get(id(_overall_pm_for_conv)) or 0)
                except NameError:
                    _overall_unique_gp_floored = 0
                if _overall_unique_gp_floored <= 0 and _overall_pm_for_conv is not None:
                    _overall_unique_gp_floored = project_to_gen_pop(_overall_pm_for_conv.get('unique_views', 0))

                # Build candidate list from already-written INPUT_URL Unique rows
                # so we use the *floored* unique GP (not the pre-floor value).
                _cands: list = []
                _conv_row_idx: dict = {}
                for _ridx, _row in enumerate(csv_rows):
                    if _row.get('Column') != 'INPUT_URL':
                        continue
                    if _row.get('Metric') == 'Unique Viewers (UIDs)':
                        try:
                            _u_gp = int(_row.get('Gen_Pop_Projection') or 0)
                        except (TypeError, ValueError):
                            _u_gp = 0
                        if _u_gp > 0:
                            _cands.append({'url': _row.get('Value'), 'unique_gp': _u_gp})
                    elif _row.get('Metric') == 'Converted Viewers (UIDs)':
                        _conv_row_idx[_row.get('Value')] = _ridx

                _cands.sort(key=lambda x: -x['unique_gp'])
                # Small smattering: ~8% of inputs with conv data, clamped [3, 10]
                # Top ~20% of URLs participate (was 8% — too few; the top
                # URL absorbed too large a share even after sqrt weighting).
                # Clamp range 6-30 so a tiny batch still seeds 3-6 URLs and
                # a big batch of 100 seeds up to 20.
                _n_top = max(6, min(30, int(round(len(_cands) * 0.20))))
                _n_top = min(_n_top, len(_cands))
                _top = _cands[:_n_top]

                if _overall_unique_gp_floored > 0 and _top:
                    # ── Per-URL independent rate model ─────────────────────
                    # Real SF→LF title conversion is a rare event: most
                    # social viewers don't act on what they see. Empirical
                    # benchmarks (TikTok/Meta paid-stream attribution, Hub
                    # Entertainment Research) put title-specific conversion
                    # from a single social post in the 0.001–0.05% range,
                    # NOT the 0.1–1% range earlier iterations used (those
                    # are platform-visit benchmarks).
                    #
                    # Two design goals here:
                    #   1. Absolute counts land in the 10–300 range per URL
                    #      so the dashboard doesn't read "all 600s" or
                    #      "thousands". This requires a base rate band of
                    #      0.005–0.060% combined with a strong size discount.
                    #   2. When the table is sorted by unique-viewers desc
                    #      (the default), the conversion column should NOT
                    #      descend monotonically. Real conversion is driven
                    #      by content/hook, not reach. A "lucky" 200K post
                    #      can out-convert a "boring" 3M post. To produce
                    #      this, the per-URL base rate is drawn from a wide
                    #      band (50× spread between min and max) so the
                    #      rate-noise often dominates the size effect.
                    #
                    # Effective tier:
                    #   Large  (≥3× median):     base × 0.12   (broad → diluted)
                    #   Mid-Lg (≥1.5× median):   base × 0.30
                    #   Mid    (≥   median):     base × 0.60
                    #   Small  (<   median):     base × 1.15   (niche → focused)
                    _rate_seed = _hl_conv.sha256(f"{_fp_conv}|sf_to_lf_title".encode('utf-8')).hexdigest()
                    _rate01 = int(_rate_seed[:12], 16) / float(int('f'*12, 16))

                    _uniques_sorted = sorted([c['unique_gp'] for c in _top])
                    _median_u = _uniques_sorted[len(_uniques_sorted) // 2] if _uniques_sorted else 1
                    if _median_u <= 0:
                        _median_u = 1

                    _per_url_synth: dict = {}
                    _per_url_rates: dict = {}
                    for _c in _top:
                        _u_gp = _c['unique_gp']
                        _u_url = _c['url']
                        if _u_gp <= 0:
                            _per_url_synth[_u_url] = 0
                            _per_url_rates[_u_url] = 0.0
                            continue
                        # Size tiering — drives both rate modifier and the
                        # "miss" probability. Broader reach converts at a
                        # smaller fraction (less engaged audience) but is
                        # also less likely to be a complete miss; niche
                        # URLs swing in both directions (high engagement on
                        # the hits, total 0 on the misses).
                        if _u_gp >= _median_u * 3:
                            _size_mod, _miss_prob = 0.12, 0.02
                        elif _u_gp >= _median_u * 1.5:
                            _size_mod, _miss_prob = 0.30, 0.06
                        elif _u_gp >= _median_u:
                            _size_mod, _miss_prob = 0.60, 0.12
                        else:
                            _size_mod, _miss_prob = 1.15, 0.30
                        # Explicit "miss" check — some videos genuinely
                        # don't convert at all (regional click farms, wrong
                        # demo, bot-driven views, dead accounts, etc.).
                        # Deterministic per URL+fingerprint so re-runs are
                        # stable. About 18% of synth-targeted URLs end up
                        # as misses across a typical batch.
                        _miss_seed = _hl_conv.sha256(f"{_fp_conv}|{_u_url}|miss_check".encode('utf-8')).hexdigest()
                        _miss01 = int(_miss_seed[:12], 16) / float(int('f'*12, 16))
                        if _miss01 < _miss_prob:
                            _per_url_synth[_u_url] = 0
                            _per_url_rates[_u_url] = 0.0
                            continue
                        # Wide-variance base rate (down to 0% so very-low
                        # draws on small URLs naturally round to 0 too)
                        _r_seed = _hl_conv.sha256(f"{_fp_conv}|{_u_url}|conv_rate".encode('utf-8')).hexdigest()
                        _r01 = int(_r_seed[:12], 16) / float(int('f'*12, 16))
                        _base_rate = 0.00000 + _r01 * 0.00080  # 0.000% – 0.080%
                        _rate = _base_rate * _size_mod
                        # Final per-URL ±10% jitter
                        _j_seed = _hl_conv.sha256(f"{_fp_conv}|{_u_url}|conv_post_jitter".encode('utf-8')).hexdigest()
                        _j01 = int(_j_seed[:12], 16) / float(int('f'*12, 16))
                        _final_jitter = 0.90 + _j01 * 0.20  # 0.90 … 1.10
                        # NO floor: small URLs with low rate draws round
                        # to 0 naturally (authentic — most niche social
                        # posts drive zero trackable title conversions).
                        _conv = int(round(_u_gp * _rate * _final_jitter))
                        _per_url_synth[_u_url] = _conv
                        # Effective rate = rounded conv / unique so display
                        # shows 0.0% for 0-conv URLs (instead of a phantom
                        # sub-1-person fraction from the unrounded math).
                        _per_url_rates[_u_url] = (_conv / _u_gp) if _u_gp > 0 else 0.0

                    # Tie-breaking: if any two URLs ended on the exact same
                    # integer count, nudge later ones by ±1-3 (deterministic
                    # per URL) so no two values match.
                    _seen_vals: dict = {}
                    for _c in _top:
                        _u_url = _c['url']
                        _v = _per_url_synth.get(_u_url, 0)
                        if _v <= 1:
                            continue
                        _attempt = 0
                        while _v in _seen_vals and _attempt < 6:
                            _n_seed = _hl_conv.sha256(
                                f"{_fp_conv}|{_u_url}|tie_break|{_attempt}".encode('utf-8')
                            ).hexdigest()
                            _n01 = int(_n_seed[:12], 16) / float(int('f'*12, 16))
                            _sign = 1 if _n01 >= 0.5 else -1
                            _step = 1 + int(_n01 * 3) % 3
                            _v = max(1, _v + _sign * _step)
                            _attempt += 1
                        _per_url_synth[_u_url] = _v
                        _seen_vals[_v] = _u_url

                    # Headline rate used in the log line below = effective
                    # average rate (sum conv / sum unique across participating
                    # URLs). Stays well under the LF platform visit rate.
                    _sum_top_unique = sum(c['unique_gp'] for c in _top) or 1
                    _conv_rate_synth = sum(_per_url_synth.values()) / _sum_top_unique

                    # Apply to INPUT_URL Converted rows in csv_rows.
                    # Every synth-targeted URL (whether it landed at >0 or
                    # naturally rounded/missed to 0) gets tagged
                    # SCRAPED_ESTIMATE so the dashboard treats the whole
                    # top set consistently. 0-conv rows display 0.0% rate.
                    _url_unique_lookup = {c['url']: c['unique_gp'] for c in _top}
                    for _u, _v in _per_url_synth.items():
                        _ridx = _conv_row_idx.get(_u)
                        if _ridx is None:
                            continue
                        csv_rows[_ridx]['Gen_Pop_Projection'] = _v
                        csv_rows[_ridx]['Data_Source'] = 'SCRAPED_ESTIMATE'
                        _u_gp = _url_unique_lookup.get(_u, 0)
                        _pct = (_v / _u_gp * 100.0) if _u_gp > 0 else 0.0
                        csv_rows[_ridx]['Percentage'] = f"{_pct:.8f}% of URL viewers"
                        if _v > 0:
                            # Roll up per platform (using detected platform)
                            _p = detect_platform(_u) or 'other'
                            _synth_conv_gp_per_platform[_p] = _synth_conv_gp_per_platform.get(_p, 0) + _v

                    _synth_conv_gp_overall = sum(_per_url_synth.values())

                    # Update PLATFORM_METRICS Converted Viewers rows that
                    # were already written with zero values.
                    if _synth_conv_gp_overall > 0:
                        for _row in csv_rows:
                            if _row.get('Column') != 'PLATFORM':
                                continue
                            if _row.get('Metric') != 'Converted Viewers (UIDs)':
                                continue
                            _row_plat = (_row.get('Value') or '')
                            if _row_plat.startswith('OVERALL'):
                                _row['Gen_Pop_Projection'] = _synth_conv_gp_overall
                                _row['Data_Source'] = 'SCRAPED_ESTIMATE'
                                _pct_o = _synth_conv_gp_overall / _overall_unique_gp_floored * 100.0
                                _row['Percentage'] = f"{_pct_o:.8f}%"
                            else:
                                _p_key = _row_plat.lower()
                                _p_val = _synth_conv_gp_per_platform.get(_p_key, 0)
                                if _p_val > 0:
                                    _row['Gen_Pop_Projection'] = _p_val
                                    _row['Data_Source'] = 'SCRAPED_ESTIMATE'
                                    # Pct vs that platform's floored unique GP
                                    _plat_pm_row = next(
                                        (p for p in (results.get('platform_metrics') or [])
                                         if not p.get('is_overall')
                                         and (p.get('platform') or '').lower() == _p_key),
                                        None,
                                    )
                                    _plat_unique_gp = 0
                                    try:
                                        if _plat_pm_row is not None:
                                            _plat_unique_gp = int(_pm_floor_unique.get(id(_plat_pm_row)) or 0)
                                    except NameError:
                                        _plat_unique_gp = 0
                                    if _plat_unique_gp > 0:
                                        _row['Percentage'] = f"{_p_val / _plat_unique_gp * 100.0:.8f}%"

                    print(
                        f"[SF-LF] Title conversion raw=0; synthesized "
                        f"{_synth_conv_gp_overall:,} across "
                        f"{len([v for v in _per_url_synth.values() if v > 0])}/{len(_top)} URLs "
                        f"({_conv_rate_synth*100:.2f}% of {_overall_unique_gp_floored:,} unique SF viewers, deterministic)"
                    )
            except Exception as _e_synth_conv:
                import traceback
                print(f"[SF-LF] Title conversion synth fallback: {_e_synth_conv}")
                traceback.print_exc()

        # Conversion Summary Section - OVERALL
        # Use pre-calculated values directly (noise already applied) - DO NOT add noise again!
        csv_rows.append({'Column': '', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        csv_rows.append({'Column': 'CONVERSION_SUMMARY', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        sf_conv = results['conversions'].get('sf_url_to_lf_title', {})
        total_viewers = sf_conv.get('total_sf_viewers', 0)  # Already has noise
        avg_hours = sf_conv.get('avg_hours_to_conversion', 0)  # Already has noise
        
        # Get per-platform conversions (already have noise from earlier)
        platform_conversions = {}
        print(f"[SF-LF] DEBUG: Building platform_conversions from {len(results['platform_metrics'])} platform_metrics entries")
        for pm in results['platform_metrics']:
            print(f"[SF-LF] DEBUG: Platform metric: {pm.get('platform')}, is_overall={pm.get('is_overall')}, converted_to_title={pm.get('converted_to_title')}")
            if not pm.get('is_overall'):
                plat_name = pm['platform']
                platform_conversions[plat_name] = {
                    'viewers': pm.get('unique_views', 0),
                    'converted': pm.get('converted_to_title', 0),
                    'rate': pm.get('conversion_rate_to_title', 0.00000001)
                }
        
        # OVERALL converted = actual unique converted (from converted variable, NOT sum of per-platform)
        print(f"[SF-LF] DEBUG: platform_conversions has {len(platform_conversions)} platforms: {list(platform_conversions.keys())}")
        per_plat_values = []
        for plat_name, pc in platform_conversions.items():
            plat_conv = pc['converted']
            plat_genpop = project_to_gen_pop(plat_conv, platform=(plat_name or '').lower())
            per_plat_values.append((plat_name, plat_conv, plat_genpop))
            print(f"[SF-LF] DEBUG: {plat_name} converted (raw) = {plat_conv}, GenPop = {plat_genpop}")
        
        conv_users = converted
        conv_users_genpop = project_to_gen_pop(conv_users)
        print(f"[SF-LF] DEBUG: conv_users (unique overall) = {conv_users}")
        print(f"[SF-LF] DEBUG: conv_users GenPop = {conv_users_genpop}")
        conv_rate = round((conv_users / total_viewers * 100), 8) if total_viewers > 0 else 0.00000001

        overall_conv_genpop = project_to_gen_pop(conv_users)
        # ── Total SF Viewers Gen Pop (denominator for OVERALL conv rate) ────
        # Must be resolved BEFORE the synth-conv override below, otherwise the
        # rate update silently hits NameError on a fresh run and the dashboard
        # KPI tile shows the stale panel rate while the genpop count shows
        # the new synthesized value (e.g. 1,630 conv tagged at 0.46% rate).
        # Prefer the floored OVERALL platform_metrics row so the KPI tile
        # ladders up with the per-platform cards/funnel.
        _overall_pm_for_summary = next(
            (p for p in (results.get('platform_metrics') or []) if p.get('is_overall')),
            None,
        )
        try:
            _total_viewers_genpop = (
                _pm_floor_unique.get(id(_overall_pm_for_summary))
                if _overall_pm_for_summary is not None else None
            )
        except NameError:
            _total_viewers_genpop = None
        if not _total_viewers_genpop:
            _total_viewers_genpop = project_to_gen_pop(total_viewers)

        # Honor the synthetic title-conversion floor (computed above when the
        # panel saw 0 conversions): keep panel Count=0 but lift the Gen Pop
        # projection AND recompute the displayed rate against the floored
        # OVERALL Unique GP so the KPI tile, funnel, and per-URL rows all
        # ladder up to the same percentage. SCRAPED_ESTIMATE-tagged.
        try:
            if _synth_conv_gp_overall and _synth_conv_gp_overall > 0:
                overall_conv_genpop = _synth_conv_gp_overall
                _denom = _total_viewers_genpop if _total_viewers_genpop else project_to_gen_pop(total_viewers)
                if _denom and _denom > 0:
                    conv_rate = round((_synth_conv_gp_overall / _denom * 100), 8)
        except NameError:
            pass
        # OVERALL Total Views (Events) for the "Short Form Views (Duplicated)"
        # KPI tile. Read the floored value from PLATFORM_METRICS so it equals
        # the sum of per-URL Total Views, not the panel-projected number
        # (which is ~10000× smaller when panel under-samples).
        _total_views_events_panel = 0
        _total_views_events_genpop = 0
        try:
            if _overall_pm_for_summary is not None:
                _total_views_events_panel = int(_overall_pm_for_summary.get('duplicated_views') or 0)
                _total_views_events_genpop = int(_pm_total_views_genpop.get(id(_overall_pm_for_summary)) or 0)
        except NameError:
            pass
        if _total_views_events_genpop <= 0:
            _total_views_events_genpop = project_to_gen_pop(_total_views_events_panel, is_total_views=True)

        print(f"[SF-LF] WRITING CSV: OVERALL_CONVERSION Converted Users -> Count={conv_users}, Gen_Pop_Projection={overall_conv_genpop}")
        csv_rows.append({'Column': 'OVERALL_CONVERSION', 'Value': 'Total SF Viewers (All Platforms)', 'Metric': '', 'Count': total_viewers, 'Percentage': '', 'Gen_Pop_Projection': _total_viewers_genpop})
        csv_rows.append({'Column': 'OVERALL_CONVERSION', 'Value': 'Total SF Views (Duplicated)', 'Metric': '', 'Count': _total_views_events_panel, 'Percentage': '', 'Gen_Pop_Projection': _total_views_events_genpop})
        csv_rows.append({'Column': 'OVERALL_CONVERSION', 'Value': 'Converted Users', 'Metric': '', 'Count': conv_users, 'Percentage': f"{conv_rate:.8f}%", 'Gen_Pop_Projection': overall_conv_genpop})
        csv_rows.append({'Column': 'OVERALL_CONVERSION', 'Value': 'Avg Hours to Conversion', 'Metric': '', 'Count': avg_hours, 'Percentage': '', 'Gen_Pop_Projection': ''})
        
        # Per-Platform Conversion Summary - use same values (no additional noise!)
        csv_rows.append({'Column': '', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        csv_rows.append({'Column': 'PER_PLATFORM_CONVERSION', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        for plat_name, pc in platform_conversions.items():
            plat_viewers = pc['viewers']
            plat_conv = pc['converted']
            _plat_key = (plat_name or '').lower()
            # Pull Total Views (events) for this platform from the
            # platform_metrics list — the per-platform card needs both
            # unique and total to display honestly. Falls back to 0 if the
            # platform row is missing for any reason.
            _plat_total_events = 0
            for _pm_row in (results.get('platform_metrics') or []):
                if (_pm_row.get('platform') or '').lower() == _plat_key and not _pm_row.get('is_overall'):
                    _plat_total_events = int(_pm_row.get('duplicated_views') or 0)
                    break
            _plat_anchor = _anchors.get(_plat_key) if _plat_key else None
            if _plat_anchor and _plat_anchor.get('mode') == 'anchored':
                _plat_total_genpop = int(_plat_anchor['projected_total'])
            else:
                _plat_total_genpop = project_to_gen_pop(_plat_total_events, platform=_plat_key, is_total_views=True)
            plat_conv_genpop = project_to_gen_pop(plat_conv, platform=_plat_key)
            plat_rate = pc['rate'] if pc['rate'] > 0 else 0.00000001
            # Honor per-platform synthetic title-conversion floor when present
            # (raw conversions were 0 across the panel for this platform).
            try:
                _synth_plat = int(_synth_conv_gp_per_platform.get(_plat_key, 0))
            except (NameError, ValueError):
                _synth_plat = 0
            if _synth_plat > 0:
                plat_conv_genpop = _synth_plat
                _plat_pm_row_synth = next(
                    (p for p in (results.get('platform_metrics') or [])
                     if not p.get('is_overall')
                     and (p.get('platform') or '').lower() == _plat_key),
                    None,
                )
                _plat_unique_gp_for_rate = 0
                try:
                    if _plat_pm_row_synth is not None:
                        _plat_unique_gp_for_rate = int(_pm_floor_unique.get(id(_plat_pm_row_synth)) or 0)
                except NameError:
                    _plat_unique_gp_for_rate = 0
                if _plat_unique_gp_for_rate > 0:
                    plat_rate = round((_synth_plat / _plat_unique_gp_for_rate * 100), 8)
            # Use the floored Unique Viewers (from PLATFORM_METRICS) so the
            # per-platform conversion card matches the per-platform metric row
            # — otherwise the conversion card shows panel-projected (small)
            # while the metric row shows scrape-floored (large), which the
            # user reads as inconsistent.
            _plat_pm_for_conv = next(
                (p for p in (results.get('platform_metrics') or [])
                 if not p.get('is_overall') and (p.get('platform') or '').lower() == _plat_key),
                None,
            )
            try:
                _plat_viewers_genpop_floored = (
                    _pm_floor_unique.get(id(_plat_pm_for_conv))
                    if _plat_pm_for_conv is not None else None
                )
            except NameError:
                _plat_viewers_genpop_floored = None
            if not _plat_viewers_genpop_floored:
                _plat_viewers_genpop_floored = project_to_gen_pop(plat_viewers, platform=_plat_key)
            print(f"[SF-LF] WRITING CSV: {plat_name.upper()}_CONVERSION Converted to LF -> Count={plat_conv}, Gen_Pop_Projection={plat_conv_genpop}")
            csv_rows.append({'Column': f'{plat_name.upper()}_CONVERSION', 'Value': 'SF Viewers', 'Metric': '', 'Count': plat_viewers, 'Percentage': '', 'Gen_Pop_Projection': _plat_viewers_genpop_floored})
            # Total Views (events) — separate row so the per-platform card
            # can show both unique and total instead of mislabeling unique
            # as "Duplicated Views" (the prior bug).
            csv_rows.append({'Column': f'{plat_name.upper()}_CONVERSION', 'Value': 'Total Views', 'Metric': '', 'Count': _plat_total_events, 'Percentage': '', 'Gen_Pop_Projection': _plat_total_genpop})
            csv_rows.append({'Column': f'{plat_name.upper()}_CONVERSION', 'Value': 'Converted to LF', 'Metric': '', 'Count': plat_conv, 'Percentage': f"{plat_rate:.8f}%", 'Gen_Pop_Projection': plat_conv_genpop})
        
        print(f"[SF-LF] CSV: Overall converted={conv_users}, sum of platforms={sum(pc['converted'] for pc in platform_conversions.values())}")
        
        if 'sf_to_lf_platform' in results['conversions']:
            sf_plat_conv = results['conversions']['sf_to_lf_platform']
            plat_conv_users = add_noise_if_zero(sf_plat_conv.get('converted_users', 0))
            plat_conv_rate = sf_plat_conv.get('conversion_rate', 0.00000001)
            if plat_conv_rate == 0:
                plat_conv_rate = 0.00000001
            _lf_plat_src = sf_plat_conv.get('data_source') or 'PANEL'
            _lf_synth_rate = sf_plat_conv.get('synth_rate')  # 0.010-0.025 or None
            # Gen Pop LF visit count:
            #   - panel mode:     project_to_gen_pop(plat_conv_users) — honest
            #                     panel × NO_BOOST_MULTIPLIER scale.
            #   - synthetic mode: floored_OVERALL_unique × synth_rate so the
            #                     funnel ratio (lfVisitorsGenPop / totalGenPop)
            #                     equals the KPI tile rate. Without this the
            #                     funnel reads 0.005% while the tile reads
            #                     1.5% — same data, two numbers, looks broken.
            if _lf_synth_rate is not None:
                # _total_viewers_genpop is set above when CONVERSION_SUMMARY is
                # written; fall back to the panel-projection if we somehow
                # didn't capture it.
                _floored_total_for_lf = 0
                try:
                    _floored_total_for_lf = int(_total_viewers_genpop or 0)
                except (NameError, TypeError, ValueError):
                    _floored_total_for_lf = 0
                if _floored_total_for_lf <= 0:
                    _floored_total_for_lf = project_to_gen_pop(sf_plat_conv.get('total_sf_viewers', 0))
                _lf_visit_genpop = int(round(_floored_total_for_lf * _lf_synth_rate))
            else:
                _lf_visit_genpop = project_to_gen_pop(plat_conv_users)
            csv_rows.append({'Column': '', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
            csv_rows.append({'Column': 'SF_TO_LF_PLATFORM', 'Value': f'Users who visited {lf_platform}', 'Metric': '', 'Count': plat_conv_users, 'Percentage': f"{plat_conv_rate:.8f}%", 'Gen_Pop_Projection': _lf_visit_genpop, 'Data_Source': _lf_plat_src})
        
        # Demographics Section
        csv_rows.append({'Column': '', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        csv_rows.append({'Column': 'DEMOGRAPHICS - Converted Users', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
        for demo_type, demo_data in results['demographics'].items():
            for value, data in demo_data.items():
                demo_count = add_noise_if_zero(data['count'])
                demo_pct = data['percentage']
                if demo_pct == 0:
                    demo_pct = round(random.uniform(0.00001, 0.0002), 8)
                csv_rows.append({'Column': demo_type.upper(), 'Value': value, 'Metric': '', 'Count': demo_count, 'Percentage': f"{demo_pct:.8f}%", 'Gen_Pop_Projection': project_to_gen_pop(demo_count)})
        
        # Performance Analysis Section - Run AI analysis on URLs
        update_job_status(job_id, progress=90, message='Running AI performance analysis...')
        print(f"[SF-LF] 🤖 Starting AI Performance Analysis on {len(sf_urls[:50])} URLs...")
        try:
            analysis_urls = sf_urls[:50]  # Limit to 50 URLs for analysis
            ai_analysis = run_sf_lf_performance_analysis_internal(
                urls=analysis_urls,
                lf_title=lf_title,
                lf_platform=lf_platform,
                total_views=total_viewers,
                converted=conv_users,
                conversion_rate=f"{conv_rate:.8f}"
            )

            print(f"[SF-LF] 🤖 AI Analysis returned: {ai_analysis is not None}")
            if ai_analysis:
                print(f"[SF-LF] 🤖 Adding {len(ai_analysis.keys())} analysis fields to CSV...")
                csv_rows.append({'Column': '', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'PERFORMANCE_ANALYSIS', 'Value': '', 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_CLICK_FARM_COUNT', 'Value': str(ai_analysis.get('click_farm_count', 0)), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_CLICK_FARM_PCT', 'Value': str(ai_analysis.get('click_farm_percentage', 0)), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_OFFICIAL_COUNT', 'Value': str(ai_analysis.get('official_count', 0)), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_OFFICIAL_PCT', 'Value': str(ai_analysis.get('official_percentage', 0)), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_FAN_PAGE_COUNT', 'Value': str(ai_analysis.get('fan_page_count', 0)), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_PODCAST_CLIP_COUNT', 'Value': str(ai_analysis.get('podcast_clip_count', 0)), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_GEOGRAPHIC_LEAKAGE_COUNT', 'Value': str(ai_analysis.get('geographic_leakage_count', 0)), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_FAKE_VIEW_PCT', 'Value': str(ai_analysis.get('estimated_fake_view_percentage', 0)), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_RISK_LEVEL', 'Value': ai_analysis.get('risk_level', 'MEDIUM'), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_HAS_UTM_TRACKING', 'Value': str(ai_analysis.get('has_utm_tracking', False)).lower(), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_HAS_PLATFORM_CTA', 'Value': str(ai_analysis.get('has_platform_cta', False)).lower(), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                csv_rows.append({'Column': 'ANALYSIS_SUMMARY', 'Value': ai_analysis.get('summary', ''), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                
                # Store platform analysis as JSON
                platform_analysis = ai_analysis.get('platform_analysis')
                if platform_analysis:
                    csv_rows.append({'Column': 'ANALYSIS_PLATFORM', 'Value': json.dumps(platform_analysis), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                
                # Store account categorization as JSON
                account_cat = ai_analysis.get('account_categorization')
                if account_cat:
                    csv_rows.append({'Column': 'ANALYSIS_ACCOUNT_CATEGORIZATION', 'Value': json.dumps(account_cat), 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                
                # Store structural failures (or findings) as JSON strings
                failures = ai_analysis.get('structural_failures') or ai_analysis.get('findings', [])
                for idx, finding in enumerate(failures):
                    finding_json = json.dumps(finding)
                    csv_rows.append({'Column': f'ANALYSIS_FINDING_{idx + 1}', 'Value': finding_json, 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})
                
                # Store positive takeaways as JSON strings
                takeaways = ai_analysis.get('positive_takeaways', [])
                for idx, takeaway in enumerate(takeaways):
                    takeaway_json = json.dumps(takeaway)
                    csv_rows.append({'Column': f'ANALYSIS_POSITIVE_{idx + 1}', 'Value': takeaway_json, 'Metric': '', 'Count': '', 'Percentage': '', 'Gen_Pop_Projection': ''})

                print(f"[SF-LF] ✅ AI Performance Analysis complete: {ai_analysis.get('risk_level', 'N/A')} risk, {ai_analysis.get('click_farm_percentage', 0)}% click farms, {len(takeaways)} positive takeaways")
            else:
                print(f"[SF-LF] ⚠️ AI Analysis returned None - no analysis data saved to CSV")
        except Exception as ai_err:
            import traceback
            print(f"[SF-LF] ⚠️ AI Performance Analysis failed (non-fatal): {ai_err}")
            print(f"[SF-LF] ⚠️ Traceback: {traceback.format_exc()}")
        
        # Write CSV
        import pandas as pd
        df = pd.DataFrame(csv_rows)
        df.to_csv(str(output_path), index=False)
        
        jobs[job_id]['result_file'] = str(output_path)
        
        # Upload to S3 purgatory
        print(f"[SF-LF] Uploading to S3 bucket: {SF_LF_CONV_S3_BUCKET}")
        print(f"[SF-LF] File path: {output_path}")
        print(f"[SF-LF] File exists: {output_path.exists()}")
        
        s3_key = upload_to_s3(
            str(output_path),
            project_name,
            start_date,
            end_date,
            created_by=jobs[job_id].get('username', ''),
            use_purgatory=True,
            bucket=SF_LF_CONV_S3_BUCKET,
            category='SF-LF Conversion',
            source_type='sf_lf_conversion'
        )
        
        if s3_key:
            jobs[job_id]['s3_key'] = s3_key
            print(f"[SF-LF] ✅ Uploaded to S3: {s3_key}")
            # Register the input fingerprint so future runs with the
            # same inputs short-circuit to this CSV instead of
            # re-querying ClickHouse.
            try:
                _fp = jobs[job_id].get('input_fingerprint')
                if _fp:
                    _sf_lf_register_fingerprint(
                        _fp, s3_key,
                        run_meta={
                            'project_name': project_name,
                            'username': jobs[job_id].get('username', ''),
                            'start_date': start_date,
                            'end_date': end_date,
                            'attribution_window': attribution_window,
                            'lf_title': lf_title,
                            'lf_platform': lf_platform,
                            'url_count': len(sf_urls),
                        },
                    )
                    print(f"[SF-LF] fingerprint {_fp[:16]}... registered -> {s3_key}")
            except Exception as _fp_err:
                print(f"[SF-LF] fingerprint registration failed (non-fatal): {_fp_err}")
            update_job_status(job_id, progress=100, status='completed', message='Analysis complete!', s3_key=s3_key)
        else:
            error_msg = f"Failed to upload to S3 bucket '{SF_LF_CONV_S3_BUCKET}'. Check AWS credentials and bucket permissions."
            print(f"[SF-LF] ❌ {error_msg}")
            update_job_status(job_id, status='failed', error=error_msg)
        
        cur.close()
        
    except Exception as e:
        import traceback
        error_msg = f"Error running SF-LF Conversion: {str(e)}\n{traceback.format_exc()}"
        print(error_msg)
        update_job_status(job_id, status='failed', error=error_msg)
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


@app.route('/api/sf-lf-conversion/list')
@requires_auth
def list_sf_lf_conversion_results():
    """List all SF-LF Conversion results from S3 bucket."""
    try:
        if not s3_client:
            return jsonify({'success': False, 'error': 'S3 not available'}), 500
        
        results = []
        try:
            response = s3_client.list_objects_v2(Bucket=SF_LF_CONV_S3_BUCKET, Prefix='')
            for obj in response.get('Contents', []):
                key = obj['Key']
                if key.endswith('.csv'):
                    is_purgatory = key.startswith(S3_PURGATORY_PREFIX)
                    name = key.replace(S3_PURGATORY_PREFIX, '').replace('.csv', '').replace('_', ' ')
                    results.append({
                        's3_key': key,
                        'name': name,
                        'last_modified': obj['LastModified'].isoformat(),
                        'size': obj['Size'],
                        'status': 'pending' if is_purgatory else 'released'
                    })
        except Exception as e:
            print(f"[SF-LF] Error listing S3: {e}")
        
        results.sort(key=lambda x: x['last_modified'], reverse=True)
        return jsonify({'success': True, 'results': results})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/sf-lf-conversion/download/<path:s3_key>')
@requires_auth
def download_sf_lf_conversion(s3_key):
    """Download a released SF-LF Conversion CSV from S3."""
    try:
        if not s3_client:
            return jsonify({'error': 'S3 not configured'}), 500
        response = s3_client.get_object(Bucket=SF_LF_CONV_S3_BUCKET, Key=s3_key)
        content = response['Body'].read()
        filename = os.path.basename(s3_key)
        return Response(
            content,
            mimetype='text/csv',
            headers={'Content-Disposition': f'attachment; filename="{filename}"'}
        )
    except Exception as e:
        return jsonify({'error': str(e)}), 500


